import React, { useMemo } from 'react';
import { Expense, PaymentMethod, WalletConfig, CategoryConfig } from '../types';
import { 
  PieChart, Pie, Cell, Tooltip, ResponsiveContainer 
} from 'recharts';
import { Wallet, Calendar, Target, Zap, Fuel, CreditCard, Clock, ChevronRight, TrendingUp, TrendingDown, SlidersHorizontal } from 'lucide-react';
import { format, isSameMonth, isBefore } from 'date-fns';
import { it, enUS } from 'date-fns/locale';
import { translations } from '../utils/i18n';

interface DashboardProps {
  expenses: Expense[];
  budget: number;
  userName?: string;
  currency?: string;
  wallets: WalletConfig[];
  categories: CategoryConfig[];
  lang?: 'it' | 'en';
  onAdjustment?: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  expenses, 
  budget, 
  userName = 'Utente', 
  currency = '€', 
  wallets, 
  categories, 
  lang = 'it',
  onAdjustment
}) => {
  const t = translations[lang].dashboard;
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const currentMonthDate = new Date();

  const parseDate = (dateStr: string) => {
    const [y, m, d] = dateStr.split('-').map(Number);
    return new Date(y, m - 1, d);
  };

  // Filtro spese del mese corrente
  const currentMonthExpenses = useMemo(() => {
    return expenses.filter(e => {
      // Replaced parseISO with custom parseDate
      const expenseDate = parseDate(e.date);
      return isSameMonth(expenseDate, currentMonthDate);
    });
  }, [expenses, currentMonthDate]);

  // CALCOLO TOTALE "CASH FLOW" 
  // Include uscite da Bancomat (spese dirette + ricariche) e Contanti.
  // Esclude esplicitamente gli aggiustamenti e le modifiche.
  const totalCurrentMonth = useMemo(() => {
    return currentMonthExpenses
      .filter(e => 
        (e.paymentMethod === PaymentMethod.Bancomat || e.paymentMethod === PaymentMethod.Contanti) && 
        !e.description.toLowerCase().includes('aggiustamento') &&
        !e.description.toLowerCase().includes('modifica')
      )
      .reduce((sum, e) => sum + e.amount, 0);
  }, [currentMonthExpenses]);

  // Totale mese scorso con la stessa logica
  const totalLastMonth = useMemo(() => {
    // Replaced subMonths with native date manipulation
    const lastMonthDate = new Date(currentMonthDate.getFullYear(), currentMonthDate.getMonth() - 1, 1);

    const lastMonthExpenses = expenses.filter(e => isSameMonth(parseDate(e.date), lastMonthDate));
    return lastMonthExpenses
      .filter(e => 
        (e.paymentMethod === PaymentMethod.Bancomat || e.paymentMethod === PaymentMethod.Contanti) && 
        !e.description.toLowerCase().includes('aggiustamento') &&
        !e.description.toLowerCase().includes('modifica')
      )
      .reduce((sum, e) => sum + e.amount, 0);
  }, [expenses, currentMonthDate]);

  const diff = totalLastMonth > 0 ? ((totalCurrentMonth - totalLastMonth) / totalLastMonth) * 100 : 0;
  const budgetProgress = Math.min((totalCurrentMonth / budget) * 100, 100);

  // LOGICA SALDI WALLET
  const balances = useMemo(() => {
    return wallets.map(w => {
      const totalIn = expenses
        .filter(e => {
          const desc = e.description.toLowerCase();
          const name = w.name.toLowerCase();
          const isAdjustment = desc.includes('aggiustamento') || desc.includes('modifica');
          return (desc.includes(`ricarica ${name}`) || (isAdjustment && desc.includes(name))) && e.paymentMethod !== w.method;
        })
        .reduce((sum, e) => sum + e.amount, 0);

      const totalOut = expenses
        .filter(e => {
          const isWalletMethod = e.paymentMethod === w.method;
          const isNotRefill = !e.description.toLowerCase().includes('ricarica');
          const expenseDate = parseDate(e.date);
          const isNotPast = !isBefore(expenseDate, today);
          return isWalletMethod && isNotRefill && isNotPast;
        })
        .reduce((sum, e) => sum + e.amount, 0);

      const calculatedBalance = Math.max(0, totalIn - totalOut);

      return {
        ...w,
        value: Math.max(0, calculatedBalance + (w.balanceOffset || 0)),
        icon: w.icon === 'zap' ? <Zap size={14} /> : w.icon === 'fuel' ? <Fuel size={14} /> : <CreditCard size={14} />,
        color: w.icon === 'zap' ? 'text-emerald-500' : 'text-blue-500'
      };
    });
  }, [expenses, wallets, today]);

  // DATI GRAFICO CATEGORIE
  const categoryData = useMemo(() => {
    // Include le ricariche (che non hanno 'aggiustamento' o 'modifica' nella descrizione)
    const realSpending = currentMonthExpenses.filter(e => 
      !e.description.toLowerCase().includes('aggiustamento') &&
      !e.description.toLowerCase().includes('modifica')
    );

    const data: Record<string, number> = {};
    realSpending.forEach(e => {
      data[e.category] = (data[e.category] || 0) + e.amount;
    });
    return Object.entries(data)
      .map(([name, value]) => ({ name, value }))
      .filter(item => item.value > 0)
      .sort((a, b) => b.value - a.value);
  }, [currentMonthExpenses]);

  const getCategoryColor = (catName: string) => categories.find(c => c.name === catName)?.color || '#9ca3af';
  const formatValue = (val: number) => `${currency}${val.toLocaleString('it-IT', { minimumFractionDigits: 2 })}`;
  const dateLocale = lang === 'en' ? enUS : it;

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="mb-2">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white">{t.hello}, {userName}! 👋</h2>
        <p className="text-gray-500 dark:text-gray-400 text-sm">{t.subtitle}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="md:col-span-2 bg-emerald-500 p-8 rounded-[2rem] text-white shadow-xl shadow-emerald-200/50 relative overflow-hidden">
          <div className="flex justify-between items-start mb-6">
            <div className="flex-1">
              <p className="text-emerald-50 text-xs font-bold uppercase tracking-wider mb-1">{t.spentThisMonth}</p>
              <div className="flex items-center gap-4">
                <h2 className="text-4xl font-black">{formatValue(totalCurrentMonth)}</h2>
              </div>
              <p className="text-emerald-100 text-[10px] mt-1 font-medium">(Uscite Bancomat, Contanti & Ricariche)</p>
            </div>
            <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-sm shrink-0"><CreditCard size={24} /></div>
          </div>
          <div className="space-y-2">
            <div className="flex justify-between text-xs font-medium text-emerald-50">
              <span>{t.target}: {currency}{budget.toLocaleString('it-IT')}</span>
              <span>{Math.round(budgetProgress)}%</span>
            </div>
            <div className="h-2 w-full bg-white/20 rounded-full overflow-hidden">
              <div className="h-full bg-white transition-all duration-1000" style={{ width: `${budgetProgress}%` }}></div>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 flex items-center gap-4 shadow-sm">
            <div className={`p-3 rounded-2xl ${diff <= 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
              {diff <= 0 ? <TrendingDown size={20} /> : <TrendingUp size={20} />}
            </div>
            <div>
              <p className="text-gray-500 dark:text-gray-400 text-[10px] uppercase font-bold tracking-widest">{t.vsLastMonth}</p>
              <p className={`font-black text-lg ${diff <= 0 ? 'text-emerald-600' : 'text-red-500'}`}>
                {diff > 0 ? '+' : ''}{diff.toFixed(1)}%
              </p>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 flex items-center gap-4 shadow-sm">
            <div className="text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 p-3 rounded-2xl"><Calendar size={20} /></div>
            <div>
              <p className="text-gray-500 dark:text-gray-400 text-[10px] uppercase font-bold tracking-widest">{t.month}</p>
              <p className="font-black text-lg dark:text-white capitalize">{format(currentMonthDate, "MMMM", { locale: dateLocale })}</p>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm overflow-x-auto">
        <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4 ml-2">Saldi Attuali Portafogli</h3>
        <div className="flex gap-4 px-2">
          {balances.map((wallet) => (
            <div key={wallet.name} className="flex-shrink-0 w-40 p-4 rounded-2xl bg-emerald-50/50 dark:bg-gray-700/50 border border-emerald-100/50 dark:border-gray-600">
              <div className="flex justify-between items-center mb-2">
                <div className={wallet.color}>{wallet.icon}</div>
                <span className="text-[8px] font-bold text-gray-400 uppercase">{wallet.name}</span>
              </div>
              <p className="font-bold dark:text-white">{currency}{wallet.value.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <div className="flex justify-between items-center mb-6">
             <h3 className="text-lg font-bold dark:text-white">Analisi Categorie</h3>
             <span className="text-[10px] text-gray-400 uppercase font-bold tracking-wider bg-gray-50 dark:bg-gray-700 px-2 py-1 rounded-lg">Consumo Reale</span>
          </div>
          <div className="w-full h-[250px]">
            {categoryData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={categoryData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                    {categoryData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={getCategoryColor(entry.name)} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(value: number) => [`${currency}${value.toLocaleString('it-IT', { minimumFractionDigits: 2 })}`, 'Importo']} />
                </PieChart>
              </ResponsiveContainer>
            ) : <div className="h-full flex items-center justify-center text-gray-400">Nessuna spesa rilevante</div>}
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-bold dark:text-white mb-6">Top Spese</h3>
          <div className="space-y-4">
            {categoryData.slice(0, 5).map((entry) => (
              <div key={entry.name} className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-3 h-3 rounded-full" style={{ backgroundColor: getCategoryColor(entry.name) }}></div>
                  <span className="text-sm dark:text-gray-300">{entry.name}</span>
                </div>
                <span className="text-sm font-bold dark:text-white">{formatValue(entry.value)}</span>
              </div>
            ))}
            {categoryData.length === 0 && <p className="text-gray-400 text-sm">Nessuna spesa da mostrare.</p>}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Expense, PaymentMethod, WalletConfig, CategoryConfig } from '../types';
import { 
  Trash2, Search, Filter, Edit2, AlertCircle, 
  Cigarette, Fuel, Car, Zap, Gamepad2, Heart, Repeat, ShoppingBag, Utensils,
  CreditCard, SlidersHorizontal
} from 'lucide-react';
import { format, isFuture } from 'date-fns';
import { it } from 'date-fns/locale';

interface ExpenseListProps {
  expenses: Expense[];
  onDelete: (id: string) => void;
  onEdit: (expense: Expense) => void;
  currency?: string;
  wallets: WalletConfig[];
  categories: CategoryConfig[];
}

export const ExpenseList: React.FC<ExpenseListProps> = ({ expenses, onDelete, onEdit, currency = '€', wallets, categories }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('Tutti');
  const [filterMethod, setFilterMethod] = useState<string>('Tutti');

  const filteredExpenses = expenses
    .filter(e => {
      // FILTRO 1: Nascondi SEMPRE gli aggiustamenti/modifiche tecniche dalla lista
      // Queste sono operazioni di sistema sui saldi, non spese reali.
      const desc = e.description.toLowerCase();
      const isAdjustment = desc.includes('aggiustamento') || desc.includes('modifica saldo') || (desc.includes('modifica') && desc.includes('contanti'));

      if (isAdjustment) return false;

      // FILTRO 2: Ricerca testuale
      const matchesSearch = desc.includes(searchTerm.toLowerCase());

      // FILTRO 3: Categoria
      const matchesCategory = filterCategory === 'Tutti' || e.category === filterCategory;

      // FILTRO 4: Metodo di Pagamento
      const matchesMethod = filterMethod === 'Tutti' || e.paymentMethod === filterMethod;

      return matchesSearch && matchesCategory && matchesMethod;
    })
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  // Funzione per ottenere l'icona in base alla categoria
  const getCategoryIcon = (categoryName: string) => {
    const lower = categoryName.toLowerCase();

    if (lower.includes('sigarett') || lower.includes('tabacco') || lower.includes('iqos')) return <Cigarette size={20} />;
    if (lower.includes('benzina') || lower.includes('diesel') || lower.includes('carburante')) return <Fuel size={20} />;
    if (lower.includes('autostrada') || lower.includes('auto') || lower.includes('parcheggio') || lower.includes('telepass')) return <Car size={20} />;
    if (lower.includes('ricarica') || lower.includes('luce') || lower.includes('energia')) return <Zap size={20} />;
    if (lower.includes('svago') || lower.includes('cinema') || lower.includes('gioc') || lower.includes('bar')) return <Gamepad2 size={20} />;
    if (lower.includes('salute') || lower.includes('farmacia') || lower.includes('medic') || lower.includes('dott')) return <Heart size={20} />;
    if (lower.includes('abbonament') || lower.includes('netflix') || lower.includes('spotify') || lower.includes('sub')) return <Repeat size={20} />;
    if (lower.includes('cibo') || lower.includes('ristorant') || lower.includes('pranzo') || lower.includes('cena') || lower.includes('spesa')) return <Utensils size={20} />;

    return <ShoppingBag size={20} />;
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row gap-4 mb-6">
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Cerca tra le spese..." 
            value={searchTerm} 
            onChange={(e) => setSearchTerm(e.target.value)} 
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-gray-200 dark:border-gray-700 dark:bg-gray-800 dark:text-white focus:ring-2 focus:ring-emerald-500 outline-none transition-all" 
          />
        </div>

        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
            {/* Filtro Metodo Pagamento */}
            <div className="relative min-w-[160px]">
              <select 
                value={filterMethod} 
                onChange={(e) => setFilterMethod(e.target.value)} 
                className="w-full px-4 py-3 rounded-xl border border-gray-200 dark:border-gray-700 dark:bg-gray-800 dark:text-white outline-none bg-white appearance-none cursor-pointer pr-10 truncate text-sm font-medium"
              >
                <option value="Tutti">Metodo: Tutti</option>
                <option value="Bancomat">Bancomat</option>
                {wallets.map(w => <option key={w.id} value={w.method}>{w.name}</option>)}
              </select>
              <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                <CreditCard size={14} />
              </div>
            </div>

            {/* Filtro Categoria */}
            <div className="relative min-w-[160px]">
              <select 
                value={filterCategory} 
                onChange={(e) => setFilterCategory(e.target.value)} 
                className="w-full px-4 py-3 rounded-xl border border-gray-200 dark:border-gray-700 dark:bg-gray-800 dark:text-white outline-none bg-white appearance-none cursor-pointer pr-10 truncate text-sm font-medium"
              >
                <option value="Tutti">Cat: Tutte</option>
                {categories.map(cat => <option key={cat.id} value={cat.name}>{cat.name}</option>)}
              </select>
              <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                <Filter size={14} />
              </div>
            </div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-[2rem] border border-emerald-100 dark:border-gray-700 overflow-hidden shadow-sm">
        {filteredExpenses.length > 0 ? (
          <div className="divide-y divide-emerald-50 dark:divide-gray-700">
            {filteredExpenses.map((expense) => {
              const expenseDate = new Date(expense.date);
              const isDateInFuture = isFuture(expenseDate);

              return (
                <div 
                  key={expense.id} 
                  className={`p-4 flex items-center justify-between hover:bg-emerald-50/30 dark:hover:bg-gray-700/30 transition-colors ${isDateInFuture ? 'bg-red-50/20' : ''}`}
                >
                  <div className="flex items-center gap-3 md:gap-4 overflow-hidden flex-1 min-w-0">
                    <div className={`shrink-0 w-10 h-10 md:w-12 md:h-12 rounded-2xl flex items-center justify-center font-bold transition-colors ${
                      isDateInFuture 
                        ? 'bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400' 
                        : 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400'
                    }`}>
                      {getCategoryIcon(expense.category)}
                    </div>

                    <div className="overflow-hidden min-w-0 flex-1">
                      <h4 className="font-semibold text-gray-800 dark:text-white truncate text-sm md:text-base pr-2">
                        {expense.description}
                      </h4>
                      <div className="flex flex-wrap items-center gap-1.5 mt-1 text-[10px] font-medium text-gray-400">
                        {isDateInFuture && <AlertCircle size={10} className="text-red-500" />}
                        <span className={`whitespace-nowrap ${isDateInFuture ? "text-red-500" : ""}`}>{format(expenseDate, 'dd MMM yyyy', { locale: it })}</span>
                        <span>•</span>
                        <span className="text-emerald-600 dark:text-emerald-400 truncate">{expense.category}</span>
                        <span>•</span>
                        <span className="truncate">{expense.paymentMethod}</span>
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-3 shrink-0 ml-2">
                    <span className={`font-bold text-base md:text-lg whitespace-nowrap ${isDateInFuture ? 'text-red-500' : 'text-gray-800 dark:text-white'}`}>
                      {currency}{expense.amount.toLocaleString('it-IT', { minimumFractionDigits: 2 })}
                    </span>

                    <div className="flex items-center bg-gray-50 dark:bg-gray-700/50 rounded-full p-1 border border-gray-100 dark:border-gray-600">
                      <button 
                        type="button"
                        onClick={() => onEdit(expense)} 
                        className="w-8 h-8 md:w-10 md:h-10 flex items-center justify-center text-gray-400 hover:text-emerald-500 hover:bg-white dark:hover:bg-gray-800 rounded-full transition-all"
                        title="Modifica"
                      >
                        <Edit2 size={14} className="md:w-4 md:h-4" />
                      </button>
                      <button 
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          onDelete(expense.id);
                        }} 
                        className="w-8 h-8 md:w-10 md:h-10 flex items-center justify-center text-gray-400 hover:text-red-600 hover:bg-white dark:hover:bg-gray-800 rounded-full transition-all active:scale-90"
                        title="Elimina"
                      >
                        <Trash2 size={16} className="md:w-[18px] md:h-[18px]" />
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="p-12 text-center">
            <div className="bg-gray-50 dark:bg-gray-700/30 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300">
              <Search size={32} />
            </div>
            <p className="text-gray-400 font-medium">Nessuna spesa trovata.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export enum PaymentMethod {
  Contanti = 'Contanti',
  Flash = 'Prepagata Flash',
  Revolut = 'Prepagata Revolut',
  AppQ8 = 'App Q8',
  Bancomat = 'Bancomat',
  Wallet4 = 'Wallet Extra 1',
  Wallet5 = 'Wallet Extra 2',
  Wallet6 = 'Wallet Extra 3'
}

export interface CategoryConfig {
  id: string;
  name: string;
  isSubscriptionDefault?: boolean;
  color?: string;
}

export type ProfileType = 'personal' | 'joint';

export interface Expense {
  id: string;
  description: string;
  amount: number;
  category: string;
  paymentMethod: PaymentMethod;
  date: string;
  isSubscription?: boolean;
  profile?: ProfileType; // Nuovo campo per distinguere il profilo
}

export interface WalletConfig {
  id: string;
  name: string;
  method: PaymentMethod;
  icon: 'zap' | 'wallet' | 'fuel' | 'credit-card';
  balanceOffset?: number; // Saldo manuale (offset)
}

export interface UserSettings {
  name: string;
  monthlyBudget: number; // Budget Personale
  jointBudget?: number;  // Budget Cointestato
  currency: string;
  isDarkMode: boolean;
  wallets: WalletConfig[];
  categories: CategoryConfig[];
  language: 'it' | 'en';
  lastBudgetUpdate?: string; // Data update personale
  lastJointBudgetUpdate?: string; // Data update cointestato
  currentProfile: ProfileType; // Profilo attualmente selezionato
  monthlyOffset?: number; // Offset manuale per il totale spese mensile
}

export interface AiInsight {
  title: string;
  advice: string;
  type: 'saving' | 'warning' | 'tip';
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ExpenseList } from './components/ExpenseList';
import { ExpenseForm } from './components/ExpenseForm';
import { AiInsights } from './components/AiInsights';
import { ReceiptScanner } from './components/ReceiptScanner';
import { SettingsView } from './components/SettingsView';
import { RicaricheView } from './components/RicaricheView';
import { SubscriptionsView } from './components/SubscriptionsView';
import { Auth } from './components/Auth';
import { Expense, UserSettings, PaymentMethod, WalletConfig, CategoryConfig, ProfileType } from './types';
import { Plus, ScanLine, Cloud, Loader2, PiggyBank, PartyPopper, History, CheckCircle2, Trash2, AlertTriangle, Target, ArrowRight } from 'lucide-react';
import { db, auth, supabase } from './services/supabase';
import { format, isSameMonth } from 'date-fns';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [allExpenses, setAllExpenses] = useState<Expense[]>([]); // Tutte le spese
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [successToast, setSuccessToast] = useState<string | null>(null);
  const [showBudgetPrompt, setShowBudgetPrompt] = useState(false);

  const [expenseToDelete, setExpenseToDelete] = useState<string | null>(null);

  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('mintflow_user_settings');
    const defaultWallets: WalletConfig[] = [
      { id: 'w0', name: 'Contanti', method: PaymentMethod.Contanti, icon: 'wallet' },
      { id: 'w1', name: 'Prepagata Flash', method: PaymentMethod.Flash, icon: 'zap' },
      { id: 'w2', name: 'Prepagata Revolut', method: PaymentMethod.Revolut, icon: 'credit-card' },
      { id: 'w3', name: 'App Q8', method: PaymentMethod.AppQ8, icon: 'fuel' }
    ];

    const defaultCategories: CategoryConfig[] = [
      { id: 'c1', name: 'Sigarette', color: '#ef4444' },
      { id: 'c2', name: 'Benzina', color: '#f97316' },
      { id: 'c3', name: 'Autostrada', color: '#eab308' },
      { id: 'c4', name: 'Ricarica Chiavetta', color: '#84cc16' },
      { id: 'c5', name: 'Svago', color: '#06b6d4' },
      { id: 'c6', name: 'Salute', color: '#ec4899' },
      { id: 'c7', name: 'Abbonamenti', isSubscriptionDefault: true, color: '#8b5cf6' },
      { id: 'c8', name: 'Altro', color: '#64748b' }
    ];

    const defaultSettings: UserSettings = {
      name: 'Utente',
      monthlyBudget: 1000,
      jointBudget: 1500, // Default per cointestato
      currency: '€',
      isDarkMode: false,
      wallets: defaultWallets,
      categories: defaultCategories,
      language: 'it',
      currentProfile: 'personal',
      monthlyOffset: 0
    };

    if (!saved) return defaultSettings;

    try {
      const parsed = JSON.parse(saved);
      const merged = { 
        ...defaultSettings, 
        ...parsed,
        currentProfile: 'personal',
        jointBudget: parsed.jointBudget || defaultSettings.jointBudget
      };

      if (!merged.wallets.some(w => w.method === PaymentMethod.Contanti)) {
          merged.wallets = [defaultWallets[0], ...merged.wallets];
      }

      return merged;
    } catch {
      return defaultSettings;
    }
  });

  // Gestione Dark Mode (DOM side)
  useEffect(() => {
    if (userSettings.isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [userSettings.isDarkMode]);

  // Filtra spese in base al profilo attivo (ora solo personal)
  const expenses = useMemo(() => {
    return allExpenses.filter(e => (e.profile || 'personal') === 'personal');
  }, [allExpenses]);

  // Budget attuale (solo personale)
  const currentBudget = userSettings.monthlyBudget;

  // Salva le impostazioni ogni volta che cambiano
  useEffect(() => {
    localStorage.setItem('mintflow_user_settings', JSON.stringify(userSettings));
  }, [userSettings]);

  const [activeTab, setActiveTab] = useState<'dashboard' | 'list' | 'ricariche' | 'ai' | 'settings' | 'subscriptions'>('dashboard');
  const [showForm, setShowForm] = useState(false);
  const [prefill, setPrefill] = useState<Partial<Expense> | null>(null);

  // Controllo budget mensile o nuovo utente
  useEffect(() => {
    if (session && !isInitialLoading) {
      const today = new Date();
      const lastUpdateStr = userSettings.lastBudgetUpdate;
      // Replaced parseISO with new Date
      const lastUpdate = lastUpdateStr ? new Date(lastUpdateStr) : null;

      if (!lastUpdate || !isSameMonth(lastUpdate, today)) {
        setShowBudgetPrompt(true);
      }
    }
  }, [session, isInitialLoading, userSettings.lastBudgetUpdate]);

  useEffect(() => {
    const initSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      setSession(session);
      if (session?.user) {
        const metadata = session.user.user_metadata;
        const displayName = metadata.full_name || metadata.display_name || metadata.name || session.user.email?.split('@')[0] || 'Utente';
        setUserSettings(prev => ({ ...prev, name: displayName }));
      }
      setIsInitialLoading(false);
    };
    initSession();
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => subscription.unsubscribe();
  }, []);

  const fetchExpenses = useCallback(async () => {
    if (!session?.user?.id) return;
    try {
      setIsLoading(true);
      const data = await db.getExpenses(session.user.id);
      setAllExpenses(data);
    } catch (err) {
      console.error("Errore caricamento:", err);
    } finally {
      setIsLoading(false);
    }
  }, [session]);

  useEffect(() => {
    if (session?.user?.id) {
      fetchExpenses();
    }
  }, [session, fetchExpenses]);

  const handleSaveExpense = async (expenseData: Omit<Expense, 'id'>) => {
    try {
      setIsSyncing(true);
      const dataToSave = {
        ...expenseData,
        profile: 'personal' as ProfileType
      };

      let savedExpense: Expense | null = null;

      if (prefill?.id) {
        savedExpense = await db.updateExpense(prefill.id, dataToSave);
        if (savedExpense) {
            setAllExpenses(prev => prev.map(e => e.id === savedExpense!.id ? savedExpense! : e));
        }
      } else {
        savedExpense = await db.addExpense(dataToSave, session.user.id);
        if (savedExpense) {
            setAllExpenses(prev => [savedExpense!, ...prev]);
        }
      }
      setShowForm(false);
      setPrefill(null);
      setSuccessToast("Operazione completata!");
      setTimeout(() => setSuccessToast(null), 3000);
    } catch (err: any) {
      alert(`Errore Cloud: ${err.message}`);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleSetMonthlyBudget = (amount: number) => {
    const now = new Date().toISOString();

    setUserSettings(prev => ({
        ...prev,
        monthlyBudget: amount,
        lastBudgetUpdate: now
    }));

    setShowBudgetPrompt(false);
    setSuccessToast("Budget impostato con successo!");
    setTimeout(() => setSuccessToast(null), 3000);
  };

  const handleDeleteAdjustments = async () => {
    if (!session?.user?.id) return;
    if (!window.confirm("Sei sicuro? Questo eliminerà definitivamente tutte le spese che contengono 'Aggiustamento' nel nome.")) return;

    try {
      setIsSyncing(true);
      const adjustments = allExpenses.filter(e => e.description.toLowerCase().includes('aggiustamento'));

      for (const adj of adjustments) {
        await db.deleteExpense(adj.id);
      }

      setAllExpenses(prev => prev.filter(e => !e.description.toLowerCase().includes('aggiustamento')));
      setSuccessToast("Aggiustamenti eliminati!");
      setTimeout(() => setSuccessToast(null), 3000);
    } catch (err: any) {
      alert("Errore durante l'eliminazione: " + err.message);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleImportCSV = async (file: File): Promise<{ imported: number, skipped: number, errors: string[], debugInfo: string }> => {
    if (!session?.user?.id) throw new Error("Utente non autenticato.");

    setIsSyncing(true);
    let importedCount = 0;
    let skippedCount = 0;
    const errors: string[] = [];

    try {
      const text = await file.text();
      const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
      if (lines.length < 1) throw new Error("File vuoto");

      const separator = lines[0].includes(';') ? ';' : ',';
      const headers = lines[0].toLowerCase().split(separator).map(h => h.trim());

      const dateIdx = headers.findIndex(h => h.includes('dat') || h.includes('giorno'));
      const descIdx = headers.findIndex(h => h.includes('desc') || h.includes('causale') || h.includes('testo'));
      const amountIdx = headers.findIndex(h => h.includes('importo') || h.includes('euro') || h.includes('valore') || h.includes('amount'));
      const catIdx = headers.findIndex(h => h.includes('cat'));

      const startLine = (dateIdx === -1 && amountIdx === -1) ? 0 : 1;

      for (let i = startLine; i < lines.length; i++) {
        const parts = lines[i].split(separator).map(p => p.trim().replace(/^"|"$/g, ''));

        try {
          const rawDate = parts[dateIdx === -1 ? 0 : dateIdx];
          const rawDesc = parts[descIdx === -1 ? 1 : descIdx];
          const rawAmount = parts[amountIdx === -1 ? 2 : amountIdx];
          const category = catIdx > -1 ? parts[catIdx] : 'Altro';

          if (!rawDate || !rawAmount) continue;

          let date = "";
          const dateMatch = rawDate.match(/(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})/);
          if (dateMatch) {
            let [_, d, m, y] = dateMatch;
            if (y.length === 2) y = "20" + y;
            date = `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
          } else if (rawDate.match(/^\d{4}-\d{2}-\d{2}$/)) {
            date = rawDate;
          }

          const amount = parseFloat(rawAmount.replace(',', '.').replace(/[^0-9.-]/g, ''));

          if (!date || isNaN(amount)) {
            errors.push(`Riga ${i+1}: Dati non validi (Data: ${rawDate}, Importo: ${rawAmount})`);
            continue;
          }

          const isDuplicate = allExpenses.some(e => e.date === date && Math.abs(e.amount - amount) < 0.01 && e.description === rawDesc);
          if (isDuplicate) {
            skippedCount++;
            continue;
          }

          await db.addExpense({
            date,
            description: rawDesc || "Importato",
            amount,
            category: category,
            paymentMethod: PaymentMethod.Contanti,
            isSubscription: false,
            profile: 'personal'
          }, session.user.id);

          importedCount++;
        } catch (e: any) {
          errors.push(`Riga ${i+1}: ${e.message}`);
        }
      }

      if (importedCount > 0) await fetchExpenses();
      return { imported: importedCount, skipped: skippedCount, errors, debugInfo: `Sep: ${separator}` };
    } finally {
      setIsSyncing(false);
    }
  };

  const handleExportCSV = () => {
    const headers = ["Data", "Descrizione", "Importo", "Categoria", "Metodo"];
    const rows = expenses.map(e => [e.date, e.description, e.amount, e.category, e.paymentMethod]);
    const csv = [headers.join(","), ...rows.map(r => r.join(","))].join("\n");
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `spese_personali_${format(new Date(), 'yyyyMMdd')}.csv`;
    a.click();
  };

  const handleUpdateWallets = (newWallets: WalletConfig[]) => {
    setUserSettings(prev => ({ ...prev, wallets: newWallets }));
  };

  if (isInitialLoading) return <div className="min-h-screen flex items-center justify-center bg-mint-50"><Loader2 className="animate-spin text-emerald-500" size={48} /></div>;
  if (!session) return <Auth onSuccess={() => {}} />;

  return (
    <Layout 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        lang={userSettings.language}
        currentProfile={userSettings.currentProfile}
    >
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        {successToast && <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-emerald-600 text-white px-6 py-3 rounded-2xl shadow-xl flex items-center gap-2 animate-in slide-in-from-top-4">{successToast}</div>}

        {activeTab === 'dashboard' && (
          <Dashboard 
            expenses={expenses} 
            budget={currentBudget} 
            userName={userSettings.name} 
            currency={userSettings.currency} 
            wallets={userSettings.wallets} 
            categories={userSettings.categories} 
            lang={userSettings.language}
            userSettings={userSettings}
            onUpdateSettings={setUserSettings}
          />
        )}
        {activeTab === 'list' && (
          <div className="space-y-6">
            <div className="flex gap-3">
              <button onClick={() => { setPrefill(null); setShowForm(true); }} className="flex-1 bg-emerald-500 text-white py-4 rounded-2xl flex items-center justify-center gap-2 font-bold shadow-lg"><Plus size={20} /> Aggiungi</button>
            </div>
            <ExpenseList expenses={expenses} onDelete={id => setExpenseToDelete(id)} onEdit={ex => { setPrefill(ex); setShowForm(true); }} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} />
          </div>
        )}
        {activeTab === 'ricariche' && (
          <RicaricheView 
            onRefill={w => { 
                const sourceMethod = w.method === PaymentMethod.Contanti ? PaymentMethod.Bancomat : PaymentMethod.Contanti;
                setPrefill({ description: `Ricarica ${w.name}`, category: 'Altro', paymentMethod: sourceMethod, date: format(new Date(), 'yyyy-MM-dd') }); 
                setShowForm(true); 
            }} 
            onSaveExpense={handleSaveExpense} 
            onUpdateWallets={handleUpdateWallets}
            expenses={expenses} 
            currency={userSettings.currency} 
            wallets={userSettings.wallets} 
          />
        )}
        {activeTab === 'ai' && <AiInsights expenses={expenses} />}
        {activeTab === 'settings' && <SettingsView settings={userSettings} onUpdate={setUserSettings} onClearData={() => {}} onDeleteAdjustments={handleDeleteAdjustments} onImport={handleImportCSV} onExport={handleExportCSV} expenses={expenses} email={session.user.email} />}
        {activeTab === 'subscriptions' && <SubscriptionsView expenses={expenses} onAddSub={() => { setPrefill({ isSubscription: true }); setShowForm(true); }} onDelete={id => setExpenseToDelete(id)} currency={userSettings.currency} />}

        {showForm && (
          <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[70] flex items-center justify-center p-4">
            <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-md p-8 shadow-2xl relative">
              <button onClick={() => setShowForm(false)} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600">✕</button>
              <h2 className="text-2xl font-bold mb-6 text-gray-800 dark:text-white">{prefill?.id ? 'Modifica' : 'Nuova Spesa'}</h2>
              <ExpenseForm onSubmit={handleSaveExpense} onCancel={() => setShowForm(false)} initialData={prefill || undefined} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} expenses={expenses} />
            </div>
          </div>
        )}

        {showBudgetPrompt && (
          <BudgetPromptModal 
            onConfirm={handleSetMonthlyBudget} 
            initialValue={currentBudget} 
            currency={userSettings.currency}
            isNewUser={!userSettings.lastBudgetUpdate}
          />
        )}

        {expenseToDelete && (
          <div className="fixed inset-0 z-[120] flex items-center justify-center p-6 bg-black/20 backdrop-blur-sm">
            <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-xs p-8 shadow-2xl text-center">
              <div className="bg-red-100 text-red-600 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4"><Trash2 size={32} /></div>
              <h3 className="text-xl font-bold mb-2">Elimina?</h3>
              <div className="flex flex-col gap-3 mt-6">
                <button onClick={async () => { await db.deleteExpense(expenseToDelete); setAllExpenses(prev => prev.filter(e => e.id !== expenseToDelete)); setExpenseToDelete(null); }} className="w-full py-4 bg-red-500 text-white rounded-2xl font-bold">Elimina</button>
                <button onClick={() => setExpenseToDelete(null)} className="w-full py-3 text-gray-400 font-bold">Annulla</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
};

// Componente Modale per il Prompt del Budget
const BudgetPromptModal: React.FC<{ 
  onConfirm: (amount: number) => void; 
  initialValue: number;
  currency: string;
  isNewUser: boolean;
}> = ({ onConfirm, initialValue, currency, isNewUser }) => {
  const [value, setValue] = useState(initialValue.toString());

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[200] flex items-center justify-center p-4 animate-in fade-in duration-300">
      <div className="bg-white dark:bg-gray-800 rounded-[3rem] w-full max-w-md p-10 shadow-2xl border-4 border-emerald-500 animate-in zoom-in-95 duration-500">
        <div className="bg-emerald-100 dark:bg-emerald-900/30 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 text-emerald-600 shadow-inner">
          <Target size={40} />
        </div>

        <h2 className="text-3xl font-black text-gray-900 dark:text-white text-center mb-2">
          {isNewUser ? 'Benvenuto!' : 'Nuovo Mese!'}
        </h2>

        <p className="text-gray-500 dark:text-gray-400 text-center mb-8 font-medium">
          {isNewUser 
            ? `Imposta il budget personale di partenza.` 
            : 'Pianifica le tue finanze per questo mese.'}
        </p>

        <div className="mb-8">
          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-3 ml-2 text-center">Budget Target</label>
          <div className="relative">
             <input 
              autoFocus
              type="number" 
              value={value} 
              onChange={(e) => setValue(e.target.value)}
              className="w-full bg-emerald-50 dark:bg-gray-700 text-gray-900 dark:text-white text-4xl font-black py-6 rounded-3xl text-center outline-none border-2 border-transparent focus:border-emerald-500 transition-all shadow-inner"
            />
            <span className="absolute right-8 top-1/2 -translate-y-1/2 text-emerald-600 dark:text-emerald-400 text-2xl font-bold pointer-events-none opacity-50">
              {currency}
            </span>
          </div>
        </div>

        <button 
          onClick={() => onConfirm(parseFloat(value) || 0)}
          className="w-full bg-emerald-500 hover:bg-emerald-600 text-white py-5 rounded-2xl font-bold flex items-center justify-center gap-3 transition-all shadow-xl shadow-emerald-200 dark:shadow-none text-lg active:scale-95"
        >
          Imposta Budget <ArrowRight size={20} />
        </button>

        {!isNewUser && (
          <button 
            onClick={() => onConfirm(initialValue)}
            className="w-full mt-4 py-2 text-gray-400 dark:text-gray-500 font-bold hover:text-gray-600 transition-colors text-sm"
          >
            Mantieni quello del mese scorso
          </button>
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { Expense, PaymentMethod, WalletConfig, CategoryConfig, UserSettings } from '../types';
import { 
  PieChart, Pie, Cell, Tooltip, ResponsiveContainer 
} from 'recharts';
import { Wallet, Calendar, Target, Zap, Fuel, CreditCard, Clock, ChevronRight, TrendingUp, TrendingDown, SlidersHorizontal, Edit2, X, Check, Loader2 } from 'lucide-react';
import { format, isSameMonth, isBefore, isFuture } from 'date-fns';
import { it, enUS } from 'date-fns/locale';
import { translations } from '../utils/i18n';

interface DashboardProps {
  expenses: Expense[];
  budget: number;
  userName?: string;
  currency?: string;
  wallets: WalletConfig[];
  categories: CategoryConfig[];
  lang?: 'it' | 'en';
  userSettings?: UserSettings;
  onUpdateSettings?: (settings: UserSettings) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  expenses, 
  budget, 
  userName = 'Utente', 
  currency = '€', 
  wallets, 
  categories, 
  lang = 'it',
  userSettings,
  onUpdateSettings
}) => {
  const t = translations[lang].dashboard;
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const currentMonthDate = new Date();
  const [isEditingTotal, setIsEditingTotal] = useState(false);
  const [tempTotal, setTempTotal] = useState('');

  const parseDate = (dateStr: string) => {
    const [y, m, d] = dateStr.split('-').map(Number);
    return new Date(y, m - 1, d);
  };

  // Filtro spese del mese corrente
  const currentMonthExpenses = useMemo(() => {
    return expenses.filter(e => {
      const expenseDate = parseDate(e.date);
      return isSameMonth(expenseDate, currentMonthDate);
    });
  }, [expenses, currentMonthDate]);

  // CALCOLO TOTALE "SPESO QUESTO MESE" 
  // 1. Somma tutte le uscite (spese normali + ricariche)
  // 2. Esclude le date FUTURE (solo oggi o passato)
  // 3. Esclude le modifiche tecniche (aggiustamenti)
  // 4. Include l'offset manuale dell'utente

  const calculatedTotal = useMemo(() => {
    return currentMonthExpenses
      .filter(e => {
         // Escludi date future
         if (isFuture(parseDate(e.date))) return false;

         // Includi Bancomat, Contanti e Ricariche (anche se non esplicitamente Bancomat/Contanti, ma le ricariche sono uscite dal main balance)
         const isStandard = e.paymentMethod === PaymentMethod.Bancomat || e.paymentMethod === PaymentMethod.Contanti;
         const isRefill = e.description.toLowerCase().includes('ricarica');

         // Escludi gli aggiustamenti tecnici
         const isAdjustment = e.description.toLowerCase().includes('aggiustamento') || e.description.toLowerCase().includes('modifica');

         return (isStandard || isRefill) && !isAdjustment;
      })
      .reduce((sum, e) => sum + e.amount, 0);
  }, [currentMonthExpenses]);

  // Totale Visualizzato = Calcolato + Offset Manuale
  const totalCurrentMonth = Math.max(0, calculatedTotal + (userSettings?.monthlyOffset || 0));

  // Totale mese scorso con la stessa logica (senza offset per ora, o servirebbe storico offset)
  const totalLastMonth = useMemo(() => {
    const lastMonthDate = new Date(currentMonthDate.getFullYear(), currentMonthDate.getMonth() - 1, 1);

    const lastMonthExpenses = expenses.filter(e => isSameMonth(parseDate(e.date), lastMonthDate));
    return lastMonthExpenses
      .filter(e => 
        (e.paymentMethod === PaymentMethod.Bancomat || e.paymentMethod === PaymentMethod.Contanti || e.description.toLowerCase().includes('ricarica')) && 
        !e.description.toLowerCase().includes('aggiustamento') &&
        !e.description.toLowerCase().includes('modifica') &&
        !isFuture(parseDate(e.date))
      )
      .reduce((sum, e) => sum + e.amount, 0);
  }, [expenses, currentMonthDate]);

  const diff = totalLastMonth > 0 ? ((totalCurrentMonth - totalLastMonth) / totalLastMonth) * 100 : 0;
  const budgetProgress = Math.min((totalCurrentMonth / budget) * 100, 100);

  // LOGICA SALDI WALLET
  const balances = useMemo(() => {
    return wallets.map(w => {
      const totalIn = expenses
        .filter(e => {
          const desc = e.description.toLowerCase();
          const name = w.name.toLowerCase();
          const isAdjustment = desc.includes('aggiustamento') || desc.includes('modifica');
          return (desc.includes(`ricarica ${name}`) || (isAdjustment && desc.includes(name))) && e.paymentMethod !== w.method;
        })
        .reduce((sum, e) => sum + e.amount, 0);

      const totalOut = expenses
        .filter(e => {
          const isWalletMethod = e.paymentMethod === w.method;
          const isNotRefill = !e.description.toLowerCase().includes('ricarica');
          const expenseDate = parseDate(e.date);
          const isNotPast = !isBefore(expenseDate, today);
          return isWalletMethod && isNotRefill && isNotPast;
        })
        .reduce((sum, e) => sum + e.amount, 0);

      const calculatedBalance = Math.max(0, totalIn - totalOut);

      return {
        ...w,
        value: Math.max(0, calculatedBalance + (w.balanceOffset || 0)),
        icon: w.icon === 'zap' ? <Zap size={14} /> : w.icon === 'fuel' ? <Fuel size={14} /> : <CreditCard size={14} />,
        color: w.icon === 'zap' ? 'text-emerald-500' : 'text-blue-500'
      };
    });
  }, [expenses, wallets, today]);

  // DATI GRAFICO CATEGORIE
  const categoryData = useMemo(() => {
    const realSpending = currentMonthExpenses.filter(e => 
      !e.description.toLowerCase().includes('aggiustamento') &&
      !e.description.toLowerCase().includes('modifica')
    );

    const data: Record<string, number> = {};
    realSpending.forEach(e => {
      data[e.category] = (data[e.category] || 0) + e.amount;
    });
    return Object.entries(data)
      .map(([name, value]) => ({ name, value }))
      .filter(item => item.value > 0)
      .sort((a, b) => b.value - a.value);
  }, [currentMonthExpenses]);

  const getCategoryColor = (catName: string) => categories.find(c => c.name === catName)?.color || '#9ca3af';
  const formatValue = (val: number) => `${currency}${val.toLocaleString('it-IT', { minimumFractionDigits: 2 })}`;
  const dateLocale = lang === 'en' ? enUS : it;

  const handleEditTotalClick = () => {
    setTempTotal(totalCurrentMonth.toFixed(2));
    setIsEditingTotal(true);
  };

  const handleSaveTotal = () => {
    if (!userSettings || !onUpdateSettings) return;

    const target = parseFloat(tempTotal.replace(',', '.'));
    if (isNaN(target) || target < 0) {
      alert("Inserisci un importo valido");
      return;
    }

    // Offset = Desiderato - Calcolato
    const newOffset = target - calculatedTotal;

    onUpdateSettings({
      ...userSettings,
      monthlyOffset: newOffset
    });

    setIsEditingTotal(false);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="mb-2">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white">{t.hello}, {userName}! 👋</h2>
        <p className="text-gray-500 dark:text-gray-400 text-sm">{t.subtitle}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="md:col-span-2 bg-emerald-500 p-8 rounded-[2rem] text-white shadow-xl shadow-emerald-200/50 relative overflow-hidden group">
          <div className="flex justify-between items-start mb-6">
            <div className="flex-1">
              <p className="text-emerald-50 text-xs font-bold uppercase tracking-wider mb-1">{t.spentThisMonth}</p>
              <div className="flex items-center gap-4">
                <h2 className="text-4xl font-black">{formatValue(totalCurrentMonth)}</h2>
                <button 
                  onClick={handleEditTotalClick}
                  className="p-2 bg-white/20 rounded-xl hover:bg-white/30 transition-colors opacity-0 group-hover:opacity-100 backdrop-blur-sm"
                  title="Modifica Totale Manualmente"
                >
                  <Edit2 size={16} className="text-white" />
                </button>
              </div>
              <p className="text-emerald-100 text-[10px] mt-1 font-medium">(Uscite Bancomat, Contanti & Ricariche)</p>
            </div>
            <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-sm shrink-0"><CreditCard size={24} /></div>
          </div>
          <div className="space-y-2">
            <div className="flex justify-between text-xs font-medium text-emerald-50">
              <span>{t.target}: {currency}{budget.toLocaleString('it-IT')}</span>
              <span>{Math.round(budgetProgress)}%</span>
            </div>
            <div className="h-2 w-full bg-white/20 rounded-full overflow-hidden">
              <div className="h-full bg-white transition-all duration-1000" style={{ width: `${budgetProgress}%` }}></div>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 flex items-center gap-4 shadow-sm">
            <div className={`p-3 rounded-2xl ${diff <= 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
              {diff <= 0 ? <TrendingDown size={20} /> : <TrendingUp size={20} />}
            </div>
            <div>
              <p className="text-gray-500 dark:text-gray-400 text-[10px] uppercase font-bold tracking-widest">{t.vsLastMonth}</p>
              <p className={`font-black text-lg ${diff <= 0 ? 'text-emerald-600' : 'text-red-500'}`}>
                {diff > 0 ? '+' : ''}{diff.toFixed(1)}%
              </p>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 flex items-center gap-4 shadow-sm">
            <div className="text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 p-3 rounded-2xl"><Calendar size={20} /></div>
            <div>
              <p className="text-gray-500 dark:text-gray-400 text-[10px] uppercase font-bold tracking-widest">{t.month}</p>
              <p className="font-black text-lg dark:text-white capitalize">{format(currentMonthDate, "MMMM", { locale: dateLocale })}</p>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm overflow-x-auto">
        <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4 ml-2">Saldi Attuali Portafogli</h3>
        <div className="flex gap-4 px-2">
          {balances.map((wallet) => (
            <div key={wallet.name} className="flex-shrink-0 w-40 p-4 rounded-2xl bg-emerald-50/50 dark:bg-gray-700/50 border border-emerald-100/50 dark:border-gray-600">
              <div className="flex justify-between items-center mb-2">
                <div className={wallet.color}>{wallet.icon}</div>
                <span className="text-[8px] font-bold text-gray-400 uppercase">{wallet.name}</span>
              </div>
              <p className="font-bold dark:text-white">{currency}{wallet.value.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <div className="flex justify-between items-center mb-6">
             <h3 className="text-lg font-bold dark:text-white">Analisi Categorie</h3>
             <span className="text-[10px] text-gray-400 uppercase font-bold tracking-wider bg-gray-50 dark:bg-gray-700 px-2 py-1 rounded-lg">Consumo Reale</span>
          </div>
          <div className="w-full h-[250px]">
            {categoryData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={categoryData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                    {categoryData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={getCategoryColor(entry.name)} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(value: number) => [`${currency}${value.toLocaleString('it-IT', { minimumFractionDigits: 2 })}`, 'Importo']} />
                </PieChart>
              </ResponsiveContainer>
            ) : <div className="h-full flex items-center justify-center text-gray-400">Nessuna spesa rilevante</div>}
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-bold dark:text-white mb-6">Top Spese</h3>
          <div className="space-y-4">
            {categoryData.slice(0, 5).map((entry) => (
              <div key={entry.name} className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-3 h-3 rounded-full" style={{ backgroundColor: getCategoryColor(entry.name) }}></div>
                  <span className="text-sm dark:text-gray-300">{entry.name}</span>
                </div>
                <span className="text-sm font-bold dark:text-white">{formatValue(entry.value)}</span>
              </div>
            ))}
            {categoryData.length === 0 && <p className="text-gray-400 text-sm">Nessuna spesa da mostrare.</p>}
          </div>
        </div>
      </div>

      {isEditingTotal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-sm p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold dark:text-white">Modifica Totale Mese</h3>
              <button onClick={() => setIsEditingTotal(false)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>

            <div className="mb-6">
              <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Nuovo Totale Visualizzato</label>
              <input 
                autoFocus
                type="number" 
                inputMode="decimal"
                value={tempTotal} 
                onChange={(e) => setTempTotal(e.target.value)} 
                className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-emerald-400 outline-none font-black text-2xl" 
              />
              <p className="text-[10px] text-gray-400 mt-2 ml-1">*Modifica solo la visualizzazione, non le singole spese.</p>
            </div>

            <button 
              onClick={handleSaveTotal}
              className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 shadow-lg active:scale-95 hover:bg-emerald-600 transition-colors"
            >
              <Check size={20} /> Salva Modifica
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Zap, Wallet, Fuel, Plus, Clock, Info, CreditCard, Edit2, X, Check, Loader2, Banknote } from 'lucide-react';
import { Expense, PaymentMethod, WalletConfig } from '../types';
import { format, isFuture } from 'date-fns';
import { it } from 'date-fns/locale';

interface RicaricheViewProps {
  onRefill: (wallet: WalletConfig) => void;
  onSaveExpense: (expense: Omit<Expense, 'id'>) => Promise<void>;
  onUpdateWallets: (wallets: WalletConfig[]) => void;
  expenses: Expense[];
  currency?: string;
  wallets: WalletConfig[];
}

export const RicaricheView: React.FC<RicaricheViewProps> = ({ onRefill, onSaveExpense, onUpdateWallets, expenses, currency = '€', wallets }) => {
  const [editingWallet, setEditingWallet] = useState<WalletConfig | null>(null);
  const [newBalance, setNewBalance] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const balances = useMemo(() => {
    // Replaced startOfToday with native date
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const parseDate = (dateStr: string) => {
        const [y, m, d] = dateStr.split('-').map(Number);
        return new Date(y, m - 1, d);
    };

    return wallets.map(w => {
      // Ricariche (entrate) + Aggiustamenti/Modifiche Positivi
      const totalRecharged = expenses
        .filter(e => {
          const desc = e.description.toLowerCase();
          const name = w.name.toLowerCase();
          const isInflow = desc.includes(`ricarica ${name}`) || desc.includes(`aggiustamento ${name}`) || desc.includes(`modifica saldo ${name}`) || desc.includes(`modifica ${name}`);
          return isInflow && e.paymentMethod !== w.method;
        })
        .reduce((sum, e) => sum + e.amount, 0);

      // Spese (uscite) - Vengono scalate TUTTE quelle fino ad oggi (compreso)
      // Le spese FUTURE vengono escluse dal calcolo del saldo attuale
      const totalSpent = expenses
        .filter(e => {
          const isWalletMethod = e.paymentMethod === w.method;
          const isNotRefill = !e.description.toLowerCase().includes('ricarica');
          const expenseDate = parseDate(e.date);

          // CRITICAL CHANGE: Exclude ONLY future expenses. Include Past and Today.
          const isNotFuture = !isFuture(expenseDate);

          return isWalletMethod && isNotRefill && isNotFuture;
        })
        .reduce((sum, e) => sum + e.amount, 0);

      const calculatedBalance = Math.max(0, totalRecharged - totalSpent);

      // Il saldo finale è il calcolato + l'offset manuale dell'utente
      return {
        ...w,
        balance: Math.max(0, calculatedBalance + (w.balanceOffset || 0))
      };
    });
  }, [expenses, wallets]);

  const refillExpenses = useMemo(() => {
    return expenses.filter(e => 
      e.description.toLowerCase().includes('ricarica') || e.description.toLowerCase().includes('deposito')
    ).slice(0, 10);
  }, [expenses]);

  const handleEditClick = (wallet: WalletConfig) => {
    const current = balances.find(b => b.id === wallet.id)?.balance || 0;
    setNewBalance(current.toFixed(2));
    setEditingWallet(wallet);
  };

  const handleBalanceUpdate = () => {
    if (!editingWallet) return;
    const target = parseFloat(newBalance.replace(',', '.'));
    if (isNaN(target) || target < 0) {
      alert("Inserisci un importo valido");
      return;
    }

    const currentWalletState = balances.find(b => b.id === editingWallet.id);
    if (!currentWalletState) return;

    // Logica Offset:
    // Saldo Visualizzato = (Transazioni + Offset)
    // Target = (Transazioni + NuovoOffset)
    // NuovoOffset = Target - Transazioni
    // Transazioni = Saldo Visualizzato Attuale - Vecchio Offset

    const currentBalance = currentWalletState.balance;
    const currentOffset = editingWallet.balanceOffset || 0;
    const transactionalBalance = currentBalance - currentOffset;

    const newOffset = target - transactionalBalance;

    setIsSubmitting(true);

    // Aggiorna la configurazione del wallet invece di creare una spesa
    const updatedWallets = wallets.map(w => 
      w.id === editingWallet.id ? { ...w, balanceOffset: newOffset } : w
    );

    onUpdateWallets(updatedWallets);

    setEditingWallet(null);
    setIsSubmitting(false);
  };

  const getWalletIcon = (w: WalletConfig) => {
    if (w.method === PaymentMethod.Contanti) return <Banknote size={20} />;
    if (w.icon === 'zap') return <Zap size={20} />;
    if (w.icon === 'fuel') return <Fuel size={20} />;
    if (w.icon === 'credit-card') return <CreditCard size={20} />;
    return <Wallet size={20} />;
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 relative">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-xl font-bold text-gray-800 dark:text-white mb-2">I tuoi Portafogli</h2>
          <p className="text-gray-500 dark:text-gray-400 text-sm">Il saldo include entrate e uscite fino ad oggi.</p>
        </div>
        <div className="hidden md:flex items-center gap-1 text-[10px] font-bold text-emerald-500 bg-emerald-50 dark:bg-emerald-900/20 px-3 py-1.5 rounded-full border border-emerald-100 dark:border-emerald-800 uppercase tracking-widest">
          <Info size={12} /> Real Balance
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {balances.map((w) => (
          <WalletCard 
            key={w.id}
            name={w.name} 
            balance={w.balance} 
            icon={getWalletIcon(w)} 
            onRefill={() => onRefill(w)} 
            onEdit={() => handleEditClick(w)}
            color={w.method === PaymentMethod.Contanti ? 'emerald' : w.icon === 'zap' ? 'emerald' : w.icon === 'fuel' ? 'orange' : w.icon === 'credit-card' ? 'purple' : 'blue'} 
            currency={currency} 
          />
        ))}
      </div>

      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm transition-colors">
        <div className="flex items-center gap-2 mb-6">
          <Clock className="text-emerald-500" size={20} />
          <h3 className="text-lg font-bold text-gray-800 dark:text-white">Movimenti Portafogli</h3>
        </div>
        <div className="space-y-3">
          {refillExpenses.length > 0 ? (
            refillExpenses.map((expense) => (
              <div key={expense.id} className="flex items-center justify-between p-4 rounded-2xl bg-gray-50 dark:bg-gray-700/50 hover:bg-emerald-50 dark:hover:bg-gray-700 transition-colors">
                <div className="flex items-center gap-4">
                   <div className="w-10 h-10 rounded-xl bg-white dark:bg-gray-800 flex items-center justify-center text-emerald-500 shadow-sm"><Plus size={18} /></div>
                   <div>
                     <p className="font-bold text-gray-800 dark:text-white text-sm">{expense.description}</p>
                     <p className="text-[10px] text-gray-400 dark:text-gray-500 font-medium uppercase tracking-tight">
                       {format(new Date(expense.date), 'dd MMMM yyyy', { locale: it })} • {expense.paymentMethod}
                     </p>
                   </div>
                </div>
                <span className="font-bold text-emerald-600 dark:text-emerald-400">+{currency}{expense.amount.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</span>
              </div>
            ))
          ) : (
            <div className="text-center py-10"><p className="text-gray-400 dark:text-gray-500 text-sm">Nessuna ricarica registrata.</p></div>
          )}
        </div>
      </div>

      {editingWallet && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-sm p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold dark:text-white">Modifica Saldo</h3>
              <button onClick={() => setEditingWallet(null)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>

            <div className="bg-emerald-50 dark:bg-emerald-900/20 p-4 rounded-2xl mb-6 flex items-center gap-3">
              <div className="p-2 bg-white dark:bg-gray-700 rounded-xl text-emerald-500 shadow-sm">
                {getWalletIcon(editingWallet)}
              </div>
              <div>
                <p className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">Portafoglio</p>
                <p className="font-bold text-emerald-700 dark:text-emerald-400">{editingWallet.name}</p>
              </div>
            </div>

            <div className="mb-6">
              <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Nuovo Saldo Attuale</label>
              <input 
                autoFocus
                type="number" 
                inputMode="decimal"
                value={newBalance} 
                onChange={(e) => setNewBalance(e.target.value)} 
                className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-emerald-400 outline-none font-black text-2xl" 
              />
              <p className="text-[10px] text-gray-400 mt-2 ml-1">*Questo modificherà solo il valore visualizzato, senza creare transazioni.</p>
            </div>

            <button 
              onClick={handleBalanceUpdate}
              disabled={isSubmitting}
              className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 shadow-lg active:scale-95 hover:bg-emerald-600 transition-colors"
            >
              {isSubmitting ? <Loader2 className="animate-spin" size={20} /> : <Check size={20} />} Salva Modifica
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

