import React, { useMemo, useState } from 'react';
import { Expense, PaymentMethod, WalletConfig, CategoryConfig, UserSettings } from '../types';
import { 
  PieChart, Pie, Cell, Tooltip, ResponsiveContainer 
} from 'recharts';
import { Wallet, Calendar, Target, Zap, Fuel, CreditCard, Clock, ChevronRight, TrendingUp, TrendingDown, SlidersHorizontal, Edit2, X, Check, Loader2 } from 'lucide-react';
import { format, isSameMonth, isBefore, isFuture } from 'date-fns';
import { it, enUS } from 'date-fns/locale';
import { translations } from '../utils/i18n';

interface DashboardProps {
  expenses: Expense[];
  budget: number;
  userName?: string;
  currency?: string;
  wallets: WalletConfig[];
  categories: CategoryConfig[];
  lang?: 'it' | 'en';
  userSettings?: UserSettings;
  onUpdateSettings?: (settings: UserSettings) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  expenses, 
  budget, 
  userName = 'Utente', 
  currency = '€', 
  wallets, 
  categories, 
  lang = 'it',
  userSettings,
  onUpdateSettings
}) => {
  const t = translations[lang].dashboard;
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const currentMonthDate = new Date();
  const [isEditingTotal, setIsEditingTotal] = useState(false);
  const [tempTotal, setTempTotal] = useState('');

  const parseDate = (dateStr: string) => {
    const [y, m, d] = dateStr.split('-').map(Number);
    return new Date(y, m - 1, d);
  };

  // Filtro spese del mese corrente
  const currentMonthExpenses = useMemo(() => {
    return expenses.filter(e => {
      const expenseDate = parseDate(e.date);
      return isSameMonth(expenseDate, currentMonthDate);
    });
  }, [expenses, currentMonthDate]);

  // CALCOLO TOTALE "SPESO QUESTO MESE" (Per la card principale)
  // Qui le spese vengono sommate per mostrare l'uscita mensile.
  const calculatedTotal = useMemo(() => {
    return currentMonthExpenses
      .filter(e => {
         // Escludi date future
         if (isFuture(parseDate(e.date))) return false;

         // Includi Bancomat, Contanti e Ricariche
         const isStandard = e.paymentMethod === PaymentMethod.Bancomat || e.paymentMethod === PaymentMethod.Contanti;
         const isRefill = e.description.toLowerCase().includes('ricarica');

         // Escludi gli aggiustamenti tecnici
         const isAdjustment = e.description.toLowerCase().includes('aggiustamento') || e.description.toLowerCase().includes('modifica');

         return (isStandard || isRefill) && !isAdjustment;
      })
      .reduce((sum, e) => sum + e.amount, 0);
  }, [currentMonthExpenses]);

  // Totale Visualizzato = Calcolato + Offset Manuale
  const totalCurrentMonth = Math.max(0, calculatedTotal + (userSettings?.monthlyOffset || 0));

  // Totale mese scorso
  const totalLastMonth = useMemo(() => {
    const lastMonthDate = new Date(currentMonthDate.getFullYear(), currentMonthDate.getMonth() - 1, 1);

    const lastMonthExpenses = expenses.filter(e => isSameMonth(parseDate(e.date), lastMonthDate));
    return lastMonthExpenses
      .filter(e => 
        (e.paymentMethod === PaymentMethod.Bancomat || e.paymentMethod === PaymentMethod.Contanti || e.description.toLowerCase().includes('ricarica')) && 
        !e.description.toLowerCase().includes('aggiustamento') &&
        !e.description.toLowerCase().includes('modifica') &&
        !isFuture(parseDate(e.date))
      )
      .reduce((sum, e) => sum + e.amount, 0);
  }, [expenses, currentMonthDate]);

  const diff = totalLastMonth > 0 ? ((totalCurrentMonth - totalLastMonth) / totalLastMonth) * 100 : 0;
  const budgetProgress = Math.min((totalCurrentMonth / budget) * 100, 100);

  // LOGICA SALDI WALLET
  // MODIFICA: Il saldo è dato dalla somma di TUTTE le ricariche (storico completo) + Offset Manuale.
  // LE SPESE NON VENGONO SOTTRATTE AUTOMATICAMENTE.
  const balances = useMemo(() => {
    return wallets.map(w => {
      const totalIn = expenses
        .filter(e => {
          // Consideriamo tutto lo storico per il saldo del wallet, non solo il mese corrente,
          // perché il credito residuo si accumula nel tempo.
          const desc = e.description.toLowerCase();
          const name = w.name.toLowerCase();
          const isAdjustment = desc.includes('aggiustamento') || desc.includes('modifica');
          // Somma le ricariche dirette a questo wallet
          return (desc.includes(`ricarica ${name}`) || (isAdjustment && desc.includes(name))) && e.paymentMethod !== w.method;
        })
        .reduce((sum, e) => sum + e.amount, 0);

      // Nessuna sottrazione spese (totalOut = 0)

      return {
        ...w,
        // Saldo = Totale Ricaricato + Offset Utente
        value: Math.max(0, totalIn + (w.balanceOffset || 0)),
        icon: w.icon === 'zap' ? <Zap size={14} /> : w.icon === 'fuel' ? <Fuel size={14} /> : <CreditCard size={14} />,
        color: w.icon === 'zap' ? 'text-emerald-500' : 'text-blue-500'
      };
    });
  }, [expenses, wallets]);

  // DATI GRAFICO CATEGORIE
  const categoryData = useMemo(() => {
    const realSpending = currentMonthExpenses.filter(e => 
      !e.description.toLowerCase().includes('aggiustamento') &&
      !e.description.toLowerCase().includes('modifica')
    );

    const data: Record<string, number> = {};
    realSpending.forEach(e => {
      data[e.category] = (data[e.category] || 0) + e.amount;
    });
    return Object.entries(data)
      .map(([name, value]) => ({ name, value }))
      .filter(item => item.value > 0)
      .sort((a, b) => b.value - a.value);
  }, [currentMonthExpenses]);

  const getCategoryColor = (catName: string) => categories.find(c => c.name === catName)?.color || '#9ca3af';
  const formatValue = (val: number) => `${currency}${val.toLocaleString('it-IT', { minimumFractionDigits: 2 })}`;
  const dateLocale = lang === 'en' ? enUS : it;

  const handleEditTotalClick = () => {
    setTempTotal(totalCurrentMonth.toFixed(2));
    setIsEditingTotal(true);
  };

  const handleSaveTotal = () => {
    if (!userSettings || !onUpdateSettings) return;

    const target = parseFloat(tempTotal.replace(',', '.'));
    if (isNaN(target) || target < 0) {
      alert("Inserisci un importo valido");
      return;
    }

    // Offset = Desiderato - Calcolato
    const newOffset = target - calculatedTotal;

    onUpdateSettings({
      ...userSettings,
      monthlyOffset: newOffset
    });

    setIsEditingTotal(false);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="mb-2">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white">{t.hello}, {userName}! 👋</h2>
        <p className="text-gray-500 dark:text-gray-400 text-sm">{t.subtitle}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="md:col-span-2 bg-emerald-500 p-8 rounded-[2rem] text-white shadow-xl shadow-emerald-200/50 relative overflow-hidden group">
          <div className="flex justify-between items-start mb-6">
            <div className="flex-1">
              <p className="text-emerald-50 text-xs font-bold uppercase tracking-wider mb-1">{t.spentThisMonth}</p>
              <div className="flex items-center gap-4">
                <h2 className="text-4xl font-black">{formatValue(totalCurrentMonth)}</h2>
                <button 
                  onClick={handleEditTotalClick}
                  className="p-2 bg-white/20 rounded-xl hover:bg-white/30 transition-colors opacity-0 group-hover:opacity-100 backdrop-blur-sm"
                  title="Modifica Totale Manualmente"
                >
                  <Edit2 size={16} className="text-white" />
                </button>
              </div>
              <p className="text-emerald-100 text-[10px] mt-1 font-medium">(Uscite Bancomat, Contanti & Ricariche)</p>
            </div>
            <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-sm shrink-0"><CreditCard size={24} /></div>
          </div>
          <div className="space-y-2">
            <div className="flex justify-between text-xs font-medium text-emerald-50">
              <span>{t.target}: {currency}{budget.toLocaleString('it-IT')}</span>
              <span>{Math.round(budgetProgress)}%</span>
            </div>
            <div className="h-2 w-full bg-white/20 rounded-full overflow-hidden">
              <div className="h-full bg-white transition-all duration-1000" style={{ width: `${budgetProgress}%` }}></div>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 flex items-center gap-4 shadow-sm">
            <div className={`p-3 rounded-2xl ${diff <= 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
              {diff <= 0 ? <TrendingDown size={20} /> : <TrendingUp size={20} />}
            </div>
            <div>
              <p className="text-gray-500 dark:text-gray-400 text-[10px] uppercase font-bold tracking-widest">{t.vsLastMonth}</p>
              <p className={`font-black text-lg ${diff <= 0 ? 'text-emerald-600' : 'text-red-500'}`}>
                {diff > 0 ? '+' : ''}{diff.toFixed(1)}%
              </p>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 flex items-center gap-4 shadow-sm">
            <div className="text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 p-3 rounded-2xl"><Calendar size={20} /></div>
            <div>
              <p className="text-gray-500 dark:text-gray-400 text-[10px] uppercase font-bold tracking-widest">{t.month}</p>
              <p className="font-black text-lg dark:text-white capitalize">{format(currentMonthDate, "MMMM", { locale: dateLocale })}</p>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm overflow-x-auto">
        <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4 ml-2">Saldi Attuali Portafogli</h3>
        <div className="flex gap-4 px-2">
          {balances.map((wallet) => (
            <div key={wallet.name} className="flex-shrink-0 w-40 p-4 rounded-2xl bg-emerald-50/50 dark:bg-gray-700/50 border border-emerald-100/50 dark:border-gray-600">
              <div className="flex justify-between items-center mb-2">
                <div className={wallet.color}>{wallet.icon}</div>
                <span className="text-[8px] font-bold text-gray-400 uppercase">{wallet.name}</span>
              </div>
              <p className="font-bold dark:text-white">{currency}{wallet.value.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</p>
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <div className="flex justify-between items-center mb-6">
             <h3 className="text-lg font-bold dark:text-white">Analisi Categorie</h3>
             <span className="text-[10px] text-gray-400 uppercase font-bold tracking-wider bg-gray-50 dark:bg-gray-700 px-2 py-1 rounded-lg">Consumo Reale</span>
          </div>
          <div className="w-full h-[250px]">
            {categoryData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={categoryData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                    {categoryData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={getCategoryColor(entry.name)} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(value: number) => [`${currency}${value.toLocaleString('it-IT', { minimumFractionDigits: 2 })}`, 'Importo']} />
                </PieChart>
              </ResponsiveContainer>
            ) : <div className="h-full flex items-center justify-center text-gray-400">Nessuna spesa rilevante</div>}
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-bold dark:text-white mb-6">Top Spese</h3>
          <div className="space-y-4">
            {categoryData.slice(0, 5).map((entry) => (
              <div key={entry.name} className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-3 h-3 rounded-full" style={{ backgroundColor: getCategoryColor(entry.name) }}></div>
                  <span className="text-sm dark:text-gray-300">{entry.name}</span>
                </div>
                <span className="text-sm font-bold dark:text-white">{formatValue(entry.value)}</span>
              </div>
            ))}
            {categoryData.length === 0 && <p className="text-gray-400 text-sm">Nessuna spesa da mostrare.</p>}
          </div>
        </div>
      </div>

      {isEditingTotal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-sm p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold dark:text-white">Modifica Totale Mese</h3>
              <button onClick={() => setIsEditingTotal(false)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>

            <div className="mb-6">
              <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Nuovo Totale Visualizzato</label>
              <input 
                autoFocus
                type="number" 
                inputMode="decimal"
                value={tempTotal} 
                onChange={(e) => setTempTotal(e.target.value)} 
                className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-emerald-400 outline-none font-black text-2xl" 
              />
              <p className="text-[10px] text-gray-400 mt-2 ml-1">*Modifica solo la visualizzazione, non le singole spese.</p>
            </div>

            <button 
              onClick={handleSaveTotal}
              className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 shadow-lg active:scale-95 hover:bg-emerald-600 transition-colors"
            >
              <Check size={20} /> Salva Modifica
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Zap, Wallet, Fuel, Plus, Clock, Info, CreditCard, Edit2, X, Check, Loader2, Banknote } from 'lucide-react';
import { Expense, PaymentMethod, WalletConfig } from '../types';
import { format } from 'date-fns';
import { it } from 'date-fns/locale';

interface RicaricheViewProps {
  onRefill: (wallet: WalletConfig) => void;
  onSaveExpense: (expense: Omit<Expense, 'id'>) => Promise<void>;
  onUpdateWallets: (wallets: WalletConfig[]) => void;
  expenses: Expense[];
  currency?: string;
  wallets: WalletConfig[];
}

export const RicaricheView: React.FC<RicaricheViewProps> = ({ onRefill, onSaveExpense, onUpdateWallets, expenses, currency = '€', wallets }) => {
  const [editingWallet, setEditingWallet] = useState<WalletConfig | null>(null);
  const [newBalance, setNewBalance] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const balances = useMemo(() => {
    return wallets.map(w => {
      // MODIFICA: Somma TUTTE le ricariche (storico completo) + Aggiustamenti.
      // Non usiamo più filtri mensili per il saldo, perché il credito è cumulativo.
      const totalRecharged = expenses
        .filter(e => {
          const desc = e.description.toLowerCase();
          const name = w.name.toLowerCase();
          const isInflow = desc.includes(`ricarica ${name}`) || desc.includes(`aggiustamento ${name}`) || desc.includes(`modifica saldo ${name}`) || desc.includes(`modifica ${name}`);
          return isInflow && e.paymentMethod !== w.method;
        })
        .reduce((sum, e) => sum + e.amount, 0);

      // MODIFICA: Non sottraiamo MAI le spese (passate, presenti o future) dal saldo visualizzato.
      // Il saldo è puramente (Ricariche + Offset Manuale).

      // Il saldo finale è il calcolato + l'offset manuale dell'utente
      return {
        ...w,
        balance: Math.max(0, totalRecharged + (w.balanceOffset || 0))
      };
    });
  }, [expenses, wallets]);

  const refillExpenses = useMemo(() => {
    return expenses.filter(e => 
      e.description.toLowerCase().includes('ricarica') || e.description.toLowerCase().includes('deposito')
    ).slice(0, 10);
  }, [expenses]);

  const handleEditClick = (wallet: WalletConfig) => {
    const current = balances.find(b => b.id === wallet.id)?.balance || 0;
    setNewBalance(current.toFixed(2));
    setEditingWallet(wallet);
  };

  const handleBalanceUpdate = () => {
    if (!editingWallet) return;
    const target = parseFloat(newBalance.replace(',', '.'));
    if (isNaN(target) || target < 0) {
      alert("Inserisci un importo valido");
      return;
    }

    const currentWalletState = balances.find(b => b.id === editingWallet.id);
    if (!currentWalletState) return;

    // Logica Offset:
    // Saldo Visualizzato = (Transazioni + Offset)
    // Target = (Transazioni + NuovoOffset)
    // NuovoOffset = Target - Transazioni
    // Transazioni in questo caso sono solo le ricariche.

    const currentBalance = currentWalletState.balance; // (Ricariche + VecchioOffset)
    const currentOffset = editingWallet.balanceOffset || 0;
    const transactionalBalance = currentBalance - currentOffset; // = Ricariche

    const newOffset = target - transactionalBalance;

    setIsSubmitting(true);

    // Aggiorna la configurazione del wallet invece di creare una spesa
    const updatedWallets = wallets.map(w => 
      w.id === editingWallet.id ? { ...w, balanceOffset: newOffset } : w
    );

    onUpdateWallets(updatedWallets);

    setEditingWallet(null);
    setIsSubmitting(false);
  };

  const getWalletIcon = (w: WalletConfig) => {
    if (w.method === PaymentMethod.Contanti) return <Banknote size={20} />;
    if (w.icon === 'zap') return <Zap size={20} />;
    if (w.icon === 'fuel') return <Fuel size={20} />;
    if (w.icon === 'credit-card') return <CreditCard size={20} />;
    return <Wallet size={20} />;
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 relative">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-xl font-bold text-gray-800 dark:text-white mb-2">I tuoi Portafogli</h2>
          <p className="text-gray-500 dark:text-gray-400 text-sm">Il saldo mostrato è il totale caricato. Le spese non vengono sottratte automaticamente.</p>
        </div>
        <div className="hidden md:flex items-center gap-1 text-[10px] font-bold text-emerald-500 bg-emerald-50 dark:bg-emerald-900/20 px-3 py-1.5 rounded-full border border-emerald-100 dark:border-emerald-800 uppercase tracking-widest">
          <Info size={12} /> Saldo Ricariche
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {balances.map((w) => (
          <WalletCard 
            key={w.id}
            name={w.name} 
            balance={w.balance} 
            icon={getWalletIcon(w)} 
            onRefill={() => onRefill(w)} 
            onEdit={() => handleEditClick(w)}
            color={w.method === PaymentMethod.Contanti ? 'emerald' : w.icon === 'zap' ? 'emerald' : w.icon === 'fuel' ? 'orange' : w.icon === 'credit-card' ? 'purple' : 'blue'} 
            currency={currency} 
          />
        ))}
      </div>

      <div className="bg-white dark:bg-gray-800 p-6 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm transition-colors">
        <div className="flex items-center gap-2 mb-6">
          <Clock className="text-emerald-500" size={20} />
          <h3 className="text-lg font-bold text-gray-800 dark:text-white">Storico Ricariche</h3>
        </div>
        <div className="space-y-3">
          {refillExpenses.length > 0 ? (
            refillExpenses.map((expense) => (
              <div key={expense.id} className="flex items-center justify-between p-4 rounded-2xl bg-gray-50 dark:bg-gray-700/50 hover:bg-emerald-50 dark:hover:bg-gray-700 transition-colors">
                <div className="flex items-center gap-4">
                   <div className="w-10 h-10 rounded-xl bg-white dark:bg-gray-800 flex items-center justify-center text-emerald-500 shadow-sm"><Plus size={18} /></div>
                   <div>
                     <p className="font-bold text-gray-800 dark:text-white text-sm">{expense.description}</p>
                     <p className="text-[10px] text-gray-400 dark:text-gray-500 font-medium uppercase tracking-tight">
                       {format(new Date(expense.date), 'dd MMMM yyyy', { locale: it })} • {expense.paymentMethod}
                     </p>
                   </div>
                </div>
                <span className="font-bold text-emerald-600 dark:text-emerald-400">+{currency}{expense.amount.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</span>
              </div>
            ))
          ) : (
            <div className="text-center py-10"><p className="text-gray-400 dark:text-gray-500 text-sm">Nessuna ricarica registrata.</p></div>
          )}
        </div>
      </div>

      {editingWallet && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-sm p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold dark:text-white">Modifica Saldo</h3>
              <button onClick={() => setEditingWallet(null)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>

            <div className="bg-emerald-50 dark:bg-emerald-900/20 p-4 rounded-2xl mb-6 flex items-center gap-3">
              <div className="p-2 bg-white dark:bg-gray-700 rounded-xl text-emerald-500 shadow-sm">
                {getWalletIcon(editingWallet)}
              </div>
              <div>
                <p className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">Portafoglio</p>
                <p className="font-bold text-emerald-700 dark:text-emerald-400">{editingWallet.name}</p>
              </div>
            </div>

            <div className="mb-6">
              <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Nuovo Saldo Attuale</label>
              <input 
                autoFocus
                type="number" 
                inputMode="decimal"
                value={newBalance} 
                onChange={(e) => setNewBalance(e.target.value)} 
                className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 dark:text-emerald-400 outline-none font-black text-2xl" 
              />
              <p className="text-[10px] text-gray-400 mt-2 ml-1">*Questo modificherà solo il valore visualizzato, senza creare transazioni.</p>
            </div>

            <button 
              onClick={handleBalanceUpdate}
              disabled={isSubmitting}
              className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 shadow-lg active:scale-95 hover:bg-emerald-600 transition-colors"
            >
              {isSubmitting ? <Loader2 className="animate-spin" size={20} /> : <Check size={20} />} Salva Modifica
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const WalletCard = ({ name, balance, icon, onRefill, onEdit, color, currency }: any) => {
  const colorClasses = {
