                    &nbsp;&nbsp;id uuid references auth.users on delete cascade not null primary key,<br/>
                    &nbsp;&nbsp;email text,<br/>
                    &nbsp;&nbsp;display_name text,<br/>
                    &nbsp;&nbsp;status text default 'active',<br/>
                    &nbsp;&nbsp;role text default 'user',<br/>
                    &nbsp;&nbsp;last_login timestamptz<br/>
                    );<br/>
                    alter table public.profiles enable row level security;<br/>
                    create policy "Profili visibili a tutti" on public.profiles for select using (true);<br/>
                    create policy "Utenti gestiscono proprio profilo" on public.profiles for insert with check (auth.uid() = id);<br/>
                    create policy "Utenti aggiornano proprio profilo" on public.profiles for update using (auth.uid() = id);
                </div>
            </div>
        )}

        {/* Users Table */}
        <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50 dark:bg-gray-700/50">
                <tr>
