      )}

      {/* Sidebar / Header */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-emerald-500 p-2.5 rounded-xl text-white shadow-lg shadow-emerald-200 dark:shadow-none">
              <Shield size={24} />
            </div>
            <div>
              <h1 className="text-xl font-black text-gray-800 dark:text-white tracking-tight">MintFlow <span className="text-emerald-500">Admin</span></h1>
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Pannello di Controllo</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden md:flex items-center gap-2 px-4 py-2 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-400 rounded-xl">
              <Users size={18} />
              <span className="font-bold text-sm">{users.length} Utenti</span>
            </div>
             <button 
              onClick={() => setShowSqlModal(true)}
              className="p-2 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400 rounded-xl hover:bg-indigo-100 transition-colors"
              title="Script Database"
            >
              <Database size={20} />
            </button>
            <button 
              onClick={handleLogout}
              className="flex items-center gap-2 px-4 py-2 bg-gray-100 dark:bg-gray-700 hover:bg-red-50 dark:hover:bg-red-900/20 text-gray-600 dark:text-gray-300 hover:text-red-600 transition-colors rounded-xl font-bold text-sm"
            >
              <LogOut size={18} /> <span className="hidden sm:inline">Esci</span>
            </button>
          </div>
        </div>
      </div>

      <main className="max-w-7xl mx-auto px-4 py-8">

        {/* Search Bar */}
        <div className="mb-8 relative flex gap-4">
            <div className="relative flex-1">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                <input 
                    type="text" 
                    placeholder="Cerca utente per nome o email..." 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full pl-12 pr-4 py-4 rounded-2xl border-none shadow-sm bg-white dark:bg-gray-800 focus:ring-2 focus:ring-emerald-500 outline-none text-gray-700 dark:text-gray-200 font-medium transition-all"
                />
            </div>
        </div>

        {error && (
            <div className="bg-red-50 dark:bg-red-900/20 p-6 rounded-2xl border border-red-100 dark:border-red-800 mb-8 flex items-center gap-4 cursor-pointer hover:bg-red-100 transition-colors" onClick={() => setShowSqlModal(true)}>
                <AlertTriangle className="text-red-500 shrink-0" size={32} />
                <div>
                  <h3 className="font-bold text-red-600 dark:text-red-400">Configurazione Database Richiesta</h3>
                  <p className="text-sm text-red-500/80">{error}</p>
                </div>
            </div>
        )}

        {/* Users Table */}
        <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50 dark:bg-gray-700/50">
                <tr>
                  <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase tracking-wider">Utente</th>
                  <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase tracking-wider">Stato</th>
                  <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase tracking-wider">Ultimo Accesso</th>
                  <th className="px-6 py-4 text-right text-xs font-bold text-gray-400 uppercase tracking-wider">Azioni</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                {loading ? (
                    <tr>
                        <td colSpan={4} className="p-8 text-center">
                            <Loader2 className="animate-spin mx-auto text-emerald-500" size={32} />
                        </td>
                    </tr>
                ) : filteredUsers.map((user) => (
                  <tr key={user.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors group">
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        <div className="w-10 h-10 rounded-full bg-gradient-to-br from-emerald-400 to-teal-500 flex items-center justify-center text-white font-bold text-lg shadow-sm">
                          {(user.display_name || user.email || '?').charAt(0).toUpperCase()}
                        </div>
                        <div className="ml-4">
                          <div className="text-sm font-bold text-gray-900 dark:text-white flex items-center gap-2">
                            {user.display_name || 'Utente senza nome'}
                            {user.email === 'admin@mintflow.com' && <span className="bg-purple-100 text-purple-600 text-[9px] px-1.5 py-0.5 rounded uppercase font-black tracking-wide">Admin</span>}
                          </div>
                          <div className="text-sm text-gray-500">{user.email}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-3 py-1 inline-flex text-xs leading-5 font-bold rounded-full items-center gap-1.5 ${
                        user.status === 'active' 
                          ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400' 
                          : 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400'
                      }`}>
                        <span className={`w-2 h-2 rounded-full ${user.status === 'active' ? 'bg-emerald-500' : 'bg-red-500'}`}></span>
                        {user.status === 'active' ? 'Attivo' : 'Disabilitato'}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400 font-medium">
                      {user.last_login ? format(new Date(user.last_login), 'dd MMM yyyy HH:mm', { locale: it }) : 'Mai'}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      {user.email !== 'admin@mintflow.com' && (
                        <div className="flex items-center justify-end gap-2 opacity-100 sm:opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => { setSelectedUser(user); setShowNotifyModal(true); }}
                            className="p-2 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-colors"
                            title="Invia Notifica"
                          >
                            <Bell size={18} />
                          </button>
                          <button 
                            onClick={() => { setSelectedUser(user); setShowPasswordModal(true); }}
                            className="p-2 text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/20 rounded-lg transition-colors"
                            title="Cambia Password"
                          >
                            <Key size={18} />
                          </button>
                          <button 
                            onClick={() => handleToggleStatus(user.id)}
                            className={`p-2 rounded-lg transition-colors ${
                              user.status === 'active' 
                              ? 'text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20' 
                              : 'text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/20'
                            }`}
                            title={user.status === 'active' ? 'Disabilita Account' : 'Attiva Account'}
                          >
                            {user.status === 'active' ? <Ban size={18} /> : <CheckCircle2 size={18} />}
                          </button>
                          <button 
                            onClick={() => handleDeleteUser(user.id)}
                            className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                            title="Elimina Utente"
                          >
                            <Trash2 size={18} />
                          </button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {!loading && filteredUsers.length === 0 && (
             <div className="p-12 text-center text-gray-400">
               <Users size={48} className="mx-auto mb-4 opacity-20" />
               <p>Nessun utente trovato.</p>
               <button onClick={() => setShowSqlModal(true)} className="mt-4 text-emerald-500 font-bold hover:underline">Importa dal DB</button>
             </div>
          )}
        </div>
      </main>

      {/* Modal SQL Script */}
      {showSqlModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-in fade-in duration-200">
            <div className="bg-white dark:bg-gray-800 rounded-[2rem] w-full max-w-2xl p-8 shadow-2xl animate-in zoom-in-95">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold dark:text-white flex items-center gap-2">
                        <Terminal className="text-emerald-500" size={24} /> Script Manutenzione DB
                    </h3>
                    <button onClick={() => setShowSqlModal(false)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
                </div>

                <div className="bg-amber-50 dark:bg-amber-900/20 p-4 rounded-xl mb-4 flex items-start gap-3">
                    <AlertTriangle className="text-amber-500 shrink-0 mt-0.5" size={20} />
                    <p className="text-sm text-amber-700 dark:text-amber-400">
                        Esegui questo script nel <strong>Supabase SQL Editor</strong> per importare gli utenti già registrati e sincronizzare l'admin. Il frontend non può leggere i vecchi utenti per sicurezza.
                    </p>
                </div>

                <div className="bg-gray-900 p-4 rounded-xl mb-4 relative group">
                    <pre className="text-xs text-gray-300 font-mono overflow-x-auto whitespace-pre-wrap">
                        {sqlImportScript}
                    </pre>
                    <button 
                        onClick={() => { navigator.clipboard.writeText(sqlImportScript); showToast("Copiato negli appunti!"); }}
                        className="absolute top-2 right-2 p-2 bg-gray-700 text-white rounded-lg hover:bg-gray-600 opacity-0 group-hover:opacity-100 transition-opacity"
                        title="Copia"
                    >
                        <Copy size={16} />
                    </button>
                </div>

                <div className="flex justify-end gap-3">
                     <button onClick={() => setShowSqlModal(false)} className="px-6 py-3 bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-300 font-bold rounded-xl">Chiudi</button>
                     <button onClick={() => { fetchUsers(); setShowSqlModal(false); }} className="px-6 py-3 bg-emerald-500 text-white font-bold rounded-xl">Ho eseguito lo script, Aggiorna</button>
                </div>
            </div>
        </div>
      )}

      {/* Modal Notifica */}
      {showNotifyModal && selectedUser && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="bg-white dark:bg-gray-800 rounded-[2rem] w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold dark:text-white flex items-center gap-2">
                <Send className="text-emerald-500" size={24} /> Invia Notifica
              </h3>
              <button onClick={() => setShowNotifyModal(false)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>

            <div className="bg-emerald-50 dark:bg-emerald-900/20 p-4 rounded-xl mb-4 flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-emerald-200 dark:bg-emerald-800 flex items-center justify-center text-emerald-700 dark:text-emerald-300 font-bold">
                {(selectedUser.display_name || '?').charAt(0)}
              </div>
              <div>
                <p className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">Destinatario</p>
                <p className="font-bold text-gray-800 dark:text-white">{selectedUser.display_name || selectedUser.email}</p>
              </div>
            </div>

            <textarea 
              autoFocus
              value={notificationText}
              onChange={(e) => setNotificationText(e.target.value)}
              placeholder="Scrivi qui il messaggio..."
              className="w-full p-4 rounded-xl bg-gray-50 dark:bg-gray-700 border-none outline-none focus:ring-2 focus:ring-emerald-500 min-h-[120px] mb-6 dark:text-white resize-none"
            />

            <button 
              onClick={handleSendNotification}
              className="w-full py-4 bg-emerald-500 text-white rounded-xl font-bold hover:bg-emerald-600 transition-colors shadow-lg active:scale-95"
            >
              Invia Messaggio
            </button>
          </div>
        </div>
      )}

      {/* Modal Password */}
      {showPasswordModal && selectedUser && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="bg-white dark:bg-gray-800 rounded-[2rem] w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold dark:text-white flex items-center gap-2">
                <Key className="text-amber-500" size={24} /> Reset Password
              </h3>
              <button onClick={() => setShowPasswordModal(false)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>

            <p className="text-sm text-gray-500 mb-6">
              Stai cambiando la password per <strong>{selectedUser.email}</strong>. L'utente verrà disconnesso da tutti i dispositivi.
            </p>

            <div className="relative mb-6">
              <Key className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input 
                type="password"
                autoFocus
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                placeholder="Nuova Password"
                className="w-full pl-12 pr-4 py-4 rounded-xl bg-gray-50 dark:bg-gray-700 border-none outline-none focus:ring-2 focus:ring-amber-500 dark:text-white font-bold"
              />
            </div>

            <button 
              onClick={handleChangePassword}
              className="w-full py-4 bg-amber-500 text-white rounded-xl font-bold hover:bg-amber-600 transition-colors shadow-lg active:scale-95"
            >
              Aggiorna Password
            </button>
          </div>
        </div>
      )}

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Shield, Users, Bell, Trash2, Ban, Key, Search, LogOut, CheckCircle2, X, Send, AlertTriangle, Mail, Loader2, Database, Terminal, Copy, Menu } from 'lucide-react';
import { auth, db } from '../services/supabase';
import { format } from 'date-fns';
import { it } from 'date-fns/locale';

interface AdminUser {
  id: string;
  email: string;
  display_name: string;
  status: 'active' | 'disabled';
  last_login: string;
  role: 'user' | 'admin';
}

export const AdminDashboard: React.FC = () => {
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState<AdminUser | null>(null);
  const [showNotifyModal, setShowNotifyModal] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [showSqlModal, setShowSqlModal] = useState(false);
  const [notificationText, setNotificationText] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [toast, setToast] = useState<{msg: string, type: 'success' | 'error'} | null>(null);

  const fetchUsers = async () => {
    setLoading(true);
    setError(null);
    try {
        const data = await db.getAllProfiles();
        const realUsers = data as AdminUser[];

        // Verifica se l'admin è già presente nel DB reale
        const adminExists = realUsers.some(u => u.email === 'admin@mintflow.com');

        // Se l'admin non è nel DB (perché non è stato importato), aggiungiamo quello mock
        let finalUsers = [...realUsers];

        if (!adminExists) {
           const mockAdmin: AdminUser = {
               id: 'mock-admin-id',
               email: 'admin@mintflow.com',
               display_name: 'Super Admin (Mock)',
               status: 'active',
               last_login: new Date().toISOString(),
               role: 'admin'
          };
          finalUsers = [mockAdmin, ...realUsers];
        } else {
            // Assicuriamoci che l'admin sia in cima
            finalUsers = [
                ...realUsers.filter(u => u.email === 'admin@mintflow.com'),
                ...realUsers.filter(u => u.email !== 'admin@mintflow.com')
            ];
        }

        setUsers(finalUsers);

    } catch (err: any) {
        console.error(err);
        setError("Errore caricamento profili. Clicca l'icona Database per istruzioni SQL.");
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const showToast = (msg: string, type: 'success' | 'error' = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const filteredUsers = users.filter(u => 
    (u.email || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
    (u.display_name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleToggleStatus = async (id: string) => {
    const user = users.find(u => u.id === id);
    if (!user) return;
    if (user.id === 'mock-admin-id') return showToast("Impossibile modificare l'admin simulato", 'error');

    const newStatus = user.status === 'active' ? 'disabled' : 'active';
    try {
        await db.updateUserStatus(id, newStatus);
        setUsers(users.map(u => u.id === id ? { ...u, status: newStatus } : u));
        showToast(`Utente ${newStatus === 'active' ? 'riattivato' : 'disabilitato'} con successo`);
    } catch (err) {
        showToast("Errore durante l'aggiornamento stato", 'error');
    }
  };

  const handleDeleteUser = async (id: string) => {
    if (id === 'mock-admin-id') return showToast("Impossibile eliminare l'admin simulato", 'error');
    if (window.confirm('Sei sicuro di voler eliminare definitivamente questo utente e tutti i suoi dati (spese incluse)? Questa azione è irreversibile.')) {
      try {
          await db.deleteProfile(id);
          setUsers(users.filter(u => u.id !== id));
          showToast('Utente e dati eliminati correttamente');
      } catch (err: any) {
          alert(err.message);
          showToast('Errore eliminazione: ' + err.message, 'error');
      }
    }
  };

  const handleSendNotification = () => {
    if (!notificationText.trim()) return;
    console.log(`Sending to ${selectedUser?.email}: ${notificationText}`);
    showToast(`Notifica inviata a ${selectedUser?.email}`);
    setShowNotifyModal(false);
    setNotificationText('');
    setSelectedUser(null);
  };

  const handleChangePassword = () => {
    if (newPassword.length < 6) {
      showToast('La password deve essere di almeno 6 caratteri', 'error');
      return;
    }
    alert("⚠️ Attenzione: Il cambio password per altri utenti richiede una Supabase Edge Function o un backend con 'Service Role'. Questa operazione è simulata nel client.");
    showToast(`Password simulata aggiornata per ${selectedUser?.email}`);
    setShowPasswordModal(false);
    setNewPassword('');
    setSelectedUser(null);
  };

  const handleLogout = async () => {
      try {
        await auth.signOut();
      } catch (e) {
          // Ignora errori logout
      }
      window.location.reload();
  };

  const sqlImportScript = `
-- Importa utenti esistenti da Auth a Profiles
INSERT INTO public.profiles (id, email, display_name, last_login, role, status)
SELECT 
    id, 
    email, 
    COALESCE(raw_user_meta_data->>'display_name', split_part(email, '@', 1)),
    COALESCE(last_sign_in_at, created_at),
    CASE WHEN email = 'admin@mintflow.com' THEN 'admin' ELSE 'user' END,
    'active'
FROM auth.users
ON CONFLICT (id) DO UPDATE 
SET email = EXCLUDED.email, last_login = EXCLUDED.last_login;
  `.trim();

  // Componente Avatar Riutilizzabile
  const UserAvatar = ({ name, email }: { name: string, email: string }) => (
    <div className="w-10 h-10 rounded-full bg-gradient-to-br from-emerald-400 to-teal-500 flex items-center justify-center text-white font-bold text-lg shadow-sm shrink-0">
      {(name || email || '?').charAt(0).toUpperCase()}
    </div>
  );

  // Componente Badge Stato Riutilizzabile
  const StatusBadge = ({ status }: { status: string }) => (
    <span className={`px-2.5 py-1 inline-flex text-xs leading-5 font-bold rounded-full items-center gap-1.5 ${
      status === 'active' 
        ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400' 
        : 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400'
    }`}>
      <span className={`w-1.5 h-1.5 rounded-full ${status === 'active' ? 'bg-emerald-500' : 'bg-red-500'}`}></span>
      {status === 'active' ? 'Attivo' : 'Disabilitato'}
    </span>
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white font-sans pb-20 md:pb-0">
      {/* Toast */}
      {toast && (
        <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[150] px-6 py-3 rounded-2xl shadow-xl flex items-center gap-2 animate-in slide-in-from-top-4 ${toast.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-500 text-white'}`}>
          {toast.type === 'success' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
          <span className="font-bold text-sm">{toast.msg}</span>
        </div>
      )}

      {/* Header Responsivo */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 h-auto md:h-20 py-3 md:py-0 flex flex-wrap md:flex-nowrap items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <div className="bg-emerald-500 p-2 rounded-xl text-white shadow-lg shadow-emerald-200 dark:shadow-none">
              <Shield size={20} />
            </div>
            <div>
              <h1 className="text-lg md:text-xl font-black text-gray-800 dark:text-white tracking-tight leading-none">MintFlow <span className="text-emerald-500">Admin</span></h1>
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest hidden sm:block">Pannello di Controllo</p>
            </div>
          </div>

          <div className="flex items-center gap-2 ml-auto">
            <div className="hidden md:flex items-center gap-2 px-3 py-1.5 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-400 rounded-xl">
              <Users size={16} />
              <span className="font-bold text-xs">{users.length} Utenti</span>
            </div>
             <button 
              onClick={() => setShowSqlModal(true)}
              className="p-2 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400 rounded-xl hover:bg-indigo-100 transition-colors"
              title="Script Database"
            >
              <Database size={18} />
            </button>
            <button 
              onClick={handleLogout}
              className="flex items-center gap-2 px-3 py-2 bg-gray-100 dark:bg-gray-700 hover:bg-red-50 dark:hover:bg-red-900/20 text-gray-600 dark:text-gray-300 hover:text-red-600 transition-colors rounded-xl font-bold text-xs"
            >
              <LogOut size={18} /> <span className="hidden sm:inline">Esci</span>
            </button>
          </div>
        </div>
      </div>

      <main className="max-w-7xl mx-auto px-4 py-6">

        {/* Search Bar */}
        <div className="mb-6 relative flex gap-3">
            <div className="relative flex-1">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input 
                    type="text" 
                    placeholder="Cerca utente..." 
