  // Calcolo saldo Extra
  const totalGiven = expenses.filter(e => e.extraType === 'given').reduce((acc, curr) => acc + curr.amount, 0);
  const totalReceived = expenses.filter(e => e.extraType === 'received').reduce((acc, curr) => acc + curr.amount, 0);
  const balance = totalReceived - totalGiven;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!description.trim() || !amount) return;

    setIsSubmitting(true);
    try {
      await onAdd({
        description: description,
        amount: parseFloat(amount.replace(',', '.')),
        category: 'Extra',
        paymentMethod: PaymentMethod.Contanti, // Default per Extra
        date: new Date().toISOString().split('T')[0],
        isExtra: true,
        extraType: transactionType,
        profile: 'personal'
      });
      setIsAdding(false);
      setDescription('');
      setAmount('');
    } catch (err) {
      alert("Errore nel salvataggio");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Balance Card - Updated to match Dashboard style (Emerald) */}
      <div className="bg-emerald-500 p-8 rounded-[2.5rem] text-white shadow-xl shadow-emerald-200/50 dark:shadow-none relative overflow-hidden">
        <div className="flex justify-between items-start z-10 relative">
          <div>
            <p className="text-emerald-50 text-xs font-bold uppercase tracking-widest mb-1">Saldo Extra</p>
            <h2 className="text-4xl font-black">{balance >= 0 ? '+' : ''}{currency}{balance.toLocaleString('it-IT', { minimumFractionDigits: 2 })}</h2>
            <div className="flex gap-4 mt-4 text-xs font-medium opacity-80">
              <span className="bg-white/20 px-2 py-1 rounded-lg">Dati: {currency}{totalGiven.toFixed(2)}</span>
              <span className="bg-white/20 px-2 py-1 rounded-lg">Ricevuti: {currency}{totalReceived.toFixed(2)}</span>
            </div>
          </div>
        </div>
      </div>

      <div className="flex gap-3">
        <button 
          onClick={() => { setTransactionType('given'); setIsAdding(true); }}
          className="flex-1 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 p-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 border-2 border-transparent hover:border-red-200 transition-all active:scale-95"
        >
          <div className="bg-white dark:bg-gray-800 p-2 rounded-full shadow-sm"><ArrowUpRight size={20} /></div>
          <span className="text-sm">Ho Dato</span>
        </button>
        <button 
          onClick={() => { setTransactionType('received'); setIsAdding(true); }}
          className="flex-1 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 p-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 border-2 border-transparent hover:border-emerald-200 transition-all active:scale-95"
        >
          <div className="bg-white dark:bg-gray-800 p-2 rounded-full shadow-sm"><ArrowDownLeft size={20} /></div>
          <span className="text-sm">Ho Ricevuto</span>
        </button>
      </div>

      <div className="space-y-4">
        <h3 className="text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-[0.2em] px-4">Movimenti Extra</h3>
        {expenses.length > 0 ? (
          <div className="bg-white dark:bg-gray-800 rounded-[2rem] border border-gray-100 dark:border-gray-700 overflow-hidden shadow-sm">
            {expenses.map((expense) => (
              <div key={expense.id} className="p-4 flex items-center justify-between border-b border-gray-50 dark:border-gray-700 last:border-0 hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                <div className="flex items-center gap-4">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${
                    expense.extraType === 'given' 
                      ? 'bg-red-100 text-red-600 dark:bg-red-900/30' 
                      : 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30'
                  }`}>
                    {expense.extraType === 'given' ? <ArrowUpRight size={18} /> : <ArrowDownLeft size={18} />}
                  </div>
                  <div>
                    <h4 className="font-bold text-gray-800 dark:text-white text-sm">{expense.description}</h4>
                    <p className="text-[10px] text-gray-400 uppercase font-medium">{format(new Date(expense.date), 'dd MMM yyyy', { locale: it })}</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <span className={`font-bold ${expense.extraType === 'given' ? 'text-red-500' : 'text-emerald-500'}`}>
                    {expense.extraType === 'given' ? '-' : '+'}{currency}{expense.amount.toFixed(2)}
                  </span>
                  <button onClick={() => onDelete(expense.id)} className="text-gray-300 hover:text-red-500 transition-colors">
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-12 bg-gray-50 dark:bg-gray-800/50 rounded-[2.5rem] border-2 border-dashed border-gray-200 dark:border-gray-700">
            <Info className="mx-auto text-gray-300 mb-2" size={32} />
            <p className="text-gray-400 font-medium text-sm">Nessun movimento extra.</p>
          </div>
        )}
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-sm p-8 shadow-2xl animate-in zoom-in-95 duration-200 relative">
            <button onClick={() => setIsAdding(false)} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600"><X size={24} /></button>

            <h3 className={`text-xl font-bold mb-6 ${transactionType === 'given' ? 'text-red-500' : 'text-emerald-500'}`}>
              {transactionType === 'given' ? 'A chi hai dato soldi?' : 'Da chi hai ricevuto soldi?'}
            </h3>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Descrizione</label>
                <input 
                  autoFocus
                  type="text" 
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder={transactionType === 'given' ? "Prestito a Marco..." : "Regalo nonna..."}
                  className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-indigo-500 outline-none dark:text-white font-medium"
                />
              </div>

              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Importo</label>
                <input 
                  type="number" 
                  inputMode="decimal"
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                  placeholder="0.00"
                  className="w-full px-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-indigo-500 outline-none dark:text-white font-black text-2xl"
                />
              </div>

              <button 
                type="submit"
                disabled={isSubmitting}
                className={`w-full py-4 text-white rounded-2xl font-bold flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-all mt-4 ${
                   transactionType === 'given' ? 'bg-red-500 hover:bg-red-600' : 'bg-emerald-500 hover:bg-emerald-600'
                }`}
              >
                {isSubmitting ? <Loader2 className="animate-spin" size={20} /> : <Check size={20} />} Salva
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Shield, Users, Bell, Trash2, Ban, Key, Search, LogOut, CheckCircle2, X, Send, AlertTriangle, Mail, Loader2, Database, Terminal, Copy, Menu } from 'lucide-react';
import { auth, db } from '../services/supabase';
import { format } from 'date-fns';
import it from 'date-fns/locale/it';

interface AdminUser {
  id: string;
  email: string;
  display_name: string;
  status: 'active' | 'disabled';
  last_login: string;
  role: 'user' | 'admin';
}

interface AdminDashboardProps {
  onLogout: () => void;
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout }) => {
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState<AdminUser | null>(null);
  const [showNotifyModal, setShowNotifyModal] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [showSqlModal, setShowSqlModal] = useState(false);
  const [notificationText, setNotificationText] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [toast, setToast] = useState<{msg: string, type: 'success' | 'error'} | null>(null);

  const fetchUsers = async () => {
    setLoading(true);
    setError(null);
    try {
        const data = await db.getAllProfiles();
        const realUsers = data as AdminUser[];

        // Verifica se l'admin è già presente nel DB reale
        const adminExists = realUsers.some(u => u.email === 'admin@mintflow.com');

        // Se l'admin non è nel DB (perché non è stato importato), aggiungiamo quello mock
        let finalUsers = [...realUsers];

        if (!adminExists) {
           const mockAdmin: AdminUser = {
               id: 'mock-admin-id',
               email: 'admin@mintflow.com',
               display_name: 'Super Admin (Mock)',
               status: 'active',
               last_login: new Date().toISOString(),
               role: 'admin'
          };
          finalUsers = [mockAdmin, ...realUsers];
        } else {
            // Assicuriamoci che l'admin sia in cima
            finalUsers = [
                ...realUsers.filter(u => u.email === 'admin@mintflow.com'),
                ...realUsers.filter(u => u.email !== 'admin@mintflow.com')
            ];
        }

        setUsers(finalUsers);

    } catch (err: any) {
        console.error(err);
        setError("Errore caricamento profili. Clicca l'icona Database per istruzioni SQL.");
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const showToast = (msg: string, type: 'success' | 'error' = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const filteredUsers = users.filter(u => 
    (u.email || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
    (u.display_name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleToggleStatus = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation(); // Mantengo solo stopPropagation, rimuovo preventDefault

    const user = users.find(u => u.id === id);
    if (!user) return;

    if (user.id === 'mock-admin-id') {
        return showToast("Impossibile modificare l'admin simulato", 'error');
    }

    const newStatus = user.status === 'active' ? 'disabled' : 'active';
    const actionLabel = user.status === 'active' ? 'DISABILITARE' : 'RIATTIVARE';

    if (window.confirm(`SEI SICURO?\n\nStai per ${actionLabel} l'utente:\n${user.display_name || user.email}`)) {
        try {
            await db.updateUserStatus(id, newStatus);
            setUsers(prevUsers => prevUsers.map(u => u.id === id ? { ...u, status: newStatus } : u));
            showToast(`Utente ${newStatus === 'active' ? 'riattivato' : 'disabilitato'} con successo`);
        } catch (err: any) {
            console.error("Errore DB:", err);
            alert("Errore DB: " + err.message);
        }
    }
  };

  const handleDeleteUser = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();

    if (id === 'mock-admin-id') return showToast("Impossibile eliminare l'admin simulato", 'error');

    if (window.confirm('ATTENZIONE: Eliminazione DEFINITIVA.\n\nSei sicuro di voler eliminare questo utente e TUTTI i suoi dati?')) {
      try {
          await db.deleteProfile(id);
          setUsers(users.filter(u => u.id !== id));
          showToast('Utente eliminato');
      } catch (err: any) {
          alert(err.message);
      }
    }
  };

  const handleSendNotification = async () => {
    if (!notificationText.trim() || !selectedUser) return;

    try {
      await db.sendNotification(selectedUser.id, notificationText);
      showToast(`Notifica inviata a ${selectedUser.email}`);
      setShowNotifyModal(false);
      setNotificationText('');
      setSelectedUser(null);
    } catch (err: any) {
      showToast('Errore invio notifica: ' + err.message, 'error');
    }
  };

  const handleChangePassword = () => {
    if (newPassword.length < 6) {
      showToast('La password deve essere di almeno 6 caratteri', 'error');
      return;
    }
    alert("⚠️ Attenzione: Il cambio password per altri utenti richiede una Supabase Edge Function. Questa operazione è simulata.");
    showToast(`Password simulata aggiornata per ${selectedUser?.email}`);
    setShowPasswordModal(false);
    setNewPassword('');
    setSelectedUser(null);
  };

  const handleLogout = async () => {
      try {
        await auth.signOut();
      } catch (e) {
          // Ignora errori logout
      }
      onLogout(); // Reindirizza al login immediatamente
  };

  const sqlImportScript = `
-- 1. Crea la tabella profiles se non esiste (con colonna notification)
CREATE TABLE IF NOT EXISTS public.profiles (
  id uuid REFERENCES auth.users ON DELETE CASCADE PRIMARY KEY,
  email text,
  display_name text,
  role text DEFAULT 'user',
  status text DEFAULT 'active',
  last_login timestamptz,
  notification text -- Colonna per i messaggi admin
);

-- 2. Importa utenti esistenti da Auth
INSERT INTO public.profiles (id, email, display_name, last_login, role, status)
SELECT 
    id, 
    email, 
    COALESCE(raw_user_meta_data->>'display_name', split_part(email, '@', 1)),
    COALESCE(last_sign_in_at, created_at),
    CASE WHEN email = 'admin@mintflow.com' THEN 'admin' ELSE 'user' END,
    'active'
FROM auth.users
ON CONFLICT (id) DO UPDATE 
SET email = EXCLUDED.email, last_login = EXCLUDED.last_login;

-- 3. Abilita RLS (Row Level Security)
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

-- 4. Policy cleanup (Rimuove vecchie policy problematiche)
DROP POLICY IF EXISTS "Users can see own profile" ON public.profiles;
DROP POLICY IF EXISTS "Admin can see all" ON public.profiles;
DROP POLICY IF EXISTS "Admin can update all" ON public.profiles;

-- 5. Crea Policy (Versione corretta senza ricorsione)
CREATE POLICY "Users can see own profile" ON public.profiles FOR SELECT USING (auth.uid() = id);

-- NOTA: Usa l'email dal token JWT per evitare loop infiniti di lettura
CREATE POLICY "Admin can see all" ON public.profiles FOR SELECT USING (
  (auth.jwt() ->> 'email') = 'admin@mintflow.com'
);

CREATE POLICY "Admin can update all" ON public.profiles FOR UPDATE USING (
  (auth.jwt() ->> 'email') = 'admin@mintflow.com'
);
  `.trim();

  // Componente Avatar Riutilizzabile
  const UserAvatar = ({ name, email }: { name: string, email: string }) => (
    <div className="w-10 h-10 rounded-full bg-gradient-to-br from-emerald-400 to-teal-500 flex items-center justify-center text-white font-bold text-lg shadow-sm shrink-0">
      {(name || email || '?').charAt(0).toUpperCase()}
    </div>
  );

  // Componente Badge Stato Riutilizzabile
  const StatusBadge = ({ status }: { status: string }) => (
    <span className={`px-2.5 py-1 inline-flex text-xs leading-5 font-bold rounded-full items-center gap-1.5 ${
      status === 'active' 
        ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400' 
        : 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400'
    }`}>
      <span className={`w-1.5 h-1.5 rounded-full ${status === 'active' ? 'bg-emerald-500' : 'bg-red-500'}`}></span>
      {status === 'active' ? 'Attivo' : 'Disabilitato'}
    </span>
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white font-sans pb-20 md:pb-0">
      {/* Toast */}
      {toast && (
        <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[150] px-6 py-3 rounded-2xl shadow-xl flex items-center gap-2 animate-in slide-in-from-top-4 ${toast.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-500 text-white'}`}>
          {toast.type === 'success' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
          <span className="font-bold text-sm">{toast.msg}</span>
        </div>
      )}

      {/* Header Responsivo */}
      <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 h-auto md:h-20 py-3 md:py-0 flex flex-wrap md:flex-nowrap items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <div className="bg-emerald-500 p-2 rounded-xl text-white shadow-lg shadow-emerald-200 dark:shadow-none">
              <Shield size={20} />
            </div>
            <div>
              <h1 className="text-lg md:text-xl font-black text-gray-800 dark:text-white tracking-tight leading-none">MintFlow <span className="text-emerald-500">Admin</span></h1>
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest hidden sm:block">Pannello di Controllo</p>
            </div>
          </div>

          <div className="flex items-center gap-2 ml-auto">
            <div className="hidden md:flex items-center gap-2 px-3 py-1.5 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-400 rounded-xl">
              <Users size={16} />
              <span className="font-bold text-xs">{users.length} Utenti</span>
            </div>
             <button 
              type="button"
              onClick={() => setShowSqlModal(true)}
              className="p-2 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400 rounded-xl hover:bg-indigo-100 transition-colors"
              title="Script Database"
            >
              <Database size={18} />
            </button>
            <button 
              type="button"
              onClick={handleLogout}
              className="flex items-center gap-2 px-3 py-2 bg-gray-100 dark:bg-gray-700 hover:bg-red-50 dark:hover:bg-red-900/20 text-gray-600 dark:text-gray-300 hover:text-red-600 transition-colors rounded-xl font-bold text-xs"
            >
              <LogOut size={18} /> <span className="hidden sm:inline">Esci</span>
            </button>
          </div>
        </div>
      </div>

      <main className="max-w-7xl mx-auto px-4 py-6">

        {/* Search Bar */}
        <div className="mb-6 relative flex gap-3">
            <div className="relative flex-1">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input 
                    type="text" 
                    placeholder="Cerca utente..." 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full pl-10 pr-4 py-3 rounded-xl border-none shadow-sm bg-white dark:bg-gray-800 focus:ring-2 focus:ring-emerald-500 outline-none text-gray-700 dark:text-gray-200 font-medium text-sm transition-all"
                />
            </div>
        </div>

        {error && (
            <div className="bg-red-50 dark:bg-red-900/20 p-4 rounded-2xl border border-red-100 dark:border-red-800 mb-6 flex items-start gap-3 cursor-pointer" onClick={() => setShowSqlModal(true)}>
                <AlertTriangle className="text-red-500 shrink-0 mt-0.5" size={24} />
                <div>
                  <h3 className="font-bold text-red-600 dark:text-red-400 text-sm">Database non configurato</h3>
                  <p className="text-xs text-red-500/80 mt-1">Clicca qui per vedere lo script SQL necessario (Aggiornato).</p>
                </div>
            </div>
        )}

        {/* --- DESKTOP VIEW (TABLE) --- */}
        <div className="hidden md:block bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50 dark:bg-gray-700/50">
                <tr>
                  <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase tracking-wider">Utente</th>
                  <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase tracking-wider">Stato</th>
                  <th className="px-6 py-4 text-left text-xs font-bold text-gray-400 uppercase tracking-wider">Ultimo Accesso</th>
                  <th className="px-6 py-4 text-right text-xs font-bold text-gray-400 uppercase tracking-wider">Azioni</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                {loading ? (
                    <tr><td colSpan={4} className="p-8 text-center"><Loader2 className="animate-spin mx-auto text-emerald-500" size={32} /></td></tr>
                ) : filteredUsers.map((user) => (
                  <tr key={user.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors group">
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        <UserAvatar name={user.display_name} email={user.email} />
                        <div className="ml-4">
                          <div className="text-sm font-bold text-gray-900 dark:text-white flex items-center gap-2">
                            {user.display_name || 'Utente senza nome'}
                            {user.role === 'admin' && <span className="bg-purple-100 text-purple-600 text-[9px] px-1.5 py-0.5 rounded uppercase font-black tracking-wide">Admin</span>}
                          </div>
                          <div className="text-sm text-gray-500">{user.email}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap"><StatusBadge status={user.status} /></td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400 font-medium">
                      {user.last_login ? format(new Date(user.last_login), 'dd MMM yyyy HH:mm', { locale: it }) : 'Mai'}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      {user.email !== 'admin@mintflow.com' && (
                        // Removed opacity-50 and hover effect for better reliability on all devices
                        <div className="flex items-center justify-end gap-2">
                          <button type="button" onClick={() => { setSelectedUser(user); setShowNotifyModal(true); }} className="p-2 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-colors"><Bell size={18} /></button>
                          <button type="button" onClick={() => { setSelectedUser(user); setShowPasswordModal(true); }} className="p-2 text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/20 rounded-lg transition-colors"><Key size={18} /></button>

                          {/* PULSANTE GESTIONE STATO UTENTE */}
                          {user.status === 'active' ? (
                            <button 
                              type="button"
                              onClick={(e) => handleToggleStatus(user.id, e)} 
                              className="p-2 rounded-lg text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
                              title="Disabilita Utente"
                            >
                              <Ban size={18} />
                            </button>
                          ) : (
                            <button 
                              type="button"
                              onClick={(e) => handleToggleStatus(user.id, e)} 
                              className="p-2 rounded-lg text-emerald-600 bg-emerald-100 hover:bg-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-400 transition-colors font-bold shadow-sm ring-1 ring-emerald-500/30"
                              title="Riattiva Utente Disabilitato"
                            >
                              <CheckCircle2 size={18} />
