            currency={userSettings.currency}
            isNewUser={!userSettings.lastBudgetUpdate}
          />
        )}

        {expenseToDelete && (
          <div className="fixed inset-0 z-[120] flex items-center justify-center p-6 bg-black/20 backdrop-blur-sm">
