CREATE POLICY "Admin can see all" ON public.profiles FOR SELECT USING (
  (auth.jwt() ->> 'email') = 'admin@mintflow.com'
);

CREATE POLICY "Admin can update all" ON public.profiles FOR UPDATE USING (
  (auth.jwt() ->> 'email') = 'admin@mintflow.com'
);
