import { createClient } from '@supabase/supabase-js';

// Assicurati di avere queste variabili in .env
const supabaseUrl = process.env.REACT_APP_SUPABASE_URL || '';
const supabaseKey = process.env.REACT_APP_SUPABASE_ANON_KEY || '';

export const supabase = createClient(supabaseUrl, supabaseKey);
export const auth = supabase.auth;

export const db = {
  // 1. Ottieni tutti i profili
  getAllProfiles: async () => {
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .order('created_at', { ascending: false }); // Assumendo ci sia created_at, o usa last_login

    if (error) throw error;
    return data;
  },

  // 2. Aggiorna stato (Attivo/Disabilitato)
  updateUserStatus: async (id: string, status: 'active' | 'disabled') => {
    const { error } = await supabase
      .from('profiles')
      .update({ status })
      .eq('id', id);

    if (error) throw error;
  },

  // 3. Elimina profilo (Attenzione: elimina solo da 'profiles', non da Auth!)
  deleteProfile: async (id: string) => {
    const { error } = await supabase
      .from('profiles')
      .delete()
      .eq('id', id);

    if (error) throw error;
