  // 4. Invia notifica (Aggiorna colonna 'notification')
  sendNotification: async (id: string, message: string) => {
    const { error } = await supabase
      .from('profiles')
      .update({ notification: message }) // Assicurati che la colonna esista
      .eq('id', id);

