      })
      .select();
    if (error) throw error;
    return data;
  },

  // Ottiene tutti i profili per la Dashboard
  async getAllProfiles() {
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .order('email');
    if (error) throw error;
    return data || [];
  },

  // QUESTA È LA FUNZIONE CHE MANCAVA!
  async updateUserStatus(id: string, status: 'active' | 'disabled') {
    const { data, error } = await supabase
      .from('profiles')
      .update({ status: status })
      .eq('id', id)
      .select(); // Fondamentale per confermare l'avvenuta modifica

    if (error) throw error;
    return data;
  },

  // Invia notifica (salvata nella colonna notification)
  async sendNotification(id: string, message: string) {
    const { error } = await supabase
      .from('profiles')
