import { useEffect } from 'react';
import { supabase } from './services/supabase'; // Assicurati che il percorso sia corretto

function App() {
  useEffect(() => {
    // 1. Ascolta i cambiamenti di stato (Login, Logout, Refresh)
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {

      if (session?.user) {
        // 2. Ogni volta che un utente è loggato, controlliamo il suo profilo nel DB
        const { data: profile, error } = await supabase
          .from('profiles')
          .select('status')
          .eq('id', session.user.id)
          .single();

        if (error) {
          console.error("Errore controllo sicurezza:", error.message);
          return;
        }

        // 3. IL BLOCCO: Se lo stato è 'disabled', forziamo il logout
        if (profile && profile.status === 'disabled') {
          await supabase.auth.signOut();

          // Messaggio all'utente e reindirizzamento
          alert("⛔ ACCOUNT DISABILITATO\n\nIl tuo accesso è stato revocato dall'amministratore.");
          window.location.href = '/login'; 
        }
      }
    });

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  // ... resto del tuo componente App
}

