import React, { useState } from 'react';
import db from '../services/supabase';

interface AdminDashboardProps {
  userId: string;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ userId }) => {
  const [userStatus, setUserStatus] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState('');

  const handleToggleStatus = async () => {
    setIsLoading(true);
    setMessage(''); // Clear any previous messages
    try {
      const { data } = await db.updateUserStatus(userId, !userStatus);

      if (!data) { // Check for empty or null data response
        console.error('Error updating user status: No data returned');
        setMessage('Failed to update user status due to RLS or other database errors.');
      } else {
        setUserStatus(!userStatus);
        setMessage(`User status updated to ${!userStatus ? 'active' : 'disabled'}`);
      }
    } catch (error) {
      console.error('Error updating user status:', error);
      setMessage(`Failed to update user status: ${error}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div>
      {/* ... other admin dashboard content ... */}
      <button onClick={handleToggleStatus} disabled={isLoading}>
        {isLoading ? 'Updating...' : `Toggle Status to ${userStatus ? 'Active' : 'Disabled'}`}
      </button>
      {message && <p>{message}</p>}
    </div>
  );
};

export default AdminDashboard;


