import { Shield, Users, Bell, Trash2, Ban, Key, Search, LogOut, CheckCircle2, X, Send, AlertTriangle, Mail, Loader2, Database, Terminal, Copy, Menu } from 'lucide-react';
import { auth, db } from '../services/supabase';
import { format } from 'date-fns';
import it from 'date-fns/locale/it';
import React, { useState, useEffect } from 'react';

interface AdminUser {
  id: string;
  email: string;
  display_name: string;
  status: 'active' | 'disabled';
  last_login: string;
  role: 'user' | 'admin';
}

interface AdminDashboardProps {
  onLogout: () => void;
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout }) => {
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState<AdminUser | null>(null);
  const [showNotifyModal, setShowNotifyModal] = useState(false);
  const [showSqlModal, setShowSqlModal] = useState(false);
  const [notificationText, setNotificationText] = useState('');
  const [toast, setToast] = useState<{msg: string, type: 'success' | 'error'} | null>(null);

  const fetchUsers = async () => {
    setLoading(true);
    setError(null);
    try {
        // Carichiamo esclusivamente i profili reali dal database
        const data = await db.getAllProfiles();
        setUsers(data as AdminUser[]);
        console.log("Utenti caricati dal DB:", data);
    } catch (err: any) {
        console.error("Errore fetch:", err);
        setError("Errore nel caricamento dal database.");
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => { fetchUsers(); }, []);

  const showToast = (msg: string, type: 'success' | 'error' = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleToggleStatus = async (id: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    const user = users.find(u => u.id === id);
    if (!user) return;

    const newStatus = user.status === 'active' ? 'disabled' : 'active';
    const actionLabel = user.status === 'active' ? 'DISABILITARE' : 'RIATTIVARE';

    if (window.confirm(`SEI SICURO?\n\nStai per ${actionLabel} l'utente:\n${user.display_name || user.email}`)) {
        try {
            const data = await db.updateUserStatus(id, newStatus);
            // Verifica RLS: se il database non restituisce nulla, la modifica è stata bloccata dalle policy
            if (!data || data.length === 0) {
                 alert("Errore: Il database ha ricevuto il comando ma ha rifiutato la modifica (RLS).\n\nAssicurati di essere loggato come 'admin@mintflow.com' nel database reale e di aver eseguito lo script SQL di configurazione.");
                 return;
            }
            setUsers(prev => prev.map(u => u.id === id ? { ...u, status: newStatus } : u));
            showToast(`Utente ${newStatus === 'active' ? 'riattivato' : 'disabilitato'} con successo`);
        } catch (err: any) {
            console.error("Errore completo:", err);
            showToast("Errore durante l'aggiornamento: " + err.message, "error");
        }
    }
  };

  const handleSendNotification = async () => {
    if (!notificationText.trim() || !selectedUser) return;
    try {
      await db.sendNotification(selectedUser.id, notificationText);
      showToast(`Notifica inviata a ${selectedUser.email}`);
      setShowNotifyModal(false);
      setNotificationText('');
      setSelectedUser(null);
    } catch (err: any) {
      showToast('Errore invio notifica: ' + err.message, 'error');
    }
  };

  const filteredUsers = users.filter(u => 
    (u.email || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
    (u.display_name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white pb-20 md:pb-0">
      {toast && (
        <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[150] px-6 py-3 rounded-2xl shadow-xl flex items-center gap-2 animate-in slide-in-from-top-4 ${toast.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-500 text-white'}`}>
          {toast.type === 'success' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
          <span className="font-bold text-sm">{toast.msg}</span>
        </div>
      )}

      <header className="bg-white dark:bg-gray-800 border-b sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Shield className="text-emerald-500" size={32} />
            <h1 className="text-xl font-black">MintFlow <span className="text-emerald-500">Admin</span></h1>
          </div>
          <div className="flex items-center gap-4">
            <button onClick={() => setShowSqlModal(true)} className="p-2 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 rounded-xl"><Database size={20} /></button>
            <button onClick={onLogout} className="flex items-center gap-2 px-4 py-2 bg-gray-100 dark:bg-gray-700 rounded-xl font-bold"><LogOut size={20} /> Esci</button>
          </div>
        </div>
      </header>

