import { createClient } from '@supabase/supabase-js';
import { Expense, PaymentMethod, ProfileType } from '../types';

const SUPABASE_URL = 'https://jpcweqcqysxgzycftzyv.supabase.co';
const SUPABASE_ANON_KEY = 'sb_publishable_qdb7pW6R-6vvGaoeuGE5fw_xuPgZweE';

export const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
const getRedirectUrl = () => window.location.origin;

const PACK_SEP = ' |#| ';

const packDescription = (desc: string, pm: PaymentMethod, isSub: boolean, profile: ProfileType, isExtra: boolean, extraType: string) => {
  return `${desc}${PACK_SEP}${pm}${PACK_SEP}${isSub}${PACK_SEP}${profile}${PACK_SEP}${isExtra}${PACK_SEP}${extraType}`;
};

const unpackDescription = (packedStr: string) => {
  if (!packedStr || !packedStr.includes(PACK_SEP)) {
    return { 
      desc: packedStr, 
      pm: PaymentMethod.Contanti, 
      isSub: false, 
      profile: 'personal' as ProfileType,
      isExtra: false,
      extraType: 'given' as 'given' | 'received'
    };
  }
  const parts = packedStr.split(PACK_SEP);
  return {
    desc: parts[0],
    pm: (parts[1] as PaymentMethod) || PaymentMethod.Contanti,
    isSub: parts[2] === 'true',
    profile: (parts[3] as ProfileType) || 'personal',
    isExtra: parts[4] === 'true',
    extraType: (parts[5] as 'given' | 'received') || 'given'
  };
};

export const auth = {
  async signUp(email: string, password: string, username: string) {
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: { data: { display_name: username }, emailRedirectTo: getRedirectUrl() }
    });
    if (error) throw error;
    if (data.user) {
        try {
            await db.upsertProfile(data.user.id, email, username);
        } catch (e) {
            console.error("Errore creazione profilo iniziale:", e);
        }
    }
    return data;
  },
  async resendConfirmation(email: string) {
    const { error } = await supabase.auth.resend({ type: 'signup', email, options: { emailRedirectTo: getRedirectUrl() } });
    if (error) throw error;
  },
  async signIn(email: string, password: string) {
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) throw error;
    return data;
  },
  async resetPassword(email: string) {
    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: getRedirectUrl(),
    });
    if (error) throw error;
  },
  async signOut() {
    const { error } = await supabase.auth.signOut();
    if (error) throw error;
  },
  async updateProfile(name: string) {
    const { data, error } = await supabase.auth.updateUser({ data: { display_name: name } });
    if (error) throw error;
    if (data.user) {
        await db.upsertProfile(data.user.id, data.user.email || '', name);
    }
    return data;
  },
  async updateEmail(newEmail: string) {
    const { data, error } = await supabase.auth.updateUser({ email: newEmail }, { emailRedirectTo: getRedirectUrl() });
    if (error) throw error;
    return data;
  },
  async updatePassword(password: string) {
    const { data, error } = await supabase.auth.updateUser({ password });
    if (error) throw error;
    return data;
  },
  async deleteAccount() {
    const { data: { user } } = await supabase.auth.getUser();
    if (user) {
      await db.clearAll(user.id);
      try {
        await supabase.from('profiles').delete().eq('id', user.id);
      } catch (e) {
        console.error("Errore cancellazione profilo", e);
      }
      await this.signOut();
    }
  }
};

export const db = {
  async upsertProfile(id: string, email: string, name: string) {
    const role = email === 'admin@mintflow.com' ? 'admin' : 'user';
    const { data, error } = await supabase
      .from('profiles')
      .upsert({ 
        id, 
        email, 
        display_name: name,
        role,
        // RIMOSSO: status: 'active' - Per evitare di sovrascrivere lo stato manuale disabled
        last_login: new Date().toISOString() 
      }, { onConflict: 'id' })
      .select();
    if (error) throw error;
    return data;
  },

  async getAllProfiles() {
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .order('email');
    if (error) throw error;
    return data || [];
  },

  async getProfile(userId: string) {
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', userId)
      .single();
    if (error) return null;
    return data;
  },

  async updateUserStatus(id: string, status: 'active' | 'disabled') {
    const { data, error } = await supabase
      .from('profiles')
      .update({ status: status })
      .eq('id', id)
      .select();

    if (error) throw error;
    return data;
  },

  async sendNotification(id: string, message: string) {
    const { error } = await supabase
      .from('profiles')
      .update({ notification: message })
      .eq('id', id);
    if (error) throw error;
  },

  async clearNotification(userId: string) {
      const { error } = await supabase.from('profiles').update({ notification: null }).eq('id', userId);
      if (error) throw error;
  },

  async getExpenses(userId: string): Promise<Expense[]> {
    const { data, error } = await supabase
      .from('expenses')
      .select('*')
      .eq('user_id', userId)
      .order('date', { ascending: false });
    if (error) throw error;
    return (data || []).map((e: any) => {
      const unpacked = unpackDescription(e.description);
      return {
        id: e.id,
        amount: e.amount,
        category: e.category,
        date: e.date,
        description: unpacked.desc,
        paymentMethod: unpacked.pm,
        isSubscription: unpacked.isSub,
        profile: unpacked.profile,
        isExtra: unpacked.isExtra,
        extraType: unpacked.extraType
      };
    });
  },

  async addExpense(expense: Omit<Expense, 'id'>, userId: string): Promise<Expense> {
    const packedDesc = packDescription(
      expense.description, 
      expense.paymentMethod, 
      !!expense.isSubscription,
      expense.profile || 'personal',
      !!expense.isExtra,
      expense.extraType || 'given'
    );
    const { data, error } = await supabase.from('expenses').insert([{
      description: packedDesc,
      amount: expense.amount,
      category: expense.category,
      date: expense.date,
      user_id: userId
    }]).select().single();
    if (error) throw error;
    return {
      id: data.id,
      ...expense
    };
  },

  async updateExpense(id: string, expense: Partial<Omit<Expense, 'id'>>): Promise<Expense> {
    const { data: current } = await supabase.from('expenses').select('description').eq('id', id).single();
    const currentUnpacked = unpackDescription(current?.description || '');
    const newDesc = expense.description !== undefined ? expense.description : currentUnpacked.desc;
    const newPM = expense.paymentMethod !== undefined ? expense.paymentMethod : currentUnpacked.pm;
    const newIsSub = expense.isSubscription !== undefined ? expense.isSubscription : currentUnpacked.isSub;
    const newProfile = expense.profile !== undefined ? expense.profile : currentUnpacked.profile;
    const newIsExtra = expense.isExtra !== undefined ? expense.isExtra : currentUnpacked.isExtra;
    const newExtraType = expense.extraType !== undefined ? expense.extraType : currentUnpacked.extraType;

    const { data, error } = await supabase.from('expenses').update({
      description: packDescription(newDesc, newPM, newIsSub, newProfile, newIsExtra, newExtraType),
      amount: expense.amount,
      category: expense.category,
      date: expense.date
    }).eq('id', id).select().single();
    if (error) throw error;
    const unpacked = unpackDescription(data.description);
    return {
      id: data.id,
      amount: data.amount,
      category: data.category,
      date: data.date,
      description: unpacked.desc,
      paymentMethod: unpacked.pm,
      isSubscription: unpacked.isSub,
      profile: unpacked.profile,
      isExtra: unpacked.isExtra,
      extraType: unpacked.extraType
    };
  },

  async deleteExpense(id: string) {
    const { error } = await supabase.from('expenses').delete().eq('id', id);
    if (error) throw error;
  },

  async clearAll(userId: string) {
    const { error } = await supabase.from('expenses').delete().eq('user_id', userId);
    if (error) throw error;
  }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ExpenseList } from './components/ExpenseList';
import { ExpenseForm } from './components/ExpenseForm';
import { AiInsights } from './components/AiInsights';
import { SettingsView } from './components/SettingsView';
import { RicaricheView } from './components/RicaricheView';
import { SubscriptionsView } from './components/SubscriptionsView';
import { ExtraView } from './components/ExtraView';
import { Auth } from './components/Auth';
import { AdminDashboard } from './components/AdminDashboard';
import { Expense, UserSettings, PaymentMethod, WalletConfig, CategoryConfig, ProfileType } from './types';
import { Plus, Loader2, ShieldAlert, Target, Mail, X, LogOut, ShieldCheck } from 'lucide-react';
import { db, auth, supabase } from './services/supabase';
import { format, isSameMonth } from 'date-fns';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [allExpenses, setAllExpenses] = useState<Expense[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [successToast, setSuccessToast] = useState<string | null>(null);

  // STATO SICUREZZA (null = controllo in corso, true = bannato, false = attivo)
  const [isBanned, setIsBanned] = useState<boolean | null>(null);
  const [expenseToDelete, setExpenseToDelete] = useState<string | null>(null);

  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('mintflow_user_settings');
    const defaultWallets: WalletConfig[] = [
      { id: 'w0', name: 'Contanti', method: PaymentMethod.Contanti, icon: 'wallet' },
      { id: 'w1', name: 'Prepagata Flash', method: PaymentMethod.Flash, icon: 'zap' },
      { id: 'w2', name: 'Prepagata Revolut', method: PaymentMethod.Revolut, icon: 'credit-card' },
      { id: 'w3', name: 'App Q8', method: PaymentMethod.AppQ8, icon: 'fuel' }
    ];

    const defaultCategories: CategoryConfig[] = [
      { id: 'c1', name: 'Sigarette', color: '#ef4444' },
      { id: 'c2', name: 'Benzina', color: '#f97316' },
      { id: 'c3', name: 'Autostrada', color: '#eab308' },
      { id: 'c4', name: 'Ricarica Chiavetta', color: '#84cc16' },
      { id: 'c5', name: 'Svago', color: '#06b6d4' },
      { id: 'c6', name: 'Salute', color: '#ec4899' },
      { id: 'c7', name: 'Abbonamenti', isSubscriptionDefault: true, color: '#8b5cf6' },
      { id: 'c8', name: 'Altro', color: '#64748b' }
    ];

    const defaultSettings: UserSettings = {
      name: 'Utente',
      monthlyBudget: 1000,
      currency: '€',
      isDarkMode: false,
      wallets: defaultWallets,
      categories: defaultCategories,
      language: 'it',
      currentProfile: 'personal',
      monthlyOffset: 0,
      lastOffsetDate: new Date().toISOString()
    };

    if (!saved) return defaultSettings;
    try {
      const parsed = JSON.parse(saved);
      const merged = { ...defaultSettings, ...parsed, currentProfile: 'personal' };
      const now = new Date();
      const lastOffsetDate = merged.lastOffsetDate ? new Date(merged.lastOffsetDate) : null;
      if (!lastOffsetDate || !isSameMonth(lastOffsetDate, now)) {
        merged.monthlyOffset = 0;
        merged.lastOffsetDate = now.toISOString();
      }
      return merged;
    } catch { return defaultSettings; }
  });

  useEffect(() => {
    if (userSettings.isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [userSettings.isDarkMode]);

  const expenses = useMemo(() => allExpenses.filter(e => (e.profile || 'personal') === 'personal' && !e.isExtra), [allExpenses]);
  const extraExpenses = useMemo(() => allExpenses.filter(e => (e.profile || 'personal') === 'personal' && e.isExtra), [allExpenses]);
  const currentBudget = userSettings.monthlyBudget;

  useEffect(() => {
    localStorage.setItem('mintflow_user_settings', JSON.stringify(userSettings));
  }, [userSettings]);

  const [activeTab, setActiveTab] = useState<'dashboard' | 'list' | 'ricariche' | 'ai' | 'settings' | 'subscriptions' | 'extra'>('dashboard');
  const [showForm, setShowForm] = useState(false);
  const [prefill, setPrefill] = useState<Partial<Expense> | null>(null);

  // --- SISTEMA DI SICUREZZA INFALLIBILE ---
  useEffect(() => {
    let channel: any;

    const checkStatus = async (userId: string) => {
      console.log("[Security] Controllo stato per utente:", userId);
      try {
        const { data, error } = await supabase
          .from('profiles')
          .select('status')
          .eq('id', userId)
          .single();

        if (error) {
          console.error("[Security] Errore database:", error.message);
          setIsBanned(false);
          return false;
        }

        console.log("[Security] Stato ricevuto dal DB:", data.status);
        const banned = data.status === 'disabled';
        setIsBanned(banned);
        return banned;
      } catch (e) {
        console.error("[Security] Errore critico:", e);
        setIsBanned(false);
        return false;
      }
    };

    const initSecurity = async () => {
      const { data: { session: currentSession } } = await supabase.auth.getSession();
      setSession(currentSession);

      if (currentSession?.user) {
        // 1. PRIMA controlla lo stato
        const banned = await checkStatus(currentSession.user.id);

        // 2. SOLO se NON è bannato, procedi con l'aggiornamento (upsert)
        if (!banned) {
          const metadata = currentSession.user.user_metadata;
          const displayName = metadata.full_name || metadata.display_name || metadata.name || currentSession.user.email?.split('@')[0] || 'Utente';
          setUserSettings(prev => ({ ...prev, name: displayName }));

          await db.upsertProfile(currentSession.user.id, currentSession.user.email || '', displayName);
        }
      } else {
        setIsBanned(false);
      }
      setIsInitialLoading(false);
    };

    initSecurity();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, currentSession) => {
      setSession(currentSession);
      if (currentSession?.user) {
        const banned = await checkStatus(currentSession.user.id);

        if (channel) supabase.removeChannel(channel);

        channel = supabase
          .channel(`security-monitor-${currentSession.user.id}`)
          .on('postgres_changes', { 
            event: 'UPDATE', 
            schema: 'public', 
            table: 'profiles',
            filter: `id=eq.${currentSession.user.id}` 
          }, (payload) => {
            console.log("[Security] Realtime update rilevato:", payload.new.status);
            setIsBanned(payload.new.status === 'disabled');
          })
          .subscribe();

        if (!banned && event === 'SIGNED_IN') {
          const metadata = currentSession.user.user_metadata;
          const displayName = metadata.full_name || metadata.display_name || metadata.name || currentSession.user.email?.split('@')[0] || 'Utente';
          await db.upsertProfile(currentSession.user.id, currentSession.user.email || '', displayName);
        }
      } else {
        setIsBanned(false);
        if (channel) supabase.removeChannel(channel);
      }
    });

    return () => {
      subscription.unsubscribe();
      if (channel) supabase.removeChannel(channel);
    };
  }, []);

  const fetchExpenses = useCallback(async () => {
    if (!session?.user?.id || isBanned) return;
    try {
      setIsLoading(true);
      const data = await db.getExpenses(session.user.id);
      setAllExpenses(data);
    } catch (err) {
      console.error("Errore caricamento:", err);
    } finally {
      setIsLoading(false);
    }
  }, [session, isBanned]);

  useEffect(() => { if (session?.user?.id) fetchExpenses(); }, [session, fetchExpenses]);

  const handleAdminLogin = () => {
    auth.signIn('admin@mintflow.com', 'admin123').then(() => {
        window.location.reload();
    }).catch(() => {
        alert("Credenziali admin errate.");
    });
  };

  const handleForcedLogout = async () => {
    await supabase.auth.signOut();
    window.location.reload();
  };

  const handleSaveExpense = async (expenseData: Omit<Expense, 'id'>) => {
    try {
      setIsSyncing(true);
      const dataToSave = { ...expenseData, profile: 'personal' as ProfileType };
      let saved: Expense;
      if (prefill?.id) saved = await db.updateExpense(prefill.id, dataToSave);
      else saved = await db.addExpense(dataToSave, session.user.id);
      setAllExpenses(prev => prefill?.id ? prev.map(e => e.id === saved.id ? saved : e) : [saved, ...prev]);
      setShowForm(false);
      setPrefill(null);
      setSuccessToast("Operazione completata!");
      setTimeout(() => setSuccessToast(null), 3000);
    } catch (err: any) { alert(`Errore: ${err.message}`); }
    finally { setIsSyncing(false); }
  };

  // Caricamento iniziale
  if (isInitialLoading || isBanned === null) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-mint-50 dark:bg-gray-900">
        <Loader2 className="animate-spin text-emerald-500" size={48} />
      </div>
    );
  }

  // Se l'utente è bannato, MOSTRA SOLO LA LOCK SCREEN (Rendering Esclusivo)
  if (isBanned === true) {
    return (
      <div className="fixed inset-0 z-[999999] bg-white dark:bg-gray-950 flex items-center justify-center p-6 touch-none overflow-hidden">
        <div className="absolute inset-0 bg-mint-50/50 dark:bg-emerald-950/20 backdrop-blur-3xl" />
        <div className="max-w-md w-full bg-white dark:bg-gray-800 rounded-[3.5rem] p-12 text-center shadow-[0_32px_64px_-15px_rgba(0,0,0,0.2)] border border-emerald-100 dark:border-gray-700 relative z-10 animate-in zoom-in-95 duration-300">
          <div className="relative w-24 h-24 mx-auto mb-10">
            <div className="absolute inset-0 bg-red-500/20 rounded-full animate-ping" />
            <div className="relative w-full h-full bg-red-50 dark:bg-red-900/30 rounded-full flex items-center justify-center border-4 border-white dark:border-gray-800 shadow-inner">
              <ShieldAlert className="text-red-500" size={48} />
            </div>
          </div>

          <h2 className="text-3xl font-black text-gray-900 dark:text-white mb-4 tracking-tight">Accesso Sospeso</h2>
          <p className="text-gray-500 dark:text-gray-400 font-medium mb-10 leading-relaxed px-2">
            Il tuo account MintFlow è stato temporaneamente limitato dall'amministratore. Contatta il supporto per maggiori informazioni o esci per cambiare account.
          </p>

          <div className="space-y-4">
            <a href="mailto:assistenza@mintflow.com" className="flex items-center justify-center gap-2 w-full py-5 bg-emerald-500 text-white rounded-3xl font-bold hover:bg-emerald-600 shadow-lg shadow-emerald-200 dark:shadow-none transition-all active:scale-95">
              <Mail size={20} /> Contatta Supporto
            </a>

            <button 
              onClick={handleForcedLogout}
              className="flex items-center justify-center gap-2 w-full py-5 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-200 rounded-3xl font-bold hover:bg-gray-200 dark:hover:bg-gray-600 transition-all active:scale-95"
            >
              <LogOut size={20} /> Esci dall'account
            </button>
          </div>

          <div className="mt-12 pt-8 border-t border-gray-100 dark:border-gray-700 flex items-center justify-center gap-2 opacity-50">
            <ShieldCheck size={14} className="text-emerald-500" />
            <p className="text-[10px] text-gray-400 font-bold uppercase tracking-[0.2em]">Protection Service Active</p>
          </div>
        </div>
      </div>
    );
  }

  // Se non c'è sessione, mostra il login
  if (!session) {
    return <Auth onSuccess={() => setIsBanned(false)} onAdminLogin={handleAdminLogin} />;
  }

  // Se è l'admin, mostra la dashboard admin
  if (session.user.email === 'admin@mintflow.com') {
    return <AdminDashboard onLogout={() => setSession(null)} />;
  }

  // Rendering normale dell'app se attivo
  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} lang={userSettings.language}>
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24 relative">
        {successToast && <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-emerald-600 text-white px-6 py-3 rounded-2xl shadow-xl animate-in slide-in-from-top-4">{successToast}</div>}
        {activeTab === 'dashboard' && <Dashboard expenses={expenses} budget={currentBudget} userName={userSettings.name} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} lang={userSettings.language} userSettings={userSettings} onUpdateSettings={setUserSettings} />}
        {activeTab === 'list' && (
          <div className="space-y-6">
            <button onClick={() => { setPrefill(null); setShowForm(true); }} className="w-full bg-emerald-500 text-white py-4 rounded-2xl flex items-center justify-center gap-2 font-bold shadow-lg transition-transform active:scale-95"><Plus size={20} /> Aggiungi Spesa</button>
            <ExpenseList expenses={expenses} onDelete={id => setExpenseToDelete(id)} onEdit={ex => { setPrefill(ex); setShowForm(true); }} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} />
          </div>
        )}
        {activeTab === 'ricariche' && <RicaricheView onRefill={w => { setPrefill({ description: `Ricarica ${w.name}`, category: 'Altro', paymentMethod: PaymentMethod.Bancomat, date: format(new Date(), 'yyyy-MM-dd') }); setShowForm(true); }} onSaveExpense={handleSaveExpense} onUpdateWallets={w => setUserSettings(prev => ({ ...prev, wallets: w }))} expenses={expenses} currency={userSettings.currency} wallets={userSettings.wallets} />}
        {activeTab === 'ai' && <AiInsights expenses={expenses} />}
        {activeTab === 'settings' && <SettingsView settings={userSettings} onUpdate={setUserSettings} onClearData={() => {}} expenses={expenses} email={session.user.email} />}
        {activeTab === 'subscriptions' && <SubscriptionsView expenses={expenses} onAddSub={() => { setPrefill({ isSubscription: true }); setShowForm(true); }} onDelete={id => setExpenseToDelete(id)} currency={userSettings.currency} />}
        {activeTab === 'extra' && <ExtraView expenses={extraExpenses} onAdd={handleSaveExpense} onDelete={id => setExpenseToDelete(id)} currency={userSettings.currency} />}

        {showForm && (
          <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[70] flex items-center justify-center p-4">
            <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-md p-8 shadow-2xl relative animate-in zoom-in-95 duration-200">
              <button onClick={() => setShowForm(false)} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 dark:hover:text-white transition-colors"><X size={24} /></button>
              <h2 className="text-2xl font-bold mb-6 dark:text-white">{prefill?.id ? 'Modifica Spesa' : 'Nuova Spesa'}</h2>
              <ExpenseForm onSubmit={handleSaveExpense} onCancel={() => setShowForm(false)} initialData={prefill || undefined} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} expenses={expenses} />
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
};

export default App;

