import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ExpenseList } from './components/ExpenseList';
import { ExpenseForm } from './components/ExpenseForm';
import { AiInsights } from './components/AiInsights';
import { SettingsView } from './components/SettingsView';
import { RicaricheView } from './components/RicaricheView';
import { SubscriptionsView } from './components/SubscriptionsView';
import { ExtraView } from './components/ExtraView';
import { Auth } from './components/Auth';
import { AdminDashboard } from './components/AdminDashboard';
import { Expense, UserSettings, PaymentMethod, WalletConfig, CategoryConfig, ProfileType } from './types';
import { Plus, Loader2, ShieldAlert, Mail, X, LogOut, ShieldCheck } from 'lucide-react';
import { db, auth, supabase } from './services/supabase';
import { format, isSameMonth } from 'date-fns';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [allExpenses, setAllExpenses] = useState<Expense[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [successToast, setSuccessToast] = useState<string | null>(null);

  // STATO SICUREZZA (null = in controllo, true = bannato, false = attivo)
  const [isBanned, setIsBanned] = useState<boolean | null>(null);

  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('mintflow_user_settings');
    const defaultWallets: WalletConfig[] = [
      { id: 'w0', name: 'Contanti', method: PaymentMethod.Contanti, icon: 'wallet' },
      { id: 'w1', name: 'Prepagata Flash', method: PaymentMethod.Flash, icon: 'zap' },
      { id: 'w2', name: 'Prepagata Revolut', method: PaymentMethod.Revolut, icon: 'credit-card' },
      { id: 'w3', name: 'App Q8', method: PaymentMethod.AppQ8, icon: 'fuel' }
    ];

    const defaultCategories: CategoryConfig[] = [
      { id: 'c1', name: 'Sigarette', color: '#ef4444' },
      { id: 'c2', name: 'Benzina', color: '#f97316' },
      { id: 'c3', name: 'Autostrada', color: '#eab308' },
      { id: 'c4', name: 'Ricarica Chiavetta', color: '#84cc16' },
      { id: 'c5', name: 'Svago', color: '#06b6d4' },
      { id: 'c6', name: 'Salute', color: '#ec4899' },
      { id: 'c7', name: 'Abbonamenti', isSubscriptionDefault: true, color: '#8b5cf6' },
      { id: 'c8', name: 'Altro', color: '#64748b' }
    ];

    const defaultSettings: UserSettings = {
      name: 'Utente',
      monthlyBudget: 1000,
      currency: '€',
      isDarkMode: false,
      wallets: defaultWallets,
      categories: defaultCategories,
      language: 'it',
      currentProfile: 'personal',
      monthlyOffset: 0,
      lastOffsetDate: new Date().toISOString()
    };

    if (!saved) return defaultSettings;
    try {
      const parsed = JSON.parse(saved);
      const merged = { ...defaultSettings, ...parsed, currentProfile: 'personal' };
      const now = new Date();
      const lastOffsetDate = merged.lastOffsetDate ? new Date(merged.lastOffsetDate) : null;
      if (!lastOffsetDate || !isSameMonth(lastOffsetDate, now)) {
        merged.monthlyOffset = 0;
        merged.lastOffsetDate = now.toISOString();
      }
      return merged;
    } catch { return defaultSettings; }
  });

  useEffect(() => {
    if (userSettings.isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [userSettings.isDarkMode]);

  const expenses = useMemo(() => allExpenses.filter(e => (e.profile || 'personal') === 'personal' && !e.isExtra), [allExpenses]);
  const extraExpenses = useMemo(() => allExpenses.filter(e => (e.profile || 'personal') === 'personal' && e.isExtra), [allExpenses]);
  const currentBudget = userSettings.monthlyBudget;

  useEffect(() => {
    localStorage.setItem('mintflow_user_settings', JSON.stringify(userSettings));
  }, [userSettings]);

  const [activeTab, setActiveTab] = useState<'dashboard' | 'list' | 'ricariche' | 'ai' | 'settings' | 'subscriptions' | 'extra'>('dashboard');
  const [showForm, setShowForm] = useState(false);
  const [prefill, setPrefill] = useState<Partial<Expense> | null>(null);

  // --- LOGICA DI SICUREZZA INFALLIBILE ---
  useEffect(() => {
    let channel: any;

    const checkStatus = async (userId: string) => {
      console.log("[Security] Controllo stato per utente:", userId);
      try {
        const { data, error } = await supabase
          .from('profiles')
          .select('status')
          .eq('id', userId)
          .single();

        if (error) {
          console.error("[Security] Errore database:", error.message);
          setIsBanned(false);
          return false;
        }

        console.log("[Security] Stato ricevuto dal DB:", data.status);
        const banned = data.status === 'disabled';
        setIsBanned(banned);
        return banned;
      } catch (e) {
        console.error("[Security] Errore critico:", e);
        setIsBanned(false);
        return false;
      }
    };

    const initSecurity = async () => {
      const { data: { session: currentSession } } = await supabase.auth.getSession();
      setSession(currentSession);

      if (currentSession?.user) {
        // 1. PRIMA controlla lo stato
        const banned = await checkStatus(currentSession.user.id);

        // 2. SOLO se NON è bannato, procedi con l'aggiornamento (upsert)
        if (!banned) {
          const metadata = currentSession.user.user_metadata;
          const displayName = metadata.full_name || metadata.display_name || metadata.name || currentSession.user.email?.split('@')[0] || 'Utente';
          setUserSettings(prev => ({ ...prev, name: displayName }));
          await db.upsertProfile(currentSession.user.id, currentSession.user.email || '', displayName);
        }

        // 3. REALTIME: Ascolta i cambiamenti di stato
        if (channel) supabase.removeChannel(channel);
        channel = supabase
          .channel(`security-${currentSession.user.id}`)
          .on('postgres_changes', { 
            event: 'UPDATE', 
            schema: 'public', 
            table: 'profiles',
            filter: `id=eq.${currentSession.user.id}` 
          }, (payload) => {
            console.log("[Security] Realtime change rilevato:", payload.new.status);
            setIsBanned(payload.new.status === 'disabled');
          })
          .subscribe();
      } else {
        setIsBanned(false);
      }
      setIsInitialLoading(false);
    };

    initSecurity();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, currentSession) => {
      setSession(currentSession);
      if (currentSession?.user) {
        // Ad ogni cambio sessione, riverifica
        const banned = await checkStatus(currentSession.user.id);
        if (!banned && event === 'SIGNED_IN') {
           const metadata = currentSession.user.user_metadata;
           const displayName = metadata.full_name || metadata.display_name || metadata.name || currentSession.user.email?.split('@')[0] || 'Utente';
           await db.upsertProfile(currentSession.user.id, currentSession.user.email || '', displayName);
        }
      } else {
        setIsBanned(false);
        if (channel) supabase.removeChannel(channel);
      }
    });

    return () => {
      subscription.unsubscribe();
      if (channel) supabase.removeChannel(channel);
    };
  }, []);

  const fetchExpenses = useCallback(async () => {
    if (!session?.user?.id || isBanned) return;
    try {
      setIsLoading(true);
      const data = await db.getExpenses(session.user.id);
      setAllExpenses(data);
    } catch (err) {
      console.error("Errore caricamento:", err);
    } finally {
      setIsLoading(false);
    }
  }, [session, isBanned]);

  useEffect(() => { if (session?.user?.id) fetchExpenses(); }, [session, fetchExpenses]);

  const handleForcedLogout = async () => {
    await supabase.auth.signOut();
    window.location.reload();
  };

  const handleSaveExpense = async (expenseData: Omit<Expense, 'id'>) => {
    try {
      setIsSyncing(true);
      const dataToSave = { ...expenseData, profile: 'personal' as ProfileType };
      let saved: Expense;
      if (prefill?.id) saved = await db.updateExpense(prefill.id, dataToSave);
      else saved = await db.addExpense(dataToSave, session.user.id);
      setAllExpenses(prev => prefill?.id ? prev.map(e => e.id === saved.id ? saved : e) : [saved, ...prev]);
      setShowForm(false);
      setPrefill(null);
      setSuccessToast("Operazione completata!");
      setTimeout(() => setSuccessToast(null), 3000);
    } catch (err: any) { alert(`Errore: ${err.message}`); }
    finally { setIsSyncing(false); }
  };

  if (isInitialLoading || isBanned === null) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-mint-50 dark:bg-gray-900">
        <Loader2 className="animate-spin text-emerald-500" size={48} />
      </div>
    );
  }

  // BLOCCO TOTALE (Realtime)
  if (isBanned === true) {
    return (
      <div className="fixed inset-0 z-[999999] bg-white dark:bg-gray-950 flex items-center justify-center p-6 touch-none overflow-hidden">
        <div className="absolute inset-0 bg-mint-50/50 dark:bg-emerald-950/10 backdrop-blur-3xl" />
        <div className="max-w-md w-full bg-white dark:bg-gray-800 rounded-[3.5rem] p-12 text-center shadow-[0_32px_64px_-15px_rgba(0,0,0,0.2)] border border-emerald-100 dark:border-gray-700 relative z-10 animate-in zoom-in-95 duration-300">
          <div className="relative w-24 h-24 mx-auto mb-10">
            <div className="absolute inset-0 bg-red-500/20 rounded-full animate-ping" />
            <div className="relative w-full h-full bg-red-50 dark:bg-red-900/30 rounded-full flex items-center justify-center border-4 border-white dark:border-gray-800 shadow-inner">
              <ShieldAlert className="text-red-500" size={48} />
            </div>
          </div>
          <h2 className="text-3xl font-black text-gray-900 dark:text-white mb-4 tracking-tight">Accesso Sospeso</h2>
          <p className="text-gray-500 dark:text-gray-400 font-medium mb-10 leading-relaxed px-2">
            Il tuo account MintFlow è stato disabilitato. Contatta il supporto per riattivare l'accesso ai tuoi dati.
          </p>
          <div className="space-y-4">
            <a href="mailto:supporto@mintflow.com" className="flex items-center justify-center gap-2 w-full py-5 bg-emerald-500 text-white rounded-[2rem] font-bold hover:bg-emerald-600 shadow-lg shadow-emerald-200 dark:shadow-none transition-all active:scale-95">
              <Mail size={20} /> Contatta Supporto
            </a>
            <button onClick={handleForcedLogout} className="flex items-center justify-center gap-2 w-full py-5 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-200 rounded-[2rem] font-bold hover:bg-gray-200 dark:hover:bg-gray-600 transition-all active:scale-95">
              <LogOut size={20} /> Esci dall'account
            </button>
          </div>
          <div className="mt-12 pt-8 border-t border-gray-100 dark:border-gray-700 flex items-center justify-center gap-2 opacity-50">
            <ShieldCheck size={14} className="text-emerald-500" />
            <p className="text-[10px] text-gray-400 font-bold uppercase tracking-[0.2em]">MintFlow Security Shield</p>
          </div>
        </div>
      </div>
    );
  }

  if (!session) return <Auth onSuccess={() => setIsBanned(false)} />;
  if (session.user.email === 'admin@mintflow.com') return <AdminDashboard onLogout={() => setSession(null)} />;

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} lang={userSettings.language}>
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24 relative">
        {successToast && <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-emerald-600 text-white px-6 py-3 rounded-2xl shadow-xl animate-in slide-in-from-top-4">{successToast}</div>}
        {activeTab === 'dashboard' && <Dashboard expenses={expenses} budget={currentBudget} userName={userSettings.name} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} lang={userSettings.language} userSettings={userSettings} onUpdateSettings={setUserSettings} />}
        {activeTab === 'list' && (
          <div className="space-y-6">
            <button onClick={() => { setPrefill(null); setShowForm(true); }} className="w-full bg-emerald-500 text-white py-4 rounded-2xl flex items-center justify-center gap-2 font-bold shadow-lg transition-transform active:scale-95"><Plus size={20} /> Aggiungi Spesa</button>
            <ExpenseList expenses={expenses} onDelete={id => setAllExpenses(prev => prev.filter(e => e.id !== id))} onEdit={ex => { setPrefill(ex); setShowForm(true); }} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} />
          </div>
        )}
        {activeTab === 'ricariche' && <RicaricheView onRefill={w => { setPrefill({ description: `Ricarica ${w.name}`, category: 'Altro', paymentMethod: PaymentMethod.Bancomat, date: format(new Date(), 'yyyy-MM-dd') }); setShowForm(true); }} onSaveExpense={handleSaveExpense} onUpdateWallets={w => setUserSettings(prev => ({ ...prev, wallets: w }))} expenses={expenses} currency={userSettings.currency} wallets={userSettings.wallets} />}
        {activeTab === 'ai' && <AiInsights expenses={expenses} />}
        {activeTab === 'settings' && <SettingsView settings={userSettings} onUpdate={setUserSettings} onClearData={() => {}} expenses={expenses} email={session.user.email} />}
        {activeTab === 'subscriptions' && <SubscriptionsView expenses={expenses} onAddSub={() => { setPrefill({ isSubscription: true }); setShowForm(true); }} onDelete={id => setAllExpenses(prev => prev.filter(e => e.id !== id))} currency={userSettings.currency} />}
        {activeTab === 'extra' && <ExtraView expenses={extraExpenses} onAdd={handleSaveExpense} onDelete={id => setAllExpenses(prev => prev.filter(e => e.id !== id))} currency={userSettings.currency} />}

        {showForm && (
          <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[70] flex items-center justify-center p-4">
            <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-md p-8 shadow-2xl relative animate-in zoom-in-95 duration-200">
              <button onClick={() => setShowForm(false)} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 dark:hover:text-white transition-colors"><X size={24} /></button>
              <h2 className="text-2xl font-bold mb-6 dark:text-white">{prefill?.id ? 'Modifica Spesa' : 'Nuova Spesa'}</h2>
              <ExpenseForm onSubmit={handleSaveExpense} onCancel={() => setShowForm(false)} initialData={prefill || undefined} currency={userSettings.currency} wallets={userSettings.wallets} categories={userSettings.categories} expenses={expenses} />
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { auth, db, supabase } from '../services/supabase';
import { PiggyBank, Mail, Lock, User, Loader2, ArrowRight, Check, Send, AlertCircle, Eye, EyeOff, ShieldCheck, MailWarning, KeyRound, ArrowLeft, Ban } from 'lucide-react';

interface AuthProps {
  onSuccess: () => void;
}

export const Auth: React.FC<AuthProps> = ({ onSuccess }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [isResetting, setIsResetting] = useState(false);
  const [loading, setLoading] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const [rememberMe, setRememberMe] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [signedUpEmail, setSignedUpEmail] = useState<string | null>(null);
  const [resetSentEmail, setResetSentEmail] = useState<string | null>(null);
  const [resending, setResending] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  // Stato per il blocco account rilevato al login
  const [isBanned, setIsBanned] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    if (isResetting) {
      try {
        await auth.resetPassword(email);
        setResetSentEmail(email);
      } catch (err: any) {
        setError(err.message || "Errore durante il reset della password");
      } finally {
        setLoading(false);
      }
      return;
    }

    try {
      if (isLogin) {
        // 1. Esegui il login tecnico con Supabase
        const data = await auth.signIn(email, password);

        if (data.user) {
          // 2. CONTROLLO IMMEDIATO DELLO STATO NEL DATABASE
          const { data: profile, error: profileError } = await supabase
            .from('profiles')
            .select('status')
            .eq('id', data.user.id)
            .single();

          if (profile?.status === 'disabled') {
            // Se è bannato, attiviamo la Lock Screen interna e fermiamo tutto
            setIsBanned(true);
            setLoading(false);
            return;
          }
        }

        // 3. Se arriviamo qui, l'utente è attivo: procedi
        onSuccess();
      } else {
        await auth.signUp(email, password, username);
        setSignedUpEmail(email);
      }
    } catch (err: any) {
      if (err.message?.includes('Email not confirmed')) {
        setError("Devi confermare la tua email prima di accedere.");
        setSignedUpEmail(email);
      } else {
        setError(err.message || "Si è verificato un errore");
      }
    } finally {
      setLoading(false);
    }
  };

  const handleBackToLogin = async () => {
    // Esci tecnicamente per pulire la sessione "congelata"
    await auth.signOut();
    setIsBanned(false);
    setLoading(false);
  };

  // --- SCHERMATA DI BLOCCO "ALLA PORTA" ---
  if (isBanned) {
    return (
      <div className="min-h-screen bg-mint-50 dark:bg-gray-900 flex items-center justify-center p-4 animate-in fade-in duration-500">
        <div className="w-full max-w-md bg-white dark:bg-gray-800 rounded-[3.5rem] shadow-2xl p-10 md:p-12 text-center border-4 border-red-500/20 relative overflow-hidden">
          <div className="absolute top-0 left-0 right-0 h-2 bg-red-500" />

          <div className="bg-red-50 dark:bg-red-900/20 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-8 shadow-inner">
            <Ban className="text-red-500 animate-pulse" size={48} />
          </div>

          <h2 className="text-3xl font-black text-gray-900 dark:text-white mb-4 tracking-tight">Accesso Sospeso</h2>
          <p className="text-gray-500 dark:text-gray-400 font-medium mb-10 leading-relaxed">
            Il tuo account MintFlow è stato disabilitato. Non puoi accedere ai tuoi dati finché l'amministratore non riabilita il tuo profilo.
          </p>

          <div className="space-y-4">
             <a href="mailto:assistenza@mintflow.com" className="flex items-center justify-center gap-2 w-full py-5 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-2xl font-bold hover:scale-[1.02] transition-transform">
               Invia Segnalazione
             </a>
             <button 
               onClick={handleBackToLogin}
               className="w-full py-4 text-gray-400 font-bold hover:text-gray-600 dark:hover:text-gray-200 transition-colors text-sm"
             >
               Torna alla maschera di login
             </button>
          </div>

          <p className="mt-12 text-[10px] text-gray-300 font-bold uppercase tracking-[0.3em]">MintFlow Security Shield</p>
        </div>
      </div>
    );
  }

  // --- RENDERING NORMALE DEL LOGIN ---
  if (resetSentEmail) {
    return (
      <div className="min-h-screen bg-mint-50 dark:bg-gray-900 flex items-center justify-center p-4">
        <div className="w-full max-w-md bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-2xl p-8 text-center animate-in fade-in zoom-in-95 duration-300">
          <div className="bg-emerald-100 dark:bg-emerald-900/30 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6">
            <KeyRound className="text-emerald-600 dark:text-emerald-400" size={32} />
          </div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">Link inviato!</h2>
          <p className="text-gray-600 dark:text-gray-400 mb-8">
            Abbiamo inviato le istruzioni per il reset a <br/>
            <span className="font-bold text-emerald-600 dark:text-emerald-400">{resetSentEmail}</span>
          </p>
          <button
            onClick={() => { setResetSentEmail(null); setIsResetting(false); setIsLogin(true); }}
            className="w-full bg-emerald-500 hover:bg-emerald-600 text-white py-4 rounded-2xl font-bold transition-all shadow-lg"
          >
            Torna al Login
          </button>
        </div>
      </div>
    );
  }

  if (signedUpEmail && !isLogin) {
    return (
      <div className="min-h-screen bg-mint-50 dark:bg-gray-900 flex items-center justify-center p-4">
        <div className="w-full max-w-md bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-2xl p-8 md:p-10 border border-emerald-100 dark:border-gray-700 text-center animate-in fade-in zoom-in-95 duration-300">
          <div className="bg-emerald-100 dark:bg-emerald-900/30 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6 shadow-inner">
            <Send className="text-emerald-600 dark:text-emerald-400" size={32} />
          </div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">Ci siamo quasi!</h2>
          <p className="text-gray-600 dark:text-gray-400 mb-8">
            Abbiamo inviato un link di conferma a <br/>
            <span className="font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 px-2 py-1 rounded-lg mt-1 inline-block">{signedUpEmail}</span>
          </p>

          <div className="bg-amber-50 dark:bg-amber-900/20 p-5 rounded-2xl border border-amber-100 dark:border-amber-900/30 text-left mb-8 flex gap-4 shadow-sm">
            <MailWarning className="text-amber-500 shrink-0 mt-1" size={24} />
            <div className="space-y-2">
                <p className="text-sm font-bold text-amber-800 dark:text-amber-300 uppercase tracking-wide">
                  ⚠️ Importante: Controlla lo SPAM
                </p>
                <p className="text-xs text-amber-700 dark:text-amber-400 leading-relaxed">
                  L'email potrebbe finire nella cartella <strong>Posta Indesiderata</strong> o <strong>Promozioni</strong>.
                </p>
            </div>
          </div>

          <div className="space-y-3">
            <button
              onClick={async () => {
                if (!signedUpEmail) return;
                setResending(true);
                try {
                  await auth.resendConfirmation(signedUpEmail);
                  alert("Email reinviata! Controlla di nuovo.");
                } catch (err: any) {
                  setError("Errore nel rinvio: " + err.message);
                } finally {
                  setResending(false);
                }
              }}
              disabled={resending}
              className="w-full bg-emerald-500 hover:bg-emerald-600 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-2 transition-all shadow-lg shadow-emerald-100 dark:shadow-none disabled:opacity-50"
            >
              {resending ? <Loader2 className="animate-spin" size={20} /> : 'Non ho ricevuto nulla, Reinvia'}
            </button>
            <button
              onClick={() => { setSignedUpEmail(null); setIsLogin(true); }}
              className="w-full py-4 text-emerald-600 dark:text-emerald-400 font-bold hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded-2xl transition-colors text-sm"
            >
              Torna al login
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-mint-50 dark:bg-gray-900 flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-2xl p-8 border border-emerald-100 dark:border-gray-700 animate-in zoom-in-95 duration-300">
        <div className="flex flex-col items-center mb-8">
          <div className="bg-emerald-500 p-4 rounded-2xl text-white mb-4 shadow-lg shadow-emerald-200">
            {isResetting ? <KeyRound size={32} /> : <PiggyBank size={32} />}
          </div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            {isResetting ? 'Recupero Password' : 'MintFlow'}
          </h1>
          <p className="text-gray-500 dark:text-gray-400 text-sm mt-1">
            {isResetting 
              ? 'Ti invieremo un link per resettare la password' 
              : isLogin ? 'Accedi al tuo account cloud' : 'Crea il tuo profilo finanziario'}
          </p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 text-sm rounded-xl border border-red-100 dark:border-red-900/30 flex items-center gap-2">
            <AlertCircle size={16} />
            <span className="flex-1">{error}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {!isLogin && !isResetting && (
            <div className="relative">
              <User className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input
                type="text"
                placeholder="Nome Utente"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                className="w-full pl-12 pr-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white transition-all font-medium"
                required={!isLogin && !isResetting}
              />
            </div>
          )}

          <div className="relative">
            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input
              type="email"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full pl-12 pr-5 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white transition-all font-medium"
              required
            />
          </div>

          {!isResetting && (
            <>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-12 pr-12 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white transition-all font-medium"
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 transition-colors p-1"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>

              {isLogin && (
                <div className="flex justify-end px-2">
                  <button
                    type="button"
                    onClick={() => { setIsResetting(true); setError(null); }}
                    className="text-xs font-bold text-emerald-600 dark:text-emerald-400 hover:underline"
                  >
                    Password dimenticata?
                  </button>
                </div>
              )}
            </>
          )}

          {isLogin && !isResetting && (
            <div className="flex items-center gap-2 px-2">
              <label className="flex items-center gap-2 cursor-pointer group">
                <div 
                  onClick={() => setRememberMe(!rememberMe)}
                  className={`w-5 h-5 rounded-md border-2 flex items-center justify-center transition-all ${
                    rememberMe 
                      ? 'bg-emerald-500 border-emerald-500' 
                      : 'border-gray-200 dark:border-gray-600 bg-transparent'
                  }`}
                >
                  {rememberMe && <Check size={14} className="text-white" />}
                </div>
                <span className="text-sm text-gray-500 dark:text-gray-400 font-medium select-none">Rimani collegato</span>
              </label>
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-emerald-500 hover:bg-emerald-600 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-2 transition-all shadow-xl shadow-emerald-200 dark:shadow-none disabled:opacity-70 mt-6"
          >
            {loading ? (
              <Loader2 className="animate-spin" size={20} />
            ) : (
              <>
                {isResetting ? 'Invia link di recupero' : isLogin ? 'Accedi' : 'Iscriviti'}
                <ArrowRight size={20} />
              </>
            )}
          </button>
        </form>

        <div className="mt-8 text-center space-y-4">
          {isResetting ? (
            <button
              onClick={() => { setIsResetting(false); setError(null); }}
              className="text-emerald-600 dark:text-emerald-400 font-bold text-sm flex items-center justify-center gap-2 w-full hover:underline"
            >
              <ArrowLeft size={16} /> Torna al login
            </button>
          ) : (
            <button
              onClick={() => { setIsLogin(!isLogin); setError(null); }}
              className="text-emerald-600 dark:text-emerald-400 font-bold text-sm hover:underline block w-full"
            >
              {isLogin ? 'Non hai un account? Iscriviti' : 'Hai già un account? Accedi'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

