import { Shield, Users, Bell, Ban, Search, LogOut, CheckCircle2, X, Send, AlertTriangle, Loader2, Database, Terminal, Copy, Key } from 'lucide-react';
import { db, auth, supabase } from '../services/supabase';
import { ConfirmModal } from './ConfirmModal';
import { format } from 'date-fns';
import it from 'date-fns/locale/it';

interface AdminUser {
