        </div>
      </main>

      {/* MODAL RESET PASSWORD & SICUREZZA */}
      {userToReset && (
        <div className="fixed inset-0 z-[160] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-in fade-in duration-200">
