               <h3 className="text-xl font-bold flex gap-2"><Terminal className="text-emerald-500" /> Script SQL Supabase</h3>
               <button onClick={() => setShowSqlModal(false)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
