import { createClient } from '@supabase/supabase-js';
import { Expense, PaymentMethod, ProfileType } from '../types';

const SUPABASE_URL = 'https://jpcweqcqysxgzycftzyv.supabase.co';
const SUPABASE_ANON_KEY = 'sb_publishable_qdb7pW6R-6vvGaoeuGE5fw_xuPgZweE';

/**
 * La Service Role Key è necessaria per bypassare le policy RLS e gestire gli utenti lato server/admin.
 * In questo ambiente, la recuperiamo dalle variabili d'ambiente.
 */
const SUPABASE_SERVICE_ROLE_KEY = (typeof process !== 'undefined' && process.env?.VITE_SUPABASE_SERVICE_ROLE_KEY) || '';

// Log di debug per lo sviluppatore
if (!SUPABASE_SERVICE_ROLE_KEY || SUPABASE_SERVICE_ROLE_KEY === 'SERVICE_ROLE_KEY_HERE') {
  console.warn("DEBUG: La Service Role Key è vuota o non valida. Le funzioni Admin (reset password) non funzioneranno correttamente.");
}

// 1. Client per l'utente (Salva la sessione nel localStorage predefinito)
export const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

// 2. Client per l'Admin (Isolato, non salva la sessione, evita i conflitti)
export const supabaseAdmin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, {
  auth: {
    persistSession: false,      // Impedisce al client Admin di scrivere nel localStorage
    autoRefreshToken: false,    // Non serve il refresh per operazioni admin one-shot
    detectSessionInUrl: false,   // Impedisce di catturare sessioni dai link di redirect nell'URL
    storageKey: 'supabase-admin-storage' // Usa un "cassetto" diverso per non disturbare la sessione utente
  }
});

const PACK_SEP = ' |#| ';

const packDescription = (desc: string, pm: PaymentMethod, isSub: boolean, profile: ProfileType, isExtra: boolean, extraType: string) => {
  return `${desc}${PACK_SEP}${pm}${PACK_SEP}${isSub}${PACK_SEP}${profile}${PACK_SEP}${isExtra}${PACK_SEP}${extraType}`;
};

const unpackDescription = (packedStr: string) => {
  if (!packedStr || !packedStr.includes(PACK_SEP)) {
    return { 
      desc: packedStr, 
      pm: PaymentMethod.Contanti, 
      isSub: false, 
      profile: 'personal' as ProfileType,
      isExtra: false,
      extraType: 'given' as 'given' | 'received'
    };
  }
  const parts = packedStr.split(PACK_SEP);
  return {
    desc: parts[0],
    pm: (parts[1] as PaymentMethod) || PaymentMethod.Contanti,
    isSub: parts[2] === 'true',
    profile: (parts[3] as ProfileType) || 'personal',
    isExtra: parts[4] === 'true',
    extraType: (parts[5] as 'given' | 'received') || 'given'
  };
};

export const auth = {
