const getServiceKey = () => {
  // Prova a recuperare da import.meta.env (Vite) o process.env (Node/Webpack)
  const key = (typeof (import.meta as any) !== 'undefined' && (import.meta as any).env?.VITE_SUPABASE_SERVICE_ROLE_KEY) || 
              (typeof process !== 'undefined' && process.env?.VITE_SUPABASE_SERVICE_ROLE_KEY) || 
              '';
  return key;
};

