const PACK_SEP = ' |#| ';

const packDescription = (desc: string, pm: PaymentMethod, isSub: boolean, profile: ProfileType, isExtra: boolean, extraType: string) => {
  return `${desc}${PACK_SEP}${pm}${PACK_SEP}${isSub}${PACK_SEP}${profile}${PACK_SEP}${isExtra}${PACK_SEP}${extraType}`;
};

const unpackDescription = (packedStr: string) => {
  if (!packedStr || !packedStr.includes(PACK_SEP)) {
    return { 
      desc: packedStr, 
      pm: PaymentMethod.Contanti, 
      isSub: false, 
      profile: 'personal' as ProfileType,
      isExtra: false,
      extraType: 'given' as 'given' | 'received'
    };
  }
  const parts = packedStr.split(PACK_SEP);
  return {
    desc: parts[0],
    pm: (parts[1] as PaymentMethod) || PaymentMethod.Contanti,
    isSub: parts[2] === 'true',
    profile: (parts[3] as ProfileType) || 'personal',
    isExtra: parts[4] === 'true',
    extraType: (parts[5] as 'given' | 'received') || 'given'
  };
};

export const auth = {
  async signUp(email: string, password: string, username: string) {
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: { data: { display_name: username }, emailRedirectTo: window.location.origin }
    });
    if (error) throw error;
    if (data.user) {
        try {
            await db.upsertProfile(data.user.id, email, username);
        } catch (e) {
            console.error("Errore creazione profilo:", e);
        }
    }
    return data;
  },
  async signIn(email: string, password: string) {
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) throw error;
    return data;
  },
  async signOut() {
    const { error } = await supabase.auth.signOut();
    if (error) throw error;
  },
  async updateProfile(name: string) {
    const { data, error } = await supabase.auth.updateUser({ data: { display_name: name } });
    if (error) throw error;
    if (data.user) {
        await db.upsertProfile(data.user.id, data.user.email || '', name);
    }
    return data;
  },
  async updateEmail(newEmail: string) {
    const { data, error } = await supabase.auth.updateUser({ email: newEmail });
    if (error) throw error;
    return data;
  },
  async updatePassword(password: string) {
    const { data, error } = await supabase.auth.updateUser({ password });
    if (error) throw error;
    return data;
  },
  async deleteAccount() {
    const { data: { user } } = await supabase.auth.getUser();
    if (user) {
      await db.clearAll(user.id);
      await supabase.from('profiles').delete().eq('id', user.id);
      await this.signOut();
    }
  },
  async resetPassword(email: string) {
    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: window.location.origin,
    });
    if (error) throw error;
  },
  async resendConfirmation(email: string) {
    const { error } = await supabase.auth.resend({ type: 'signup', email });
    if (error) throw error;
  }
};

export const db = {
  async upsertProfile(id: string, email: string, name: string) {
    const role = email === 'admin@mintflow.com' ? 'admin' : 'user';
    const { data, error } = await supabase
      .from('profiles')
      .upsert({ 
        id, 
        email, 
        display_name: name,
        role,
        last_login: new Date().toISOString() 
      }, { onConflict: 'id' })
      .select();
    if (error) throw error;
    return data;
  },

  async getAllProfiles() {
    const { data, error } = await supabase.from('profiles').select('*').order('email');
    if (error) throw error;
    return data || [];
  },

  async updateUserStatus(id: string, status: 'active' | 'disabled') {
    const { data, error } = await supabase.from('profiles').update({ status }).eq('id', id).select();
    if (error) throw error;
    return data;
  },

  // NOTIFICHE
  async sendNotification(userId: string, title: string, message: string) {
    const { error } = await supabaseAdmin.from('notifications').insert([{
      user_id: userId,
      title,
      message,
      is_read: false
    }]);
    if (error) throw error;
  },

  async getNotifications(userId: string): Promise<AppNotification[]> {
    const { data, error } = await supabase
      .from('notifications')
      .select('*')
      .eq('user_id', userId)
      .order('created_at', { ascending: false });
    if (error) throw error;
    return data || [];
  },

  async markNotificationRead(notificationId: string) {
    const { error } = await supabase
      .from('notifications')
      .update({ is_read: true })
      .eq('id', notificationId);
    if (error) throw error;
  },

  // SPESE
  async getExpenses(userId: string): Promise<Expense[]> {
    const { data, error } = await supabase.from('expenses').select('*').eq('user_id', userId).order('date', { ascending: false });
    if (error) throw error;
    return (data || []).map((e: any) => {
      const unpacked = unpackDescription(e.description);
      return {
        id: e.id,
        amount: e.amount,
        category: e.category,
        date: e.date,
        description: unpacked.desc,
        paymentMethod: unpacked.pm,
        isSubscription: unpacked.isSub,
        profile: unpacked.profile,
        isExtra: unpacked.isExtra,
        extraType: unpacked.extraType
      };
    });
  },

  async addExpense(expense: Omit<Expense, 'id'>, userId: string): Promise<Expense> {
    const packedDesc = packDescription(expense.description, expense.paymentMethod, !!expense.isSubscription, expense.profile || 'personal', !!expense.isExtra, expense.extraType || 'given');
    const { data, error } = await supabase.from('expenses').insert([{
      description: packedDesc,
      amount: expense.amount,
      category: expense.category,
      date: expense.date,
      user_id: userId
    }]).select().single();
    if (error) throw error;
    return { id: data.id, ...expense };
  },

  async updateExpense(id: string, expense: Partial<Omit<Expense, 'id'>>): Promise<Expense> {
    const { data: current } = await supabase.from('expenses').select('description').eq('id', id).single();
    const currentUnpacked = unpackDescription(current?.description || '');
    const newDesc = expense.description !== undefined ? expense.description : currentUnpacked.desc;
    const newPM = expense.paymentMethod !== undefined ? expense.paymentMethod : currentUnpacked.pm;
    const newIsSub = expense.isSubscription !== undefined ? expense.isSubscription : currentUnpacked.isSub;
    const newProfile = expense.profile !== undefined ? expense.profile : currentUnpacked.profile;
    const newIsExtra = expense.isExtra !== undefined ? expense.isExtra : currentUnpacked.isExtra;
    const newExtraType = expense.extraType !== undefined ? expense.extraType : currentUnpacked.extraType;

    const { data, error } = await supabase.from('expenses').update({
      description: packDescription(newDesc, newPM, newIsSub, newProfile, newIsExtra, newExtraType),
      amount: expense.amount,
      category: expense.category,
      date: expense.date
    }).eq('id', id).select().single();
    if (error) throw error;
    const unpacked = unpackDescription(data.description);
    return { id: data.id, ...data, ...unpacked, description: unpacked.desc, paymentMethod: unpacked.pm, isSubscription: unpacked.isSub };
  },

  async deleteExpense(id: string) {
    const { error } = await supabase.from('expenses').delete().eq('id', id);
    if (error) throw error;
  },

  async clearAll(userId: string) {
    const { error } = await supabase.from('expenses').delete().eq('user_id', userId);
    if (error) throw error;
  }
};

import { Shield, Users, Bell, Ban, Search, LogOut, CheckCircle2, X, Send, AlertTriangle, Loader2, Database, Terminal, Key, Check, RefreshCw } from 'lucide-react';
import React, { useState, useEffect } from 'react';
import { db, supabase, supabaseAdmin } from '../services/supabase';
import { ConfirmModal } from './ConfirmModal';

interface AdminUser {
  id: string;
  email: string;
  display_name: string;
  status: 'active' | 'disabled';
  last_login: string;
  role: 'user' | 'admin';
}

interface AdminDashboardProps {
  onLogout: () => void;
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout }) => {
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState<AdminUser | null>(null);
  const [showNotifyModal, setShowNotifyModal] = useState(false);
  const [showSqlModal, setShowSqlModal] = useState(false);
  const [notificationTitle, setNotificationTitle] = useState('Messaggio da MintFlow');
  const [notificationText, setNotificationText] = useState('');
  const [toast, setToast] = useState<{msg: string, type: 'success' | 'error'} | null>(null);
  const [userToReset, setUserToReset] = useState<{email: string, id: string} | null>(null);
  const [isResetting, setIsResetting] = useState(false);
  const [tempPassword, setTempPassword] = useState('');

  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    userId: string;
    userName: string;
    newStatus: 'active' | 'disabled';
  }>({ isOpen: false, userId: '', userName: '', newStatus: 'active' });

  const fetchUsers = async () => {
    setLoading(true);
    try {
        const data = await db.getAllProfiles();
        setUsers(data as AdminUser[]);
    } catch (err) {
        setError("Errore nel caricamento dal database.");
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => { fetchUsers(); }, []);

  const showToast = (msg: string, type: 'success' | 'error' = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleToggleStatusRequest = (user: AdminUser) => {
    setConfirmConfig({
      isOpen: true,
      userId: user.id,
      userName: user.display_name || user.email,
      newStatus: user.status === 'active' ? 'disabled' : 'active'
    });
  };

  const executeToggleStatus = async () => {
    const { userId, newStatus } = confirmConfig;
    setConfirmConfig(prev => ({ ...prev, isOpen: false }));
    try {
        await db.updateUserStatus(userId, newStatus);
        setUsers(prev => prev.map(u => u.id === userId ? { ...u, status: newStatus } : u));
        showToast(`Utente ${newStatus === 'active' ? 'riattivato' : 'disabilitato'}`);
    } catch (err: any) {
        showToast("Errore: " + err.message, "error");
    }
  };

  const handleSendNotification = async () => {
    if (!notificationText.trim() || !selectedUser) return;
    try {
      await db.sendNotification(selectedUser.id, notificationTitle, notificationText);
      showToast(`Notifica inviata a ${selectedUser.email}`);
      setShowNotifyModal(false);
      setNotificationText('');
      setNotificationTitle('Messaggio da MintFlow');
      setSelectedUser(null);
    } catch (err: any) {
      showToast('Errore invio notifica: ' + err.message, 'error');
    }
  };

  const handleSetTempPassword = async () => {
    if (!userToReset || !tempPassword) return;
    setIsResetting(true);
    try {
      const { error } = await supabaseAdmin.auth.admin.updateUserById(userToReset.id, { password: tempPassword });
      if (error) throw error;
      showToast(`Password aggiornata per ${userToReset.email}`);
      setUserToReset(null);
      setTempPassword('');
    } catch (err: any) {
      showToast('Errore setup password: ' + err.message, 'error');
    } finally {
      setIsResetting(false);
    }
  };

  const filteredUsers = users.filter(u => 
    (u.email || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
    (u.display_name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white pb-20 md:pb-0">
      {toast && (
        <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[150] px-6 py-3 rounded-2xl shadow-xl flex items-center gap-2 animate-in slide-in-from-top-4 ${
          toast.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-500 text-white'
        }`}>
          {toast.type === 'success' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
          <span className="font-bold text-sm">{toast.msg}</span>
        </div>
      )}

      <header className="bg-white dark:bg-gray-800 border-b sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Shield className="text-emerald-500" size={32} />
            <h1 className="text-xl font-black">MintFlow <span className="text-emerald-500">Admin</span></h1>
          </div>
          <div className="flex items-center gap-4">
            <button onClick={() => setShowSqlModal(true)} className="p-2 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 rounded-xl"><Database size={20} /></button>
            <button onClick={onLogout} className="flex items-center gap-2 px-4 py-2 bg-gray-100 dark:bg-gray-700 rounded-xl font-bold"><LogOut size={20} /> Esci</button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8">
        <div className="mb-8 relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
          <input type="text" placeholder="Cerca utente..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white dark:bg-gray-800 border-none shadow-sm outline-none focus:ring-2 focus:ring-emerald-500" />
