export const db = {
  async upsertProfile(id: string, email: string, name: string) {
    const role = email === 'admin@mintflow.com' ? 'admin' : 'user';
    const { data, error } = await supabase
      .from('profiles')
      .upsert({ 
        id, 
        email, 
        display_name: name,
        role,
        last_login: new Date().toISOString() 
      }, { onConflict: 'id' })
      .select();
    if (error) throw error;
    return data;
  },

  async getAllProfiles() {
    const { data, error } = await supabase.from('profiles').select('*').order('email');
    if (error) throw error;
    return data || [];
  },

  async updateUserStatus(id: string, status: 'active' | 'disabled') {
    const { data, error } = await supabase.from('profiles').update({ status }).eq('id', id).select();
    if (error) throw error;
    return data;
  },

  // NOTIFICHE
  async sendNotification(userId: string, title: string, message: string) {
    const { error } = await supabaseAdmin.from('notifications').insert([{
      user_id: userId,
      title,
      message,
      is_read: false
    }]);
    if (error) throw error;
  },

  async getNotifications(userId: string): Promise<AppNotification[]> {
    const { data, error } = await supabase
      .from('notifications')
      .select('*')
      .eq('user_id', userId)
      .order('created_at', { ascending: false });
    if (error) throw error;
    return data || [];
  },

  async markNotificationRead(notificationId: string) {
    const { error } = await supabase
      .from('notifications')
      .update({ is_read: true })
      .eq('id', notificationId);
    if (error) throw error;
  },

  async markAllNotificationsAsRead(userId: string) {
    const { error } = await supabase
      .from('notifications')
      .update({ is_read: true })
      .eq('user_id', userId)
      .eq('is_read', false);
    if (error) throw error;
  },

  // SPESE
  async getExpenses(userId: string): Promise<Expense[]> {
    const { data, error } = await supabase.from('expenses').select('*').eq('user_id', userId).order('date', { ascending: false });
    if (error) throw error;
    return (data || []).map((e: any) => {
      const unpacked = unpackDescription(e.description);
      return {
        id: e.id,
        amount: e.amount,
        category: e.category,
        date: e.date,
        description: unpacked.desc,
        paymentMethod: unpacked.pm,
        isSubscription: unpacked.isSub,
        profile: unpacked.profile,
        isExtra: unpacked.isExtra,
        extraType: unpacked.extraType
      };
    });
  },

  async addExpense(expense: Omit<Expense, 'id'>, userId: string): Promise<Expense> {
    const packedDesc = packDescription(expense.description, expense.paymentMethod, !!expense.isSubscription, expense.profile || 'personal', !!expense.isExtra, expense.extraType || 'given');
    const { data, error } = await supabase.from('expenses').insert([{
      description: packedDesc,
      amount: expense.amount,
      category: expense.category,
      date: expense.date,
      user_id: userId
    }]).select().single();
    if (error) throw error;
    return { id: data.id, ...expense };
  },

  async updateExpense(id: string, expense: Partial<Omit<Expense, 'id'>>): Promise<Expense> {
    const { data: current } = await supabase.from('expenses').select('description').eq('id', id).single();
    const currentUnpacked = unpackDescription(current?.description || '');
    const newDesc = expense.description !== undefined ? expense.description : currentUnpacked.desc;
    const newPM = expense.paymentMethod !== undefined ? expense.paymentMethod : currentUnpacked.pm;
    const newIsSub = expense.isSubscription !== undefined ? expense.isSubscription : currentUnpacked.isSub;
    const newProfile = expense.profile !== undefined ? expense.profile : currentUnpacked.profile;
    const newIsExtra = expense.isExtra !== undefined ? expense.isExtra : currentUnpacked.isExtra;
    const newExtraType = expense.extraType !== undefined ? expense.extraType : currentUnpacked.extraType;

    const { data, error } = await supabase.from('expenses').update({
      description: packDescription(newDesc, newPM, newIsSub, newProfile, newIsExtra, newExtraType),
      amount: expense.amount,
      category: expense.category,
      date: expense.date
    }).eq('id', id).select().single();
    if (error) throw error;
    const unpacked = unpackDescription(data.description);
    return { id: data.id, ...data, ...unpacked, description: unpacked.desc, paymentMethod: unpacked.pm, isSubscription: unpacked.isSub };
  },

  async deleteExpense(id: string) {
    const { error } = await supabase.from('expenses').delete().eq('id', id);
    if (error) throw error;
  },

  async clearAll(userId: string) {
    const { error } = await supabase.from('expenses').delete().eq('user_id', userId);
    if (error) throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, List, BrainCircuit, PiggyBank, Settings, Zap, Repeat, ArrowRightLeft, Bell, X, Mail } from 'lucide-react';
import { translations } from '../utils/i18n';
import { ProfileType, AppNotification } from '../types';
import { supabase, db } from '../services/supabase';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: 'dashboard' | 'list' | 'ai' | 'settings' | 'ricariche' | 'subscriptions' | 'extra';
  setActiveTab: (tab: 'dashboard' | 'list' | 'ai' | 'settings' | 'ricariche' | 'subscriptions' | 'extra') => void;
  lang?: 'it' | 'en';
  currentProfile?: ProfileType;
}

export const Layout: React.FC<LayoutProps> = ({ children, activeTab, setActiveTab, lang = 'it', currentProfile = 'personal' }) => {
  const t = translations[lang].nav;
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [isNotifPanelOpen, setIsNotifPanelOpen] = useState(false);

  useEffect(() => {
    const fetchAndSubscribe = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      // 1. Fetch iniziale
      const data = await db.getNotifications(user.id);
      setNotifications(data);

      // 2. Real-time Subscription
      const channel = supabase
        .channel(`notifs-${user.id}`)
        .on('postgres_changes', 
          { 
            event: 'INSERT', 
            schema: 'public', 
            table: 'notifications', 
            filter: `user_id=eq.${user.id}` 
          }, 
          (payload) => {
            setNotifications(prev => [payload.new as AppNotification, ...prev]);
          }
        )
        .subscribe();

      return () => { supabase.removeChannel(channel); };
    };

    fetchAndSubscribe();
  }, []);

  const unreadCount = notifications.filter(n => !n.is_read).length;

  const handleMarkRead = async (id: string) => {
    await db.markNotificationRead(id);
    setNotifications(prev => prev.map(n => n.id === id ? { ...n, is_read: true } : n));
  };

  return (
    <div className="min-h-screen bg-white dark:bg-gray-900 text-gray-900 dark:text-white transition-colors duration-300">
      {/* Header Desktop */}
      <header className="sticky top-0 z-40 bg-white/80 dark:bg-gray-900/80 backdrop-blur-md border-b border-emerald-100 dark:border-gray-800">
        <div className="max-w-4xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-emerald-100 dark:bg-emerald-900/30 p-2 rounded-lg">
              <PiggyBank className="text-emerald-600 dark:text-emerald-400" size={24} />
            </div>
            <span className="text-xl font-bold bg-gradient-to-r from-emerald-600 to-teal-500 bg-clip-text text-transparent">
              MintFlow
            </span>
          </div>

          <div className="flex items-center gap-4">
            <div className="relative">
              <button 
                onClick={() => setIsNotifPanelOpen(!isNotifPanelOpen)}
                className={`p-2 rounded-xl transition-all ${isNotifPanelOpen ? 'bg-emerald-100 text-emerald-600' : 'text-gray-400 hover:bg-emerald-50'}`}
              >
                <Bell size={20} />
                {unreadCount > 0 && (
                  <span className="absolute top-1 right-1 bg-red-500 text-white text-[8px] w-4 h-4 rounded-full flex items-center justify-center font-bold animate-bounce shadow-sm">
                    {unreadCount}
                  </span>
                )}
              </button>

              {/* Notification Panel Desktop */}
              {isNotifPanelOpen && (
                <div className="hidden md:block absolute right-0 mt-2 w-80 bg-white dark:bg-gray-800 shadow-2xl rounded-[2rem] border border-gray-100 dark:border-gray-700 z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                  <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50/50 dark:bg-gray-800/50">
                    <h3 className="font-bold text-gray-800 dark:text-white">Notifiche</h3>
                    <button onClick={() => setIsNotifPanelOpen(false)}><X size={18} /></button>
                  </div>
                  <div className="max-h-96 overflow-y-auto custom-scrollbar">
                    {notifications.length === 0 ? (
                      <p className="p-10 text-center text-gray-400 text-sm">Nessuna notifica presente</p>
                    ) : (
                      notifications.map((n) => (
                        <div 
                          key={n.id} 
                          onClick={() => !n.is_read && handleMarkRead(n.id)}
                          className={`p-4 border-b border-gray-50 dark:border-gray-700 hover:bg-emerald-50/30 dark:hover:bg-gray-700 transition cursor-pointer ${!n.is_read ? 'bg-emerald-50/50 dark:bg-emerald-900/10' : ''}`}
                        >
                          <div className="flex items-start gap-3">
                            <Mail size={18} className={`${!n.is_read ? 'text-emerald-500' : 'text-gray-300'} mt-1`} />
                            <div className="min-w-0 flex-1">
                              <p className={`text-sm font-bold truncate ${!n.is_read ? 'text-gray-900 dark:text-white' : 'text-gray-500'}`}>{n.title}</p>
                              <p className="text-xs text-gray-600 dark:text-gray-400 mt-1 line-clamp-2">{n.message}</p>
                              <p className="text-[9px] text-gray-400 mt-2 font-bold uppercase">{new Date(n.created_at).toLocaleString()}</p>
                            </div>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}
            </div>

            <div className="hidden md:flex items-center gap-1 bg-white dark:bg-gray-800 p-1 rounded-xl border border-emerald-50 dark:border-gray-700">
              <NavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={<LayoutDashboard size={18} />} label={t.dashboard} />
              <NavButton active={activeTab === 'list'} onClick={() => setActiveTab('list')} icon={<List size={18} />} label={t.expenses} />
              <NavButton active={activeTab === 'extra'} onClick={() => setActiveTab('extra')} icon={<ArrowRightLeft size={18} />} label={t.extra} />
              <NavButton active={activeTab === 'subscriptions'} onClick={() => setActiveTab('subscriptions')} icon={<Repeat size={18} />} label={t.subscriptions} />
              <NavButton active={activeTab === 'ricariche'} onClick={() => setActiveTab('ricariche')} icon={<Zap size={18} />} label={t.wallets} />
