              <NavButton active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} icon={<Settings size={18} />} label={t.settings} />
            </div>
          </div>
        </div>
      </header>

      {/* Mobile Notification Drawer */}
      {isNotifPanelOpen && (
        <div className="md:hidden fixed inset-0 z-[100] bg-black/50 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="absolute bottom-0 left-0 right-0 bg-white dark:bg-gray-800 rounded-t-[3rem] max-h-[80vh] flex flex-col animate-in slide-in-from-bottom duration-300">
            <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center">
              <h3 className="text-xl font-bold">Le tue Notifiche</h3>
              <button onClick={() => setIsNotifPanelOpen(false)} className="p-2 bg-gray-100 dark:bg-gray-700 rounded-full"><X size={24} /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-6 space-y-4">
              {notifications.length > 0 ? notifications.map(n => (
                <div 
                  key={n.id} 
                  onClick={() => !n.is_read && handleMarkRead(n.id)}
                  className={`p-5 rounded-[2rem] border transition-all ${
                    !n.is_read 
                      ? 'bg-emerald-50 dark:bg-emerald-900/10 border-emerald-100 dark:border-emerald-800 border-l-8 border-l-emerald-500' 
                      : 'bg-gray-50 dark:bg-gray-800 border-gray-100 dark:border-gray-700 opacity-60'
                  }`}
                >
                  <div className="flex justify-between items-start mb-2">
                    <h4 className="font-bold">{n.title}</h4>
                    <span className="text-[10px] text-gray-400 font-bold uppercase">{new Date(n.created_at).toLocaleDateString()}</span>
                  </div>
