import React, { useState, useEffect } from 'react';
import { LayoutDashboard, List, BrainCircuit, PiggyBank, Settings, Zap, Repeat, ArrowRightLeft, Bell, X, Mail, CheckCircle2, Calendar } from 'lucide-react';
