            <div className="bg-emerald-50 dark:bg-emerald-900/20 w-16 h-16 rounded-3xl flex items-center justify-center mb-8 text-emerald-500">
              <Mail size={32} />
            </div>

            <div className="space-y-4">
              <div className="flex items-center gap-2 text-[10px] font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-[0.2em] bg-emerald-50 dark:bg-emerald-900/20 w-fit px-3 py-1 rounded-full">
                <Calendar size={12} /> {new Date(selectedNotification.created_at).toLocaleString('it-IT', { day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' })}
              </div>
              <h3 className="text-2xl font-black text-gray-900 dark:text-white leading-tight">
                {selectedNotification.title}
              </h3>
              <div className="h-px bg-emerald-50 dark:bg-gray-700 w-full"></div>
              <p className="text-gray-600 dark:text-gray-400 leading-relaxed text-lg py-2">
                {selectedNotification.message}
              </p>
            </div>

            <button 
              onClick={() => setSelectedNotification(null)}
              className="w-full mt-10 py-5 bg-emerald-500 text-white rounded-[2rem] font-bold flex items-center justify-center gap-2 shadow-lg shadow-emerald-200 dark:shadow-none hover:bg-emerald-600 active:scale-95 transition-all"
            >
              <CheckCircle2 size={20} /> Ho capito
            </button>
          </div>
        </div>
      )}

      <main>{children}</main>

      {/* Bottom Nav Scorrevole per Mobile */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-white dark:bg-gray-900 border-t border-emerald-100 dark:border-gray-800 h-20 px-4 flex items-center overflow-x-auto no-scrollbar gap-8 pb-4 transition-colors z-50">
        <MobileNavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={<LayoutDashboard />} label="Home" />
        <MobileNavButton active={activeTab === 'list'} onClick={() => setActiveTab('list')} icon={<List />} label={t.expenses} />
        <MobileNavButton active={activeTab === 'extra'} onClick={() => setActiveTab('extra')} icon={<ArrowRightLeft />} label={t.extra} />
        <MobileNavButton active={activeTab === 'subscriptions'} onClick={() => setActiveTab('subscriptions')} icon={<Repeat />} label={t.subscriptions.substring(0, 5) + '.'} />
        <MobileNavButton active={activeTab === 'ricariche'} onClick={() => setActiveTab('ricariche')} icon={<Zap />} label={t.wallets} />
        <MobileNavButton active={activeTab === 'ai'} onClick={() => setActiveTab('ai')} icon={<BrainCircuit />} label="AI" />
