3. Lato Utente: La Campanella con Popup
Ora aggiungiamo l'icona della campanella. Per non incasinare il layout, mettila vicino all'avatar o al tasto logout.

TypeScript
import { useState, useEffect } from 'react';
import { Bell } from 'lucide-react'; // Assicurati di avere lucide-react o usa un emoji 🔔

export const NotificationCenter = ({ userId }: { userId: string }) => {
  const [showPopup, setShowPopup] = useState(false);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    // Carica le notifiche
    const loadNotif = async () => {
      const { data } = await supabase
        .from('notifications')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: false });
      if (data) setNotifications(data);
    };
    loadNotif();
  }, [userId, showPopup]);

  return (
    <div style={{ position: 'relative' }}>
      {/* Icona Campanella */}
      <button onClick={() => setShowPopup(!showPopup)} style={{ background: 'none', border: 'none', cursor: 'pointer' }}>
        <Bell size={24} />
        {notifications.filter(n => !n.is_read).length > 0 && (
          <span style={{ position: 'absolute', top: 0, right: 0, background: 'red', borderRadius: '50%', width: '10px', height: '10px' }}></span>
        )}
      </button>

      {/* Popup stilizzato */}
      {showPopup && (
        <div style={{
          position: 'absolute', right: 0, top: '40px', width: '300px', 
          background: 'white', borderRadius: '12px', boxShadow: '0 10px 25px rgba(0,0,0,0.1)',
          padding: '15px', zIndex: 1000, border: '1px solid #eee'
        }}>
          <h4 style={{ margin: '0 0 10px 0', borderBottom: '1px solid #eee', paddingBottom: '10px' }}>Le tue notifiche</h4>
          <div style={{ maxHeight: '200px', overflowY: 'auto' }}>
            {notifications.length === 0 ? <p style={{ fontSize: '12px', color: '#888' }}>Nessun messaggio</p> : 
              notifications.map(n => (
                <div key={n.id} style={{ padding: '8px 0', borderBottom: '1px solid #f9f9f9' }}>
                  <div style={{ fontWeight: 'bold', fontSize: '13px' }}>{n.title}</div>
                  <div style={{ fontSize: '12px', color: '#555' }}>{n.message}</div>
                </div>
              ))
            }
          </div>
        </div>
      )}
    </div>
  );
};

