          <div className="bg-white dark:bg-gray-800 rounded-[3rem] w-full max-w-md p-10 shadow-2xl border border-emerald-100 dark:border-emerald-900/30 relative animate-in zoom-in-95 duration-300">
            <button 
              onClick={() => setSelectedNotification(null)}
              className="absolute top-8 right-8 text-gray-400 hover:text-emerald-500 hover:bg-emerald-50 dark:hover:bg-gray-700 p-2 rounded-full transition-all"
            >
              <X size={24} />
            </button>

            <div className="bg-emerald-50 dark:bg-emerald-900/20 w-16 h-16 rounded-[1.5rem] flex items-center justify-center mb-8 text-emerald-500">
              <Mail size={32} />
            </div>

            <div className="space-y-4">
              <div className="flex items-center gap-2 text-[10px] font-black text-emerald-600 dark:text-emerald-400 uppercase tracking-widest bg-emerald-50 dark:bg-emerald-900/20 w-fit px-3 py-1.5 rounded-full">
                <Calendar size={12} /> {new Date(selectedNotification.created_at).toLocaleString('it-IT', { day: '2-digit', month: 'long', hour: '2-digit', minute: '2-digit' })}
              </div>
              <h3 className="text-2xl font-black text-gray-900 dark:text-white leading-tight">
