  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
      {feedback && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[100] px-6 py-3 bg-emerald-500 text-white rounded-2xl shadow-2xl flex items-center gap-2 animate-in fade-in zoom-in duration-300">
          <CheckCircle2 size={16} />
          <span className="font-bold text-xs uppercase tracking-wider">{feedback}</span>
        </div>
      )}

      <div className="bg-white dark:bg-gray-800 p-6 md:p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 p-4 rounded-[1.5rem] text-white shrink-0"><User size={24} /></div>
            <div className="min-w-0">
              <h3 className="text-xl font-black text-gray-800 dark:text-white truncate">{settings.name}</h3>
              <p className="text-gray-400 text-sm truncate font-medium">{email}</p>
            </div>
          </div>
          <button type="button" onClick={() => setShowProfileModal(true)} className="px-5 py-2.5 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-emerald-100 transition-all">Modifica</button>
        </div>
