          <button type="button" onClick={() => setView('history')} className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all"><History size={20} /> {t.history}</button>
          <button type="button" onClick={onExport} className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all"><Download size={20} /> {t.export}</button>
          <button type="button" onClick={() => fileInputRef.current?.click()} disabled={isImporting} className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all">
            {isImporting ? <Loader2 size={20} className="animate-spin" /> : <Upload size={20} />} {t.import}
            <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".csv" className="hidden" />
          </button>
        </div>
      </div>

      <div className="p-8 text-center bg-gray-50 dark:bg-gray-800/50 rounded-[2.5rem] border border-red-50 dark:border-red-900/10">
        <button onClick={() => auth.signOut()} className="text-red-500 font-black flex items-center gap-3 mx-auto uppercase tracking-widest text-sm hover:scale-105 transition-transform"><LogOut size={20} /> {t.logout}</button>
      </div>

      <Modal isOpen={showProfileModal} onClose={() => setShowProfileModal(false)} title="Il tuo Nome">
        <input type="text" value={tempName} onChange={(e) => setTempName(e.target.value)} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-none outline-none dark:text-white font-bold mb-6" placeholder="Nome" />
        <button type="button" onClick={handleUpdateProfile} disabled={isUpdating} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-lg shadow-emerald-200">{isUpdating ? "Salvataggio..." : "Aggiorna"}</button>
      </Modal>

      <Modal isOpen={showPasswordModal} onClose={() => setShowPasswordModal(false)} title="Nuova Password">
        <input type="password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-none outline-none dark:text-white font-bold mb-6" placeholder="Minimo 6 caratteri" />
        <button type="button" onClick={handleUpdatePassword} disabled={isUpdating} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-lg shadow-emerald-200">{isUpdating ? "Aggiornamento..." : "Cambia Password"}</button>
      </Modal>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Shield, Users, Bell, Ban, Search, LogOut, CheckCircle2, X, Send, AlertTriangle, Loader2, Database, Terminal, Copy, Key, Check, Mail } from 'lucide-react';
import { db, auth, supabase, supabaseAdmin } from '../services/supabase';
import { ConfirmModal } from './ConfirmModal';
import { format } from 'date-fns';
import it from 'date-fns/locale/it';

interface AdminUser {
  id: string;
  email: string;
  display_name: string;
  status: 'active' | 'disabled';
  last_login: string;
  role: 'user' | 'admin';
}

interface AdminDashboardProps {
  onLogout: () => void;
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout }) => {
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [toast, setToast] = useState<{msg: string, type: 'success' | 'error' | 'warning'} | null>(null);

  const [userToReset, setUserToReset] = useState<{email: string, id: string} | null>(null);
  const [isResetting, setIsResetting] = useState(false);
  const [tempPassword, setTempPassword] = useState('');

  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    userId: string;
    userName: string;
    newStatus: 'active' | 'disabled';
  }>({ isOpen: false, userId: '', userName: '', newStatus: 'active' });

  const fetchUsers = async () => {
    setLoading(true);
    setError(null);
    try {
        const data = await db.getAllProfiles();
        setUsers(data as AdminUser[]);
    } catch (err: any) {
        console.error("Errore fetch:", err);
        setError("Errore nel caricamento dal database.");
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => { fetchUsers(); }, []);

  const showToast = (msg: string, type: 'success' | 'error' | 'warning' = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleToggleStatusRequest = (user: AdminUser, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    setConfirmConfig({
      isOpen: true,
      userId: user.id,
      userName: user.display_name || user.email,
      newStatus: user.status === 'active' ? 'disabled' : 'active'
    });
  };

  const executeToggleStatus = async () => {
    const { userId, newStatus } = confirmConfig;
    setConfirmConfig(prev => ({ ...prev, isOpen: false }));

    try {
        const data = await db.updateUserStatus(userId, newStatus);
        if (!data || data.length === 0) {
             showToast("Errore: Il database ha rifiutato la modifica (Verifica Policy SQL)", "error");
             return;
        }
        setUsers(prev => prev.map(u => u.id === userId ? { ...u, status: newStatus } : u));
        showToast(`Utente ${newStatus === 'active' ? 'riattivato' : 'disabilitato'} con successo`);
    } catch (err: any) {
        console.error("Errore durante l'aggiornamento:", err);
        showToast("Errore: " + err.message, "error");
    }
  };

  const sendNotification = async (userId: string) => {
    const title = prompt("Titolo del messaggio:");
    const text = prompt("Testo della notifica:");

    if (title && text) {
      const { error } = await supabaseAdmin
        .from('notifications')
        .insert([{ user_id: userId, title: title, message: text }]);

      if (error) showToast("Errore: " + error.message, "error");
      else showToast("Notifica inviata con successo!");
    }
  };

  const confirmResetPassword = async () => {
    if (!userToReset) return;
    setIsResetting(true);

    try {
      const { error } = await supabase.auth.resetPasswordForEmail(userToReset.email, {
        redirectTo: window.location.origin,
      });
      if (error) throw error;
      showToast(`📧 Email di reset inviata a ${userToReset.email}!`, 'success');
      setUserToReset(null);
    } catch (err: any) {
      showToast('Errore reset password: ' + err.message, 'error');
    } finally {
      setIsResetting(false);
    }
  };

  const handleSetTempPassword = async () => {
    if (!userToReset || !tempPassword) return;
    setIsResetting(true);

    try {
      const { error } = await supabaseAdmin.auth.admin.updateUserById(
        userToReset.id,
        { password: tempPassword }
      );

      if (error) throw error;

      showToast(`✅ Password cambiata con successo per ${userToReset.email}!`, 'success');
      setUserToReset(null);
      setTempPassword('');
    } catch (err: any) {
      console.error("Errore Admin Auth:", err);
      showToast('Errore setup password: ' + err.message, 'error');
    } finally {
      setIsResetting(false);
    }
  };

  const filteredUsers = users.filter(u => 
    (u.email || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
    (u.display_name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white pb-20 md:pb-0">
      {toast && (
        <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[150] px-6 py-3 rounded-2xl shadow-xl flex items-center gap-2 animate-in slide-in-from-top-4 ${
          toast.type === 'success' ? 'bg-emerald-600 text-white' : 
          toast.type === 'warning' ? 'bg-amber-500 text-white' : 'bg-red-500 text-white'
        }`}>
          {toast.type === 'success' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
          <span className="font-bold text-sm">{toast.msg}</span>
        </div>
      )}

      <header className="bg-white dark:bg-gray-800 border-b sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Shield className="text-emerald-500" size={32} />
            <h1 className="text-xl font-black">MintFlow <span className="text-emerald-500">Admin</span></h1>
          </div>
          <div className="flex items-center gap-4">
            <button onClick={() => showToast("Script SQL già configurato nel DB.", "warning")} title="Database Schema" className="p-2 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 rounded-xl"><Database size={20} /></button>
            <button onClick={onLogout} className="flex items-center gap-2 px-4 py-2 bg-gray-100 dark:bg-gray-700 rounded-xl font-bold"><LogOut size={20} /> Esci</button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8">
        <div className="mb-8 relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
          <input type="text" placeholder="Cerca utente per nome o email..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white dark:bg-gray-800 border-none shadow-sm outline-none focus:ring-2 focus:ring-emerald-500" />
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-gray-50 dark:bg-gray-700/50">
              <tr>
                <th className="px-6 py-4 font-bold text-xs uppercase tracking-wider text-gray-500 dark:text-gray-400">Utente</th>
                <th className="px-6 py-4 font-bold text-xs uppercase tracking-wider text-gray-500 dark:text-gray-400">Stato</th>
                <th className="px-6 py-4 font-bold text-xs uppercase tracking-wider text-gray-500 dark:text-gray-400">Azioni</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
              {loading ? (
                <tr><td colSpan={3} className="p-12 text-center"><Loader2 className="animate-spin mx-auto text-emerald-500" /></td></tr>
              ) : filteredUsers.length > 0 ? (
                filteredUsers.map(user => (
                  <tr key={user.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                    <td className="px-6 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-emerald-500 rounded-full flex items-center justify-center text-white font-bold shrink-0">{(user.display_name || user.email).charAt(0).toUpperCase()}</div>
                        <div className="min-w-0">
                          <div className="font-bold truncate">{user.display_name}</div>
                          <div className="text-sm text-gray-500 truncate">{user.email}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-6">
                      <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${user.status === 'active' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'}`}>{user.status}</span>
                    </td>
                    <td className="px-6 py-6">
                      {user.email !== 'admin@mintflow.com' && (
                        <div className="flex gap-2">
                          <button 
                            onClick={() => setUserToReset({ email: user.email, id: user.id })}
                            className="p-3 bg-amber-50 dark:bg-amber-900/20 text-amber-500 rounded-2xl hover:scale-110 transition-transform active:scale-95 shadow-sm"
                            title="Sicurezza Account"
                          >
                            <Key size={20} />
                          </button>
                          <button 
                            onClick={() => sendNotification(user.id)} 
                            className="p-3 bg-blue-50 dark:bg-blue-900/20 text-blue-500 rounded-2xl hover:scale-110 transition-transform active:scale-95 shadow-sm"
                            title="Invia Notifica"
                          >
                            <Bell size={20} />
                          </button>
                          <button 
                            onClick={e => handleToggleStatusRequest(user, e)} 
                            className={`p-3 rounded-2xl transition-all hover:scale-110 active:scale-95 shadow-sm ${
                              user.status === 'active' 
                                ? 'text-gray-400 bg-gray-100 hover:text-red-500 hover:bg-red-50 dark:bg-gray-700' 
                                : 'text-white bg-emerald-500 shadow-emerald-100'
                            }`}
                            title={user.status === 'active' ? "Disabilita Account" : "Attiva Account"}
                          >
                            {user.status === 'active' ? <Ban size={20} /> : <CheckCircle2 size={20} />}
                          </button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))
              ) : (
                <tr><td colSpan={3} className="p-12 text-center text-gray-400">Nessun utente trovato</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </main>

      {/* MODAL RESET PASSWORD & SICUREZZA */}
      {userToReset && (
        <div className="fixed inset-0 z-[160] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-in fade-in duration-200">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-sm p-8 shadow-2xl animate-in zoom-in-95 border border-amber-100 dark:border-gray-700 relative overflow-hidden">
            <button onClick={() => { setUserToReset(null); setTempPassword(''); }} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 transition-colors"><X size={24} /></button>
            <div className="bg-amber-100 dark:bg-amber-900/30 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 text-amber-600 shadow-inner"><Key size={32} /></div>
            <h2 className="text-2xl font-black text-gray-800 dark:text-white mb-2 tracking-tight">Sicurezza Account</h2>
            <p className="text-gray-500 dark:text-gray-400 mb-8 font-medium leading-relaxed">Gestione accesso per: <br/><span className="font-bold text-emerald-600 dark:text-emerald-400">{userToReset.email}</span></p>
            <div className="space-y-4">
              <button onClick={confirmResetPassword} disabled={isResetting} className="w-full py-4 bg-amber-500 text-white rounded-2xl font-bold shadow-lg shadow-amber-200 dark:shadow-none hover:bg-amber-600 active:scale-95 transition-all flex items-center justify-center gap-2">{isResetting ? <Loader2 className="animate-spin" size={18} /> : <Mail size={18} />}Invia Email di Reset</button>
              <div className="relative my-6 text-center"><hr className="border-gray-100 dark:border-gray-700" /><span className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white dark:bg-gray-800 px-3 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Oppure imposta subito</span></div>
              <div className="space-y-3">
                <input type="text" placeholder="Password temporanea..." value={tempPassword} onChange={(e) => setTempPassword(e.target.value)} className="w-full px-5 py-4 bg-gray-50 dark:bg-gray-700 rounded-2xl border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white font-medium" />
                <button onClick={handleSetTempPassword} disabled={isResetting || !tempPassword} className="w-full py-4 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-2xl font-bold disabled:opacity-50 transition-all flex items-center justify-center gap-2 active:scale-95">{isResetting ? <Loader2 className="animate-spin" size={18} /> : <Check size={18} />}Aggiorna Password Ora</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* MODAL DI CONFERMA STATO */}
      <ConfirmModal 
        isOpen={confirmConfig.isOpen}
        title={confirmConfig.newStatus === 'disabled' ? "Disabilita Utente" : "Riattiva Utente"}
        message={`Sei sicuro di voler cambiare lo stato di ${confirmConfig.userName} a ${confirmConfig.newStatus === 'disabled' ? 'Disabilitato' : 'Attivo'}?`}
        confirmText={confirmConfig.newStatus === 'disabled' ? "Sì, Blocca" : "Sì, Attiva"}
        type={confirmConfig.newStatus === 'disabled' ? 'danger' : 'success'}
        onConfirm={executeToggleStatus}
        onCancel={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}
      />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, List, BrainCircuit, PiggyBank, Settings, Zap, Repeat, ArrowRightLeft, Bell, X, Mail, CheckCircle2, Calendar } from 'lucide-react';
import { translations } from '../utils/i18n';
import { ProfileType, AppNotification } from '../types';
import { supabase, db } from '../services/supabase';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: 'dashboard' | 'list' | 'ai' | 'settings' | 'ricariche' | 'subscriptions' | 'extra';
  setActiveTab: (tab: 'dashboard' | 'list' | 'ai' | 'settings' | 'ricariche' | 'subscriptions' | 'extra') => void;
  lang?: 'it' | 'en';
  currentProfile?: ProfileType;
}

export const Layout: React.FC<LayoutProps> = ({ children, activeTab, setActiveTab, lang = 'it', currentProfile = 'personal' }) => {
  const t = translations[lang].nav;
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [isNotifPanelOpen, setIsNotifPanelOpen] = useState(false);
  const [selectedNotification, setSelectedNotification] = useState<AppNotification | null>(null);

  useEffect(() => {
    const fetchAndSubscribe = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const data = await db.getNotifications(user.id);
      setNotifications(data);

      const channel = supabase
        .channel(`global-notifs-${user.id}`)
        .on('postgres_changes', 
          { 
            event: 'INSERT', 
            schema: 'public', 
            table: 'notifications', 
            filter: `user_id=eq.${user.id}` 
          }, 
          (payload) => {
            setNotifications(prev => [payload.new as AppNotification, ...prev]);
          }
        )
        .subscribe();

      return () => { supabase.removeChannel(channel); };
    };

    fetchAndSubscribe();
  }, []);

  const unreadCount = notifications.filter(n => !n.is_read).length;

  const handleMarkRead = async (id: string) => {
    await db.markNotificationRead(id);
    setNotifications(prev => prev.map(n => n.id === id ? { ...n, is_read: true } : n));
  };

  const handleNotificationClick = (n: AppNotification) => {
    if (!n.is_read) handleMarkRead(n.id);
    setSelectedNotification(n);
    setIsNotifPanelOpen(false);
  };

  return (
    <div className="min-h-screen bg-white dark:bg-gray-900 text-gray-900 dark:text-white transition-colors duration-300">
      <header className="sticky top-0 z-40 bg-white/80 dark:bg-gray-900/80 backdrop-blur-md border-b border-emerald-100 dark:border-gray-800">
        <div className="max-w-4xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-emerald-100 dark:bg-emerald-900/30 p-2 rounded-lg">
              <PiggyBank className="text-emerald-600 dark:text-emerald-400" size={24} />
            </div>
            <span className="text-xl font-black bg-gradient-to-r from-emerald-600 to-teal-500 bg-clip-text text-transparent">
              MintFlow
            </span>
          </div>

          <div className="flex items-center gap-3">
            <div className="relative">
              <button 
                onClick={() => setIsNotifPanelOpen(!isNotifPanelOpen)}
                className={`relative p-2.5 rounded-xl transition-all ${isNotifPanelOpen ? 'bg-emerald-100 text-emerald-600' : 'text-gray-400 hover:bg-emerald-50 dark:hover:bg-gray-800'}`}
              >
                <Bell size={22} />
                {unreadCount > 0 && (
                  <span className="absolute top-1.5 right-1.5 bg-red-500 text-white text-[8px] w-4 h-4 rounded-full flex items-center justify-center font-bold animate-bounce shadow-sm ring-2 ring-white dark:ring-gray-900">
                    {unreadCount}
                  </span>
                )}
              </button>

              {isNotifPanelOpen && (
                <div className="absolute right-0 mt-3 w-80 bg-white dark:bg-gray-800 shadow-[0_20px_50px_rgba(0,0,0,0.15)] rounded-[2rem] border border-gray-100 dark:border-gray-700 z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                  <div className="p-5 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50/50 dark:bg-gray-800/50">
                    <h3 className="font-black text-gray-800 dark:text-white uppercase tracking-widest text-[10px]">Le tue notifiche</h3>
                    <button onClick={() => setIsNotifPanelOpen(false)} className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full text-gray-400"><X size={16} /></button>
                  </div>
                  <div className="max-h-[360px] overflow-y-auto custom-scrollbar">
                    {notifications.length === 0 ? (
                      <div className="py-12 text-center text-gray-400">
                        <Mail className="mx-auto mb-2 opacity-20" size={32} />
                        <p className="text-sm font-medium">Nessuna notifica</p>
                      </div>
                    ) : (
                      notifications.map((n) => (
                        <div 
                          key={n.id} 
                          onClick={() => handleNotificationClick(n)}
                          className={`p-5 border-b border-gray-50 dark:border-gray-700 hover:bg-emerald-50/30 dark:hover:bg-gray-700 transition cursor-pointer ${!n.is_read ? 'bg-emerald-50/40 dark:bg-emerald-900/10' : ''}`}
                        >
                          <div className="flex items-start gap-4">
                            <div className={`mt-1 shrink-0 ${!n.is_read ? 'text-emerald-500 font-bold' : 'text-gray-300'}`}>
                              <Mail size={18} />
                            </div>
                            <div className="min-w-0 flex-1">
                              <p className={`text-sm font-bold truncate ${!n.is_read ? 'text-gray-900 dark:text-white' : 'text-gray-500'}`}>{n.title}</p>
                              <p className="text-xs text-gray-500 dark:text-gray-400 mt-1 line-clamp-2 leading-relaxed">{n.message}</p>
                              <p className="text-[9px] text-gray-400 mt-2 font-black uppercase tracking-tighter">{new Date(n.created_at).toLocaleDateString()}</p>
                            </div>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}
            </div>

            <div className="hidden md:flex items-center gap-1 bg-white dark:bg-gray-800 p-1 rounded-2xl border border-emerald-50 dark:border-gray-700">
              <NavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={<LayoutDashboard size={18} />} label={t.dashboard} />
              <NavButton active={activeTab === 'list'} onClick={() => setActiveTab('list')} icon={<List size={18} />} label={t.expenses} />
              <NavButton active={activeTab === 'extra'} onClick={() => setActiveTab('extra')} icon={<ArrowRightLeft size={18} />} label={t.extra} />
              <NavButton active={activeTab === 'subscriptions'} onClick={() => setActiveTab('subscriptions')} icon={<Repeat size={18} />} label={t.subscriptions} />
              <NavButton active={activeTab === 'ricariche'} onClick={() => setActiveTab('ricariche')} icon={<Zap size={18} />} label={t.wallets} />
              <NavButton active={activeTab === 'ai'} onClick={() => setActiveTab('ai')} icon={<BrainCircuit size={18} />} label={t.ai} />
              <NavButton active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} icon={<Settings size={18} />} label={t.settings} />
            </div>
          </div>
        </div>
      </header>

      {/* Full Notification Content Modal (User Style) */}
      {selectedNotification && (
        <div className="fixed inset-0 z-[200] bg-black/60 backdrop-blur-md flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-gray-800 rounded-[3rem] w-full max-w-md p-10 shadow-2xl border border-emerald-100 dark:border-emerald-900/30 relative animate-in zoom-in-95 duration-300">
            <button 
              onClick={() => setSelectedNotification(null)}
