                            onClick={() => sendNotification(user.id)} 
                            className="p-3 bg-blue-50 dark:bg-blue-900/20 text-blue-500 rounded-2xl hover:scale-110 transition-transform active:scale-95 shadow-sm"
                            title="Invia Notifica"
                          >
                            <Bell size={20} />
                          </button>
                          <button 
                            onClick={e => handleToggleStatusRequest(user, e)} 
                            className={`p-3 rounded-2xl transition-all hover:scale-110 active:scale-95 shadow-sm ${
                              user.status === 'active' 
                                ? 'text-gray-400 bg-gray-100 hover:text-red-500 hover:bg-red-50 dark:bg-gray-700' 
                                : 'text-white bg-emerald-500 shadow-emerald-100'
                            }`}
                            title={user.status === 'active' ? "Disabilita Account" : "Attiva Account"}
                          >
                            {user.status === 'active' ? <Ban size={20} /> : <CheckCircle2 size={20} />}
                          </button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))
              ) : (
                <tr><td colSpan={3} className="p-12 text-center text-gray-400">Nessun utente trovato</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </main>

      {userToReset && (
        <div className="fixed inset-0 z-[160] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-in fade-in duration-200">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-sm p-8 shadow-2xl animate-in zoom-in-95 border border-amber-100 dark:border-gray-700 relative overflow-hidden">
            <button onClick={() => { setUserToReset(null); setTempPassword(''); }} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 transition-colors"><X size={24} /></button>
            <div className="bg-amber-100 dark:bg-amber-900/30 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 text-amber-600 shadow-inner"><Key size={32} /></div>
            <h2 className="text-2xl font-black text-gray-800 dark:text-white mb-2 tracking-tight">Sicurezza Account</h2>
            <p className="text-gray-500 dark:text-gray-400 mb-8 font-medium leading-relaxed">Gestione accesso per: <br/><span className="font-bold text-emerald-600 dark:text-emerald-400">{userToReset.email}</span></p>
            <div className="space-y-4">
              <button onClick={confirmResetPassword} disabled={isResetting} className="w-full py-4 bg-amber-500 text-white rounded-2xl font-bold shadow-lg shadow-amber-200 dark:shadow-none hover:bg-amber-600 active:scale-95 transition-all flex items-center justify-center gap-2">{isResetting ? <Loader2 className="animate-spin" size={18} /> : <Mail size={18} />}Invia Email di Reset</button>
              <div className="relative my-6 text-center"><hr className="border-gray-100 dark:border-gray-700" /><span className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white dark:bg-gray-800 px-3 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Oppure imposta subito</span></div>
              <div className="space-y-3">
                <input type="text" placeholder="Password temporanea..." value={tempPassword} onChange={(e) => setTempPassword(e.target.value)} className="w-full px-5 py-4 bg-gray-50 dark:bg-gray-700 rounded-2xl border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white font-medium" />
                <button onClick={handleSetTempPassword} disabled={isResetting || !tempPassword} className="w-full py-4 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-2xl font-bold disabled:opacity-50 transition-all flex items-center justify-center gap-2 active:scale-95">{isResetting ? <Loader2 className="animate-spin" size={18} /> : <Check size={18} />}Aggiorna Password Ora</button>
              </div>
            </div>
          </div>
        </div>
      )}

      <ConfirmModal 
        isOpen={confirmConfig.isOpen}
        title={confirmConfig.newStatus === 'disabled' ? "Disabilita Utente" : "Riattiva Utente"}
        message={`Sei sicuro di voler cambiare lo stato di ${confirmConfig.userName} a ${confirmConfig.newStatus === 'disabled' ? 'Disabilitato' : 'Attivo'}?`}
        confirmText={confirmConfig.newStatus === 'disabled' ? "Sì, Blocca" : "Sì, Attiva"}
        type={confirmConfig.newStatus === 'disabled' ? 'danger' : 'success'}
        onConfirm={executeToggleStatus}
        onCancel={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}
      />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, List, BrainCircuit, PiggyBank, Settings, Zap, Repeat, ArrowRightLeft, Bell, X, Mail, CheckCircle2, Calendar, Trash2 } from 'lucide-react';
import { translations } from '../utils/i18n';
import { ProfileType, AppNotification } from '../types';
import { supabase, db } from '../services/supabase';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: 'dashboard' | 'list' | 'ai' | 'settings' | 'ricariche' | 'subscriptions' | 'extra';
  setActiveTab: (tab: 'dashboard' | 'list' | 'ai' | 'settings' | 'ricariche' | 'subscriptions' | 'extra') => void;
  lang?: 'it' | 'en';
  currentProfile?: ProfileType;
}

export const Layout: React.FC<LayoutProps> = ({ children, activeTab, setActiveTab, lang = 'it', currentProfile = 'personal' }) => {
  const t = translations[lang].nav;
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [isNotifPanelOpen, setIsNotifPanelOpen] = useState(false);
  const [selectedNotification, setSelectedNotification] = useState<AppNotification | null>(null);

  useEffect(() => {
    const fetchAndSubscribe = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const data = await db.getNotifications(user.id);
      setNotifications(data);

      const channel = supabase
        .channel(`global-notifs-${user.id}`)
        .on('postgres_changes', 
          { 
            event: 'INSERT', 
            schema: 'public', 
            table: 'notifications', 
            filter: `user_id=eq.${user.id}` 
          }, 
          (payload) => {
            setNotifications(prev => [payload.new as AppNotification, ...prev]);
          }
        )
        .subscribe();

      return () => { supabase.removeChannel(channel); };
    };

    fetchAndSubscribe();
  }, []);

  const unreadCount = notifications.filter(n => !n.is_read).length;

  const handleMarkRead = async (id: string) => {
    await db.markNotificationRead(id);
    setNotifications(prev => prev.map(n => n.id === id ? { ...n, is_read: true } : n));
  };

  const handleDelete = async (id: string) => {
    if (confirm("Vuoi cancellare definitivamente questa notifica?")) {
      await db.deleteNotification(id);
      setNotifications(prev => prev.filter(n => n.id !== id));
      setSelectedNotification(null);
    }
  };

  const openNotification = (n: AppNotification) => {
    if (!n.is_read) handleMarkRead(n.id);
    setSelectedNotification(n);
    setIsNotifPanelOpen(false);
  };

  return (
    <div className="min-h-screen bg-white dark:bg-gray-900 text-gray-900 dark:text-white transition-colors duration-300">
      <header className="sticky top-0 z-40 bg-white/80 dark:bg-gray-900/80 backdrop-blur-md border-b border-emerald-100 dark:border-gray-800">
        <div className="max-w-4xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-emerald-100 dark:bg-emerald-900/30 p-2 rounded-lg">
              <PiggyBank className="text-emerald-600 dark:text-emerald-400" size={24} />
            </div>
            <span className="text-xl font-black bg-gradient-to-r from-emerald-600 to-teal-500 bg-clip-text text-transparent">
              MintFlow
            </span>
          </div>

          <div className="flex items-center gap-3">
            <div className="relative">
              <button 
                onClick={() => setIsNotifPanelOpen(!isNotifPanelOpen)}
                className={`relative p-2.5 rounded-xl transition-all ${isNotifPanelOpen ? 'bg-emerald-100 text-emerald-600' : 'text-gray-400 hover:bg-emerald-50 dark:hover:bg-gray-800'}`}
              >
                <Bell size={22} />
                {unreadCount > 0 && (
                  <span className="absolute top-1.5 right-1.5 bg-red-500 text-white text-[8px] w-4 h-4 rounded-full flex items-center justify-center font-bold animate-bounce shadow-sm ring-2 ring-white dark:ring-gray-900">
                    {unreadCount}
                  </span>
                )}
              </button>

              {isNotifPanelOpen && (
                <div className="absolute right-0 mt-3 w-80 bg-white dark:bg-gray-800 shadow-[0_20px_50px_rgba(0,0,0,0.15)] rounded-[2rem] border border-gray-100 dark:border-gray-700 z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                  <div className="p-5 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-gray-50/50 dark:bg-gray-800/50">
                    <h3 className="font-black text-gray-800 dark:text-white uppercase tracking-widest text-xs">Notifiche</h3>
                    <button onClick={() => setIsNotifPanelOpen(false)} className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-full"><X size={16} /></button>
                  </div>
                  <div className="max-h-[360px] overflow-y-auto no-scrollbar">
                    {notifications.length === 0 ? (
                      <div className="py-12 text-center text-gray-400">
                        <Mail className="mx-auto mb-2 opacity-20" size={32} />
                        <p className="text-sm font-medium">Nessuna notifica</p>
                      </div>
                    ) : (
                      notifications.map((n) => (
                        <div 
                          key={n.id} 
                          onClick={() => openNotification(n)}
                          className={`p-5 border-b border-gray-50 dark:border-gray-700 hover:bg-emerald-50/30 dark:hover:bg-gray-700 transition cursor-pointer ${!n.is_read ? 'bg-emerald-50/40 dark:bg-emerald-900/10' : ''}`}
                        >
                          <div className="flex items-start gap-4">
                            <div className={`mt-1 shrink-0 ${!n.is_read ? 'text-emerald-500' : 'text-gray-300'}`}>
                              <Mail size={18} />
                            </div>
                            <div className="min-w-0 flex-1">
                              <p className={`text-sm font-bold truncate ${!n.is_read ? 'text-gray-900 dark:text-white' : 'text-gray-500'}`}>{n.title}</p>
                              <p className="text-[9px] text-gray-400 mt-2 font-black uppercase tracking-tighter">{new Date(n.created_at).toLocaleDateString()}</p>
                            </div>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}
            </div>

            <div className="hidden md:flex items-center gap-1 bg-white dark:bg-gray-800 p-1 rounded-2xl border border-emerald-50 dark:border-gray-700">
              <NavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={<LayoutDashboard size={18} />} label={t.dashboard} />
              <NavButton active={activeTab === 'list'} onClick={() => setActiveTab('list'} icon={<List size={18} />} label={t.expenses} />
              <NavButton active={activeTab === 'extra'} onClick={() => setActiveTab('extra')} icon={<ArrowRightLeft size={18} />} label={t.extra} />
              <NavButton active={activeTab === 'subscriptions'} onClick={() => setActiveTab('subscriptions')} icon={<Repeat size={18} />} label={t.subscriptions} />
              <NavButton active={activeTab === 'ricariche'} onClick={() => setActiveTab('ricariche')} icon={<Zap size={18} />} label={t.wallets} />
              <NavButton active={activeTab === 'ai'} onClick={() => setActiveTab('ai')} icon={<BrainCircuit size={18} />} label={t.ai} />
              <NavButton active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} icon={<Settings size={18} />} label={t.settings} />
            </div>
          </div>
        </div>
      </header>

      {selectedNotification && (
        <div className="fixed inset-0 z-[200] bg-black/60 backdrop-blur-md flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-gray-800 rounded-[3rem] w-full max-w-md p-10 shadow-2xl border border-emerald-100 dark:border-emerald-900/30 relative animate-in zoom-in-95 duration-300">
            <button 
              onClick={() => setSelectedNotification(null)}
              className="absolute top-8 right-8 text-gray-400 hover:text-emerald-500 hover:bg-emerald-50 dark:hover:bg-gray-700 p-2 rounded-full transition-all"
            >
              <X size={24} />
            </button>

            <div className="bg-emerald-50 dark:bg-emerald-900/20 w-16 h-16 rounded-[1.5rem] flex items-center justify-center mb-8 text-emerald-500">
              <Mail size={32} />
            </div>

            <div className="space-y-4">
              <div className="flex items-center gap-2 text-[10px] font-black text-emerald-600 dark:text-emerald-400 uppercase tracking-widest bg-emerald-50 dark:bg-emerald-900/20 w-fit px-3 py-1.5 rounded-full">
                <Calendar size={12} /> {new Date(selectedNotification.created_at).toLocaleString('it-IT', { day: '2-digit', month: 'long', hour: '2-digit', minute: '2-digit' })}
              </div>
              <h3 className="text-2xl font-black text-gray-900 dark:text-white leading-tight">
                {selectedNotification.title}
              </h3>
              <div className="h-px bg-emerald-100 dark:bg-gray-700 w-full opacity-50"></div>
              <p className="text-gray-600 dark:text-gray-400 leading-relaxed text-lg pt-2 font-medium">
                {selectedNotification.message}
              </p>
            </div>

            <div className="flex gap-4 mt-10">
              <button 
                onClick={() => setSelectedNotification(null)}
                className="flex-1 py-5 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-[2rem] font-black uppercase tracking-widest text-xs hover:bg-gray-200 transition-all active:scale-95"
              >
                Chiudi
              </button>
              <button 
                onClick={() => handleDelete(selectedNotification.id)}
                className="flex-1 py-5 bg-red-50 text-red-500 rounded-[2rem] font-black uppercase tracking-widest text-xs flex items-center justify-center gap-2 hover:bg-red-100 transition-all active:scale-95"
              >
                <Trash2 size={16} /> Cancella
              </button>
            </div>
          </div>
        </div>
      )}

      <main>{children}</main>

      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-white dark:bg-gray-900 border-t border-emerald-100 dark:border-gray-800 h-20 px-4 flex items-center overflow-x-auto no-scrollbar gap-8 pb-4 transition-colors z-30">
        <MobileNavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={<LayoutDashboard />} label="Home" />
        <MobileNavButton active={activeTab === 'list'} onClick={() => setActiveTab('list')} icon={<List />} label={t.expenses} />
        <MobileNavButton active={activeTab === 'extra'} onClick={() => setActiveTab('extra')} icon={<ArrowRightLeft />} label={t.extra} />
        <MobileNavButton active={activeTab === 'subscriptions'} onClick={() => setActiveTab('subscriptions')} icon={<Repeat />} label={t.subscriptions.substring(0, 5)} />
        <MobileNavButton active={activeTab === 'ricariche'} onClick={() => setActiveTab('ricariche')} icon={<Zap />} label={t.wallets} />
        <MobileNavButton active={activeTab === 'ai'} onClick={() => setActiveTab('ai')} icon={<BrainCircuit />} label="AI" />
        <MobileNavButton active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} icon={<Settings />} label={t.settings.substring(0, 4)} />
      </nav>
    </div>
  );
};

const NavButton = ({ active, onClick, icon, label }: any) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-2 px-3 py-2 rounded-xl transition-all ${
      active 
        ? 'bg-emerald-500 text-white shadow-md font-bold' 
        : 'text-emerald-600 dark:text-gray-400 hover:bg-emerald-50 dark:hover:bg-gray-800'
    }`}
  >
    {icon}
    <span className="text-sm">{label}</span>
  </button>
);

const MobileNavButton = ({ active, onClick, icon, label }: any) => (
  <button
    onClick={onClick}
    className={`flex flex-col items-center gap-1 transition-all min-w-[60px] shrink-0 ${
      active ? 'text-emerald-600 dark:text-emerald-400' : 'text-gray-400 dark:text-gray-500'
    }`}
  >
    {React.cloneElement(icon, { size: 22, strokeWidth: active ? 2.5 : 2 })}
