);

import React, { useState, useRef } from 'react';
import { UserSettings, Expense, WalletConfig, CategoryConfig, PaymentMethod } from '../types';
import { User, DollarSign, Trash2, Download, Moon, Sun, LogOut, FileDown, History, CheckCircle2, Edit3, X, Lock, Wallet, Tag, ChevronRight, Plus, ChevronLeft, Save, Check, Upload, Loader2, Eraser } from 'lucide-react';
import { auth } from '../services/supabase';
import { HistoryView } from './HistoryView';
import { translations } from '../utils/i18n';

const SettingsRow = ({ icon, label, onClick }: { icon: React.ReactNode, label: string, onClick: () => void }) => (
  <button type="button" onClick={onClick} className="w-full flex items-center justify-between px-6 py-5 md:px-8 md:py-6 hover:bg-emerald-50 dark:hover:bg-gray-700/50 transition-all group text-left">
    <div className="flex items-center gap-4">
      <div className="text-emerald-500">{icon}</div>
      <span className="font-bold text-gray-700 dark:text-gray-200 text-sm md:text-base">{label}</span>
    </div>
    <ChevronRight className="text-gray-300 group-hover:text-emerald-500 group-hover:translate-x-1 transition-all" size={20} />
  </button>
);

const Modal = ({ isOpen, onClose, title, children }: { isOpen: boolean, onClose: () => void, title: string, children?: React.ReactNode }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-md z-[110] flex items-center justify-center p-4">
      <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white">{title}</h2>
          <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors"><X size={24} /></button>
        </div>
        {children}
      </div>
    </div>
  );
};

interface SettingsViewProps {
  settings: UserSettings;
  onUpdate: (settings: UserSettings) => void;
  onClearData: () => void;
  onDeleteAdjustments?: () => void;
  onImport?: (file: File) => Promise<{ imported: number; skipped: number; errors: string[], debugInfo: string }>;
  onExport?: () => void;
  expenses: Expense[];
  email?: string;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ 
  settings, 
  onUpdate, 
  onClearData,
  onDeleteAdjustments,
  onImport,
  onExport,
  expenses,
  email
}) => {
  const [view, setView] = useState<'main' | 'history' | 'wallets' | 'categories'>('main');
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);

  const [isAdding, setIsAdding] = useState(false);
  const [newItemName, setNewItemName] = useState('');
  const [newItemColor, setNewItemColor] = useState('#10b981');

  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editColor, setEditColor] = useState('');

  const [tempName, setTempName] = useState(settings.name);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const lang = settings.language || 'it';
  const t = translations[lang].settings;
  const tNav = translations[lang].nav;

  const showFeedback = (msg: string) => {
    setFeedback(msg);
    setTimeout(() => setFeedback(null), 3000);
  };

  const handleUpdateProfile = async () => {
    setIsUpdating(true);
    try {
      if (tempName !== settings.name) {
        await auth.updateProfile(tempName);
        onUpdate({ ...settings, name: tempName });
      }
      showFeedback("Profilo aggiornato!");
      setShowProfileModal(false);
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleAddItem = (type: 'wallet' | 'category') => {
    if (!newItemName.trim()) return;

    if (type === 'wallet') {
      const newWallet: WalletConfig = {
        id: 'w' + Date.now(),
        name: newItemName.trim(),
        method: newItemName.trim() as PaymentMethod,
        icon: 'credit-card'
      };
      onUpdate({ ...settings, wallets: [...settings.wallets, newWallet] });
    } else {
      const newCat: CategoryConfig = {
        id: 'c' + Date.now(),
        name: newItemName.trim(),
        color: newItemColor
      };
      onUpdate({ ...settings, categories: [...settings.categories, newCat] });
    }

    setNewItemName('');
    setIsAdding(false);
    showFeedback("Aggiunto con successo!");
  };

  const startEditing = (item: CategoryConfig) => {
    setEditingId(item.id);
    setEditName(item.name);
    setEditColor(item.color || '#10b981');
  };

  const saveEdit = () => {
    if (!editName.trim()) return;
    const newCats = settings.categories.map(c => 
      c.id === editingId ? { ...c, name: editName, color: editColor } : c
    );
    onUpdate({ ...settings, categories: newCats });
    setEditingId(null);
    showFeedback("Modifica salvata!");
  };

  if (view === 'history') return <HistoryView expenses={expenses} onClose={() => setView('main')} currency={settings.currency} />;

  if (view === 'wallets') return (
    <div className="fixed inset-0 bg-white dark:bg-gray-900 z-[80] overflow-y-auto animate-in slide-in-from-right duration-300">
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        <button type="button" onClick={() => { setView('main'); setIsAdding(false); }} className="flex items-center gap-2 text-emerald-600 font-bold mb-6 hover:translate-x-[-4px] transition-transform"><ChevronLeft /> {tNav.settings}</button>
        <h2 className="text-3xl font-black dark:text-white mb-6">I tuoi Portafogli</h2>
        <div className="space-y-4">
          {settings.wallets.map(w => (
            <div key={w.id} className="flex items-center justify-between p-6 bg-white dark:bg-gray-800 rounded-3xl border border-emerald-50 dark:border-gray-700 shadow-sm">
              <div className="flex items-center gap-4 font-bold dark:text-white">
                <div className="p-3 bg-emerald-50 dark:bg-emerald-900/20 rounded-2xl text-emerald-500"><Wallet /></div>
                <span>{w.name}</span>
              </div>
              <button onClick={() => onUpdate({ ...settings, wallets: settings.wallets.filter(x => x.id !== w.id) })} className="p-3 text-red-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-2xl transition-all">
                <Trash2 size={20} />
              </button>
            </div>
          ))}
          {isAdding ? (
            <div className="space-y-4 p-6 bg-emerald-50 dark:bg-emerald-900/10 rounded-[2.5rem] border-2 border-emerald-500 animate-in zoom-in-95 duration-200">
              <input autoFocus type="text" value={newItemName} onChange={(e) => setNewItemName(e.target.value)} placeholder="Nome portafoglio" className="w-full px-5 py-4 rounded-2xl bg-white dark:bg-gray-700 border-none outline-none dark:text-white font-bold" />
              <div className="flex gap-2">
                <button type="button" onClick={() => handleAddItem('wallet')} className="flex-1 py-4 bg-emerald-500 text-white rounded-2xl font-bold">Salva</button>
                <button type="button" onClick={() => setIsAdding(false)} className="px-6 py-4 bg-white dark:bg-gray-600 text-gray-400 rounded-2xl font-bold">Annulla</button>
              </div>
            </div>
          ) : (
            <button type="button" onClick={() => setIsAdding(true)} className="w-full py-5 bg-emerald-500 text-white rounded-[2rem] font-bold flex items-center justify-center gap-2 mt-4 shadow-lg active:scale-95 transition-all">
              <Plus size={24} /> Aggiungi Portafoglio
            </button>
          )}
        </div>
      </div>
    </div>
  );

  if (view === 'categories') return (
    <div className="fixed inset-0 bg-white dark:bg-gray-900 z-[80] overflow-y-auto animate-in slide-in-from-right duration-300">
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        <button type="button" onClick={() => { setView('main'); setIsAdding(false); }} className="flex items-center gap-2 text-emerald-600 font-bold mb-6 hover:translate-x-[-4px] transition-transform"><ChevronLeft /> {tNav.settings}</button>
        <h2 className="text-3xl font-black dark:text-white mb-6">Le tue Categorie</h2>
        <div className="space-y-4">
          {settings.categories.map(c => (
            <div key={c.id} className="p-6 bg-white dark:bg-gray-800 rounded-3xl border border-emerald-50 dark:border-gray-700 shadow-sm">
              {editingId === c.id ? (
                <div className="flex flex-col gap-4 animate-in fade-in duration-200">
                  <div className="flex items-center gap-4">
                    <input type="color" value={editColor} onChange={(e) => setEditColor(e.target.value)} className="w-12 h-12 border-none bg-transparent cursor-pointer rounded-full shrink-0" />
                    <input autoFocus type="text" value={editName} onChange={(e) => setEditName(e.target.value)} className="flex-1 px-4 py-3 bg-gray-50 dark:bg-gray-700 rounded-2xl border-none outline-none dark:text-white font-bold" />
                  </div>
                  <div className="flex gap-2">
                    <button onClick={saveEdit} className="flex-1 py-3 bg-emerald-500 text-white rounded-xl font-bold">Salva</button>
                    <button onClick={() => setEditingId(null)} className="px-6 py-3 bg-gray-100 dark:bg-gray-600 text-gray-500 rounded-xl font-bold">Annulla</button>
                  </div>
                </div>
              ) : (
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 rounded-2xl shadow-inner border border-white/20" style={{ backgroundColor: c.color || '#10b981' }}></div>
                    <span className="font-bold text-gray-800 dark:text-white text-lg">{c.name}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <button onClick={() => startEditing(c)} className="p-3 text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded-2xl transition-all"><Edit3 size={20} /></button>
                    {!c.isSubscriptionDefault && (
                      <button onClick={() => onUpdate({ ...settings, categories: settings.categories.filter(x => x.id !== c.id) })} className="p-3 text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-2xl transition-all"><Trash2 size={20} /></button>
                    )}
                  </div>
                </div>
              )}
            </div>
          ))}
          {isAdding ? (
            <div className="space-y-4 p-6 bg-emerald-50 dark:bg-emerald-900/10 rounded-[2.5rem] border-2 border-emerald-500 animate-in zoom-in-95 duration-200">
              <div className="flex items-center gap-4 bg-white dark:bg-gray-700 rounded-2xl p-2">
                <input type="color" value={newItemColor} onChange={(e) => setNewItemColor(e.target.value)} className="w-12 h-12 border-none bg-transparent cursor-pointer rounded-full" />
                <input autoFocus type="text" value={newItemName} onChange={(e) => setNewItemName(e.target.value)} placeholder="Nuova categoria" className="flex-1 bg-transparent border-none outline-none dark:text-white font-bold px-2" />
              </div>
              <div className="flex gap-2">
                <button type="button" onClick={() => handleAddItem('category')} className="flex-1 py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-lg">Crea</button>
                <button type="button" onClick={() => setIsAdding(false)} className="px-6 py-4 bg-white dark:bg-gray-600 text-gray-400 rounded-2xl font-bold">Annulla</button>
              </div>
            </div>
          ) : (
            <button type="button" onClick={() => setIsAdding(true)} className="w-full py-5 bg-emerald-500 text-white rounded-[2rem] font-bold flex items-center justify-center gap-2 mt-4 shadow-lg active:scale-95">
              <Plus size={24} /> Aggiungi Categoria
            </button>
          )}
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
      {feedback && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[100] px-6 py-3 bg-emerald-500 text-white rounded-2xl shadow-2xl flex items-center gap-2 animate-in fade-in zoom-in duration-300">
          <CheckCircle2 size={16} />
          <span className="font-bold text-xs uppercase tracking-wider">{feedback}</span>
        </div>
      )}

      <div className="bg-white dark:bg-gray-800 p-6 md:p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-500 p-4 rounded-[1.5rem] text-white shrink-0"><User size={24} /></div>
            <div className="min-w-0">
              <h3 className="text-xl font-black text-gray-800 dark:text-white truncate">{settings.name}</h3>
              <p className="text-gray-400 text-sm truncate font-medium">{email}</p>
            </div>
          </div>
          <button type="button" onClick={() => setShowProfileModal(true)} className="px-5 py-2.5 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-emerald-100 transition-all">Modifica</button>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm overflow-hidden">
        <SettingsRow icon={<Lock size={20} />} label={t.changePassword} onClick={() => setShowPasswordModal(true)} />
        <div className="h-[1px] bg-emerald-50 dark:bg-gray-700 mx-6"></div>
        <SettingsRow icon={<Wallet size={20} />} label={t.manageWallets} onClick={() => setView('wallets')} />
        <div className="h-[1px] bg-emerald-50 dark:bg-gray-700 mx-6"></div>
        <SettingsRow icon={<Tag size={20} />} label={t.manageCategories} onClick={() => setView('categories')} />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-black text-gray-800 dark:text-white mb-6 flex items-center gap-2"><DollarSign className="text-emerald-500" size={20} /> Budget Mensile</h3>
          <input type="number" value={settings.monthlyBudget} onChange={(e) => onUpdate({ ...settings, monthlyBudget: Number(e.target.value) })} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white font-black text-3xl" />
        </div>
        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
          <h3 className="text-lg font-black text-gray-800 dark:text-white mb-6 flex items-center gap-2">{settings.isDarkMode ? <Moon className="text-emerald-500" size={20} /> : <Sun className="text-emerald-500" size={20} />} {t.appearance}</h3>
          <button type="button" onClick={() => onUpdate({ ...settings, isDarkMode: !settings.isDarkMode })} className={`w-full py-4 rounded-2xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-md active:scale-95 ${settings.isDarkMode ? 'bg-gray-900 text-white' : 'bg-emerald-100 text-emerald-700'}`}>
            {settings.isDarkMode ? 'Tema Scuro' : 'Tema Chiaro'}
          </button>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
        <h3 className="text-lg font-black text-gray-800 dark:text-white mb-6 flex items-center gap-2"><FileDown className="text-emerald-500" size={20} /> {t.dataArchive}</h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          <button type="button" onClick={() => setView('history')} className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all"><History size={20} /> {t.history}</button>
          <button type="button" onClick={onExport} className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all"><Download size={20} /> {t.export}</button>
          <button type="button" onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center gap-3 p-5 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 dark:text-emerald-400 rounded-2xl font-bold hover:bg-emerald-100 transition-all">
            <Upload size={20} /> {t.import}
            <input type="file" ref={fileInputRef} className="hidden" />
          </button>
        </div>
      </div>

      <div className="p-8 text-center bg-gray-50 dark:bg-gray-800/50 rounded-[2.5rem] border border-red-50 dark:border-red-900/10">
        <button onClick={() => auth.signOut()} className="text-red-500 font-black flex items-center gap-3 mx-auto uppercase tracking-widest text-sm hover:scale-105 transition-transform"><LogOut size={20} /> {t.logout}</button>
      </div>

      <Modal isOpen={showProfileModal} onClose={() => setShowProfileModal(false)} title="Il tuo Nome">
        <input type="text" value={tempName} onChange={(e) => setTempName(e.target.value)} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-none outline-none dark:text-white font-bold mb-6" placeholder="Nome" />
        <button type="button" onClick={handleUpdateProfile} disabled={isUpdating} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-lg shadow-emerald-200">{isUpdating ? "Salvataggio..." : "Aggiorna"}</button>
      </Modal>

      <Modal isOpen={showPasswordModal} onClose={() => setShowPasswordModal(false)} title="Nuova Password">
        <input type="password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-gray-700 border-none outline-none dark:text-white font-bold mb-6" placeholder="Minimo 6 caratteri" />
        <button type="button" onClick={() => auth.updatePassword(newPassword).then(() => setShowPasswordModal(false))} disabled={isUpdating} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-lg shadow-emerald-200">{isUpdating ? "Aggiornamento..." : "Cambia Password"}</button>
      </Modal>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { UserSettings, Expense, WalletConfig, CategoryConfig, PaymentMethod } from '../types';
import { User, DollarSign, Trash2, Download, Moon, Sun, LogOut, FileDown, History, CheckCircle2, Edit3, X, Lock, Wallet, Tag, ChevronRight, Plus, ChevronLeft, Save, Check, Upload, Loader2 } from 'lucide-react';
import { auth } from '../services/supabase';
import { HistoryView } from './HistoryView';
import { translations } from '../utils/i18n';

const SettingsRow = ({ icon, label, onClick }: { icon: React.ReactNode, label: string, onClick: () => void }) => (
  <button type="button" onClick={onClick} className="w-full flex items-center justify-between px-6 py-5 md:px-8 md:py-6 hover:bg-emerald-50 dark:hover:bg-gray-700/50 transition-all group text-left">
    <div className="flex items-center gap-4">
      <div className="text-emerald-500">{icon}</div>
      <span className="font-bold text-gray-700 dark:text-gray-200 text-sm md:text-base">{label}</span>
    </div>
    <ChevronRight className="text-gray-300 group-hover:text-emerald-500 group-hover:translate-x-1 transition-all" size={20} />
  </button>
);

const Modal = ({ isOpen, onClose, title, children }: { isOpen: boolean, onClose: () => void, title: string, children?: React.ReactNode }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-md z-[110] flex items-center justify-center p-4">
      <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-gray-800 dark:text-white">{title}</h2>
          <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors"><X size={24} /></button>
        </div>
        {children}
      </div>
    </div>
  );
};

interface SettingsViewProps {
  settings: UserSettings;
  onUpdate: (settings: UserSettings) => void;
  onClearData: () => void;
  onDeleteAdjustments?: () => void;
  onImport?: (file: File) => Promise<{ imported: number; skipped: number; errors: string[], debugInfo: string }>;
  onExport?: () => void;
  expenses: Expense[];
  email?: string;
}

export const SettingsView: React.FC<SettingsViewProps> = ({ 
  settings, 
  onUpdate, 
  onClearData,
  onImport,
  onExport,
  expenses,
  email
}) => {
  const [view, setView] = useState<'main' | 'history' | 'wallets' | 'categories'>('main');
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);

  const [isAdding, setIsAdding] = useState(false);
  const [newItemName, setNewItemName] = useState('');
  const [newItemColor, setNewItemColor] = useState('#10b981');

  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editColor, setEditColor] = useState('');

  const [tempName, setTempName] = useState(settings.name);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const lang = settings.language || 'it';
  const t = translations[lang].settings;
  const tNav = translations[lang].nav;

  const showFeedback = (msg: string) => {
    setFeedback(msg);
    setTimeout(() => setFeedback(null), 3000);
  };

  const handleUpdateProfile = async () => {
    setIsUpdating(true);
    try {
      if (tempName !== settings.name) {
        await auth.updateProfile(tempName);
        onUpdate({ ...settings, name: tempName });
      }
      showFeedback("Profilo aggiornato!");
      setShowProfileModal(false);
    } catch (err: any) {
      alert("Errore: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleAddItem = (type: 'wallet' | 'category') => {
    if (!newItemName.trim()) return;

    if (type === 'wallet') {
      const newWallet: WalletConfig = {
        id: 'w' + Date.now(),
        name: newItemName.trim(),
        method: newItemName.trim() as PaymentMethod,
        icon: 'credit-card'
      };
      onUpdate({ ...settings, wallets: [...settings.wallets, newWallet] });
    } else {
      const newCat: CategoryConfig = {
        id: 'c' + Date.now(),
        name: newItemName.trim(),
        color: newItemColor
      };
      onUpdate({ ...settings, categories: [...settings.categories, newCat] });
    }

    setNewItemName('');
    setIsAdding(false);
    showFeedback("Aggiunto con successo!");
  };

  const startEditing = (item: CategoryConfig) => {
    setEditingId(item.id);
    setEditName(item.name);
    setEditColor(item.color || '#10b981');
  };

  const saveEdit = () => {
    if (!editName.trim()) return;
    const newCats = settings.categories.map(c => 
      c.id === editingId ? { ...c, name: editName, color: editColor } : c
    );
    onUpdate({ ...settings, categories: newCats });
    setEditingId(null);
    showFeedback("Modifica salvata!");
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !onImport) return;

    setIsImporting(true);
    try {
      const { imported } = await onImport(file);
      showFeedback(`${imported} spese importate!`);
    } catch (err: any) {
      alert("Errore importazione: " + err.message);
    } finally {
      setIsImporting(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  if (view === 'history') return <HistoryView expenses={expenses} onClose={() => setView('main')} currency={settings.currency} />;

  if (view === 'wallets') return (
    <div className="fixed inset-0 bg-white dark:bg-gray-900 z-[80] overflow-y-auto animate-in slide-in-from-right duration-300">
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        <button type="button" onClick={() => { setView('main'); setIsAdding(false); }} className="flex items-center gap-2 text-emerald-600 font-bold mb-6 hover:translate-x-[-4px] transition-transform"><ChevronLeft /> {tNav.settings}</button>
        <h2 className="text-3xl font-black dark:text-white mb-6">I tuoi Portafogli</h2>
        <div className="space-y-4">
          {settings.wallets.map(w => (
            <div key={w.id} className="flex items-center justify-between p-6 bg-white dark:bg-gray-800 rounded-3xl border border-emerald-50 dark:border-gray-700 shadow-sm">
              <div className="flex items-center gap-4 font-bold dark:text-white">
                <div className="p-3 bg-emerald-50 dark:bg-emerald-900/20 rounded-2xl text-emerald-500"><Wallet size={20} /></div>
                <span>{w.name}</span>
              </div>
              <button onClick={() => onUpdate({ ...settings, wallets: settings.wallets.filter(x => x.id !== w.id) })} className="p-3 text-red-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-2xl transition-all">
                <Trash2 size={20} />
              </button>
            </div>
          ))}
          {isAdding ? (
            <div className="space-y-4 p-6 bg-emerald-50 dark:bg-emerald-900/10 rounded-[2.5rem] border-2 border-emerald-500 animate-in zoom-in-95 duration-200">
              <input autoFocus type="text" value={newItemName} onChange={(e) => setNewItemName(e.target.value)} placeholder="Nome portafoglio" className="w-full px-5 py-4 rounded-2xl bg-white dark:bg-gray-700 border-none outline-none dark:text-white font-bold" />
              <div className="flex gap-2">
                <button type="button" onClick={() => handleAddItem('wallet')} className="flex-1 py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-lg">Salva</button>
                <button type="button" onClick={() => setIsAdding(false)} className="px-6 py-4 bg-white dark:bg-gray-600 text-gray-400 rounded-2xl font-bold">Annulla</button>
              </div>
            </div>
          ) : (
            <button type="button" onClick={() => setIsAdding(true)} className="w-full py-5 bg-emerald-500 text-white rounded-[2rem] font-bold flex items-center justify-center gap-2 mt-4 shadow-lg hover:bg-emerald-600 transition-all active:scale-95">
              <Plus size={24} /> Aggiungi Portafoglio
            </button>
          )}
        </div>
      </div>
    </div>
  );

  if (view === 'categories') return (
    <div className="fixed inset-0 bg-white dark:bg-gray-900 z-[80] overflow-y-auto animate-in slide-in-from-right duration-300">
      <div className="max-w-4xl mx-auto px-4 py-8 pb-24">
        <button type="button" onClick={() => { setView('main'); setIsAdding(false); }} className="flex items-center gap-2 text-emerald-600 font-bold mb-6 hover:translate-x-[-4px] transition-transform"><ChevronLeft /> {tNav.settings}</button>
        <h2 className="text-3xl font-black dark:text-white mb-6">Le tue Categorie</h2>
        <div className="space-y-4">
          {settings.categories.map(c => (
            <div key={c.id} className="p-6 bg-white dark:bg-gray-800 rounded-3xl border border-emerald-50 dark:border-gray-700 shadow-sm">
              {editingId === c.id ? (
                <div className="flex flex-col gap-4 animate-in fade-in duration-200">
                  <div className="flex items-center gap-4">
                    <input type="color" value={editColor} onChange={(e) => setEditColor(e.target.value)} className="w-12 h-12 border-none bg-transparent cursor-pointer rounded-full shrink-0" />
                    <input autoFocus type="text" value={editName} onChange={(e) => setEditName(e.target.value)} className="flex-1 px-4 py-3 bg-gray-50 dark:bg-gray-700 rounded-2xl border-none outline-none dark:text-white font-bold" />
                  </div>
                  <div className="flex gap-2">
                    <button onClick={saveEdit} className="flex-1 py-3 bg-emerald-500 text-white rounded-xl font-bold">Salva</button>
                    <button onClick={() => setEditingId(null)} className="px-6 py-3 bg-gray-100 dark:bg-gray-600 text-gray-500 rounded-xl font-bold">Annulla</button>
                  </div>
                </div>
              ) : (
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 rounded-2xl shadow-inner border border-white/20" style={{ backgroundColor: c.color || '#10b981' }}></div>
                    <span className="font-bold text-gray-800 dark:text-white text-lg">{c.name}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <button onClick={() => startEditing(c)} className="p-3 text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded-2xl transition-all"><Edit3 size={20} /></button>
                    {!c.isSubscriptionDefault && (
                      <button onClick={() => onUpdate({ ...settings, categories: settings.categories.filter(x => x.id !== c.id) })} className="p-3 text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-2xl transition-all"><Trash2 size={20} /></button>
                    )}
                  </div>
                </div>
              )}
            </div>
          ))}
          {isAdding ? (
            <div className="space-y-4 p-6 bg-emerald-50 dark:bg-emerald-900/10 rounded-[2.5rem] border-2 border-emerald-500 animate-in zoom-in-95 duration-200">
              <div className="flex items-center gap-4 bg-white dark:bg-gray-700 rounded-2xl p-2">
                <input type="color" value={newItemColor} onChange={(e) => setNewItemColor(e.target.value)} className="w-12 h-12 border-none bg-transparent cursor-pointer rounded-full" />
                <input autoFocus type="text" value={newItemName} onChange={(e) => setNewItemName(e.target.value)} placeholder="Nuova categoria" className="flex-1 bg-transparent border-none outline-none dark:text-white font-bold px-2" />
              </div>
              <div className="flex gap-2">
                <button type="button" onClick={() => handleAddItem('category')} className="flex-1 py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-lg">Crea</button>
                <button type="button" onClick={() => setIsAdding(false)} className="px-6 py-4 bg-white dark:bg-gray-600 text-gray-400 rounded-2xl font-bold">Annulla</button>
              </div>
            </div>
          ) : (
            <button type="button" onClick={() => setIsAdding(true)} className="w-full py-5 bg-emerald-500 text-white rounded-[2rem] font-bold flex items-center justify-center gap-2 mt-4 shadow-lg hover:bg-emerald-600 transition-all active:scale-95">
              <Plus size={24} /> Aggiungi Categoria
            </button>
          )}
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
      {feedback && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[100] px-6 py-3 bg-emerald-500 text-white rounded-2xl shadow-2xl flex items-center gap-2 animate-in fade-in zoom-in duration-300">
          <CheckCircle2 size={16} />
          <span className="font-bold text-xs uppercase tracking-wider">{feedback}</span>
        </div>
      )}

      <div className="bg-white dark:bg-gray-800 p-6 md:p-8 rounded-[2.5rem] border border-emerald-100 dark:border-gray-700 shadow-sm">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
