);

import React, { useState, useEffect } from 'react';
import { Shield, Users, Bell, Ban, Search, LogOut, CheckCircle2, X, Send, AlertTriangle, Loader2, Database, Terminal, Copy, Key, Check, Mail } from 'lucide-react';
import { db, auth, supabase, supabaseAdmin } from '../services/supabase';
import { ConfirmModal } from './ConfirmModal';
import { format } from 'date-fns';
import it from 'date-fns/locale/it';

interface AdminUser {
  id: string;
  email: string;
  display_name: string;
  status: 'active' | 'disabled';
  last_login: string;
  role: 'user' | 'admin';
}

interface AdminDashboardProps {
  onLogout: () => void;
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout }) => {
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState<AdminUser | null>(null);
  const [showNotifyModal, setShowNotifyModal] = useState(false);
  const [showSqlModal, setShowSqlModal] = useState(false);
  const [notificationText, setNotificationText] = useState('');
  const [toast, setToast] = useState<{msg: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Stato per il nuovo Modal di Reset Password (Email + ID)
  const [userToReset, setUserToReset] = useState<{email: string, id: string} | null>(null);
  const [isResetting, setIsResetting] = useState(false);
  const [tempPassword, setTempPassword] = useState('');

  // Configurazione per il modal di conferma stato (attiva/disattiva)
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    userId: string;
    userName: string;
    newStatus: 'active' | 'disabled';
  }>({ isOpen: false, userId: '', userName: '', newStatus: 'active' });

  const fetchUsers = async () => {
    setLoading(true);
    setError(null);
    try {
        const data = await db.getAllProfiles();
        setUsers(data as AdminUser[]);
    } catch (err: any) {
        console.error("Errore fetch:", err);
        setError("Errore nel caricamento dal database.");
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => { fetchUsers(); }, []);

  const showToast = (msg: string, type: 'success' | 'error' | 'warning' = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleToggleStatusRequest = (user: AdminUser, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    setConfirmConfig({
      isOpen: true,
      userId: user.id,
      userName: user.display_name || user.email,
      newStatus: user.status === 'active' ? 'disabled' : 'active'
    });
  };

  const executeToggleStatus = async () => {
    const { userId, newStatus } = confirmConfig;
    setConfirmConfig(prev => ({ ...prev, isOpen: false }));

    try {
        const data = await db.updateUserStatus(userId, newStatus);
        if (!data || data.length === 0) {
             showToast("Errore: Il database ha rifiutato la modifica (Verifica Policy SQL)", "error");
             return;
        }
        setUsers(prev => prev.map(u => u.id === userId ? { ...u, status: newStatus } : u));
        showToast(`Utente ${newStatus === 'active' ? 'riattivato' : 'disabilitato'} con successo`);
    } catch (err: any) {
        console.error("Errore durante l'aggiornamento:", err);
        showToast("Errore: " + err.message, "error");
    }
  };

  const handleSendQuickNotification = async (targetUser: AdminUser) => {
    const title = prompt("Titolo della notifica:");
    const message = prompt("Testo del messaggio:");
    if (!title || !message) return;

    try {
      const { error } = await supabaseAdmin
        .from('notifications')
        .insert([{ user_id: targetUser.id, title, message }]);

      if (error) throw error;
      showToast(`Notifica inviata con successo!`);
    } catch (err: any) {
      showToast("Errore invio: " + err.message, "error");
    }
  };

  const confirmResetPassword = async () => {
    if (!userToReset) return;
    setIsResetting(true);

    try {
      const { error } = await supabase.auth.resetPasswordForEmail(userToReset.email, {
        redirectTo: window.location.origin,
      });
      if (error) throw error;
      showToast(`📧 Email di reset inviata a ${userToReset.email}!`, 'success');
      setUserToReset(null);
    } catch (err: any) {
      showToast('Errore reset password: ' + err.message, 'error');
    } finally {
      setIsResetting(false);
    }
  };

  const handleSetTempPassword = async () => {
    if (!userToReset || !tempPassword) return;
    setIsResetting(true);

    try {
      // Usiamo il client Admin con la Service Role Key per avere i permessi necessari
      const { error } = await supabaseAdmin.auth.admin.updateUserById(
        userToReset.id,
        { password: tempPassword }
      );

      if (error) throw error;

      showToast(`✅ Password cambiata con successo per ${userToReset.email}!`, 'success');
      setUserToReset(null);
      setTempPassword('');
    } catch (err: any) {
      console.error("Errore Admin Auth:", err);
      showToast('Errore setup password: ' + err.message, 'error');
    } finally {
      setIsResetting(false);
    }
  };

  const filteredUsers = users.filter(u => 
    (u.email || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
    (u.display_name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white pb-20 md:pb-0">
      {toast && (
        <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[150] px-6 py-3 rounded-2xl shadow-xl flex items-center gap-2 animate-in slide-in-from-top-4 ${
          toast.type === 'success' ? 'bg-emerald-600 text-white' : 
          toast.type === 'warning' ? 'bg-amber-500 text-white' : 'bg-red-500 text-white'
        }`}>
          {toast.type === 'success' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
          <span className="font-bold text-sm">{toast.msg}</span>
        </div>
      )}

      <header className="bg-white dark:bg-gray-800 border-b sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Shield className="text-emerald-500" size={32} />
            <h1 className="text-xl font-black">MintFlow <span className="text-emerald-500">Admin</span></h1>
          </div>
          <div className="flex items-center gap-4">
            <button onClick={() => setShowSqlModal(true)} title="Database Schema" className="p-2 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 rounded-xl"><Database size={20} /></button>
            <button onClick={onLogout} className="flex items-center gap-2 px-4 py-2 bg-gray-100 dark:bg-gray-700 rounded-xl font-bold"><LogOut size={20} /> Esci</button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8">
        <div className="mb-8 relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
          <input type="text" placeholder="Cerca utente per nome o email..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white dark:bg-gray-800 border-none shadow-sm outline-none focus:ring-2 focus:ring-emerald-500" />
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-gray-50 dark:bg-gray-700/50">
              <tr>
                <th className="px-6 py-4 font-bold text-xs uppercase tracking-wider text-gray-500 dark:text-gray-400">Utente</th>
                <th className="px-6 py-4 font-bold text-xs uppercase tracking-wider text-gray-500 dark:text-gray-400">Stato</th>
                <th className="px-6 py-4 font-bold text-xs uppercase tracking-wider text-gray-500 dark:text-gray-400">Azioni</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
              {loading ? (
                <tr><td colSpan={3} className="p-12 text-center"><Loader2 className="animate-spin mx-auto text-emerald-500" /></td></tr>
              ) : filteredUsers.length > 0 ? (
                filteredUsers.map(user => (
                  <tr key={user.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                    <td className="px-6 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-emerald-500 rounded-full flex items-center justify-center text-white font-bold shrink-0">{(user.display_name || user.email).charAt(0).toUpperCase()}</div>
                        <div className="min-w-0">
                          <div className="font-bold truncate">{user.display_name}</div>
                          <div className="text-sm text-gray-500 truncate">{user.email}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-6">
                      <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${user.status === 'active' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'}`}>{user.status}</span>
                    </td>
                    <td className="px-6 py-6">
                      {user.email !== 'admin@mintflow.com' && (
                        <div className="flex gap-2">
                          <button 
                            onClick={() => setUserToReset({ email: user.email, id: user.id })}
                            className="p-3 bg-amber-50 dark:bg-amber-900/20 text-amber-500 rounded-2xl hover:scale-110 transition-transform active:scale-95 shadow-sm"
                            title="Sicurezza Account"
                          >
                            <Key size={20} />
                          </button>
                          <button 
                            onClick={() => handleSendQuickNotification(user)} 
                            className="p-3 bg-blue-50 dark:bg-blue-900/20 text-blue-500 rounded-2xl hover:scale-110 transition-transform active:scale-95 shadow-sm"
                            title="Invia Notifica"
                          >
                            <Bell size={20} />
                          </button>
                          <button 
                            onClick={e => handleToggleStatusRequest(user, e)} 
                            className={`p-3 rounded-2xl transition-all hover:scale-110 active:scale-95 shadow-sm ${
                              user.status === 'active' 
                                ? 'text-gray-400 bg-gray-100 hover:text-red-500 hover:bg-red-50 dark:bg-gray-700' 
                                : 'text-white bg-emerald-500 shadow-emerald-100'
                            }`}
                            title={user.status === 'active' ? "Disabilita Account" : "Attiva Account"}
                          >
                            {user.status === 'active' ? <Ban size={20} /> : <CheckCircle2 size={20} />}
                          </button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))
              ) : (
                <tr><td colSpan={3} className="p-12 text-center text-gray-400">Nessun utente trovato</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </main>

      {/* MODAL RESET PASSWORD & SICUREZZA */}
      {userToReset && (
        <div className="fixed inset-0 z-[160] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-in fade-in duration-200">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-sm p-8 shadow-2xl animate-in zoom-in-95 border border-amber-100 dark:border-gray-700 relative overflow-hidden">
            <button onClick={() => { setUserToReset(null); setTempPassword(''); }} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 transition-colors"><X size={24} /></button>

            <div className="bg-amber-100 dark:bg-amber-900/30 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 text-amber-600 shadow-inner">
              <Key size={32} />
            </div>

            <h2 className="text-2xl font-black text-gray-800 dark:text-white mb-2 tracking-tight">Sicurezza Account</h2>
            <p className="text-gray-500 dark:text-gray-400 mb-8 font-medium leading-relaxed">
              Gestione accesso per: <br/>
              <span className="font-bold text-emerald-600 dark:text-emerald-400">{userToReset.email}</span>
            </p>

            <div className="space-y-4">
              <button 
                onClick={confirmResetPassword}
                disabled={isResetting}
                className="w-full py-4 bg-amber-500 text-white rounded-2xl font-bold shadow-lg shadow-amber-200 dark:shadow-none hover:bg-amber-600 active:scale-95 transition-all flex items-center justify-center gap-2"
              >
                {isResetting ? <Loader2 className="animate-spin" size={18} /> : <Mail size={18} />}
                Invia Email di Reset
              </button>

              <div className="relative my-6 text-center">
                <hr className="border-gray-100 dark:border-gray-700" />
                <span className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white dark:bg-gray-800 px-3 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Oppure imposta subito</span>
              </div>

              <div className="space-y-3">
                <input 
                  type="text"
                  placeholder="Password temporanea..."
                  value={tempPassword}
                  onChange={(e) => setTempPassword(e.target.value)}
                  className="w-full px-5 py-4 bg-gray-50 dark:bg-gray-700 rounded-2xl border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white font-medium"
                />
                <button 
                  onClick={handleSetTempPassword}
                  disabled={isResetting || !tempPassword}
                  className="w-full py-4 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-2xl font-bold disabled:opacity-50 transition-all flex items-center justify-center gap-2 active:scale-95"
                >
                  {isResetting ? <Loader2 className="animate-spin" size={18} /> : <Check size={18} />}
                  Aggiorna Password Ora
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* SQL MODAL */}
      {showSqlModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-2xl p-8 max-h-[90vh] overflow-y-auto animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
               <h3 className="text-xl font-bold flex gap-2"><Terminal className="text-emerald-500" /> Script SQL Supabase</h3>
               <button onClick={() => setShowSqlModal(false)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>
            <p className="text-sm text-gray-500 mb-4 font-medium">Copia questi comandi nel SQL Editor di Supabase per attivare il sistema di notifiche.</p>
            <pre className="bg-gray-900 text-emerald-400 p-5 rounded-xl text-xs overflow-x-auto mb-6 whitespace-pre-wrap leading-relaxed">
{`CREATE TABLE IF NOT EXISTS public.notifications (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    is_read BOOLEAN DEFAULT false,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);

ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users view own" ON public.notifications FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Admin insert" ON public.notifications FOR INSERT WITH CHECK (true);
CREATE POLICY "Users delete own" ON public.notifications FOR DELETE USING (auth.uid() = user_id);
CREATE POLICY "Users update own read status" ON public.notifications FOR UPDATE USING (auth.uid() = user_id);`}
            </pre>
            <button onClick={() => setShowSqlModal(false)} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-lg shadow-emerald-200 dark:shadow-none transition-all active:scale-95">Ho capito, chiudi</button>
          </div>
        </div>
      )}

      <ConfirmModal 
        isOpen={confirmConfig.isOpen}
        title={confirmConfig.newStatus === 'disabled' ? "Disabilita Utente" : "Riattiva Utente"}
        message={`Sei sicuro di voler cambiare lo stato di ${confirmConfig.userName} a ${confirmConfig.newStatus === 'disabled' ? 'Disabilitato' : 'Attivo'}?`}
        confirmText={confirmConfig.newStatus === 'disabled' ? "Sì, Blocca" : "Sì, Attiva"}
        type={confirmConfig.newStatus === 'disabled' ? 'danger' : 'success'}
        onConfirm={executeToggleStatus}
        onCancel={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}
      />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Shield, Users, Bell, Ban, Search, LogOut, CheckCircle2, X, Send, AlertTriangle, Loader2, Database, Terminal, Copy, Key, Check, Mail, MoreVertical } from 'lucide-react';
import { db, auth, supabase, supabaseAdmin } from '../services/supabase';
import { ConfirmModal } from './ConfirmModal';
import { format } from 'date-fns';
import it from 'date-fns/locale/it';

interface AdminUser {
  id: string;
  email: string;
  display_name: string;
  status: 'active' | 'disabled';
  last_login: string;
  role: 'user' | 'admin';
}

interface AdminDashboardProps {
  onLogout: () => void;
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout }) => {
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showSqlModal, setShowSqlModal] = useState(false);
  const [toast, setToast] = useState<{msg: string, type: 'success' | 'error' | 'warning'} | null>(null);

  const [userToReset, setUserToReset] = useState<{email: string, id: string} | null>(null);
  const [isResetting, setIsResetting] = useState(false);
  const [tempPassword, setTempPassword] = useState('');

  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    userId: string;
    userName: string;
    newStatus: 'active' | 'disabled';
  }>({ isOpen: false, userId: '', userName: '', newStatus: 'active' });

  const fetchUsers = async () => {
    setLoading(true);
    setError(null);
    try {
        const data = await db.getAllProfiles();
        setUsers(data as AdminUser[]);
    } catch (err: any) {
        console.error("Errore fetch:", err);
        setError("Errore nel caricamento dal database.");
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => { fetchUsers(); }, []);

  const showToast = (msg: string, type: 'success' | 'error' | 'warning' = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleToggleStatusRequest = (user: AdminUser, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    setConfirmConfig({
      isOpen: true,
      userId: user.id,
      userName: user.display_name || user.email,
      newStatus: user.status === 'active' ? 'disabled' : 'active'
    });
  };

  const executeToggleStatus = async () => {
    const { userId, newStatus } = confirmConfig;
    setConfirmConfig(prev => ({ ...prev, isOpen: false }));

    try {
        const data = await db.updateUserStatus(userId, newStatus);
        if (!data || data.length === 0) {
             showToast("Errore: Il database ha rifiutato la modifica (Verifica Policy SQL)", "error");
             return;
        }
        setUsers(prev => prev.map(u => u.id === userId ? { ...u, status: newStatus } : u));
        showToast(`Utente ${newStatus === 'active' ? 'riattivato' : 'disabilitato'} con successo`);
    } catch (err: any) {
        console.error("Errore durante l'aggiornamento:", err);
        showToast("Errore: " + err.message, "error");
    }
  };

  const handleSendQuickNotification = async (targetUser: AdminUser) => {
    const title = prompt("Titolo della notifica:");
    if (title === null) return;
    const message = prompt("Testo del messaggio:");
    if (message === null) return;

    if (!title.trim() || !message.trim()) {
      showToast("Titolo e messaggio obbligatori", "warning");
      return;
    }

    try {
      const { error } = await supabaseAdmin
        .from('notifications')
        .insert([{ user_id: targetUser.id, title, message }]);

      if (error) throw error;
      showToast(`Notifica inviata a ${targetUser.display_name || targetUser.email}!`);
    } catch (err: any) {
      showToast("Errore invio: " + err.message, "error");
    }
  };

  const confirmResetPassword = async () => {
    if (!userToReset) return;
    setIsResetting(true);

    try {
      const { error } = await supabase.auth.resetPasswordForEmail(userToReset.email, {
        redirectTo: window.location.origin,
      });
      if (error) throw error;
      showToast(`📧 Email di reset inviata a ${userToReset.email}!`, 'success');
      setUserToReset(null);
    } catch (err: any) {
      showToast('Errore reset password: ' + err.message, 'error');
    } finally {
      setIsResetting(false);
    }
  };

  const handleSetTempPassword = async () => {
    if (!userToReset || !tempPassword) return;
    setIsResetting(true);

    try {
      const { error } = await supabaseAdmin.auth.admin.updateUserById(
        userToReset.id,
        { password: tempPassword }
      );

      if (error) throw error;

      showToast(`✅ Password cambiata con successo per ${userToReset.email}!`, 'success');
      setUserToReset(null);
      setTempPassword('');
    } catch (err: any) {
      console.error("Errore Admin Auth:", err);
      showToast('Errore setup password: ' + err.message, 'error');
    } finally {
      setIsResetting(false);
    }
  };

  const filteredUsers = users.filter(u => 
    (u.email || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
    (u.display_name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white pb-24 md:pb-8">
      {toast && (
        <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[150] px-6 py-3 rounded-2xl shadow-xl flex items-center gap-2 animate-in slide-in-from-top-4 ${
          toast.type === 'success' ? 'bg-emerald-600 text-white' : 
          toast.type === 'warning' ? 'bg-amber-500 text-white' : 'bg-red-500 text-white'
        }`}>
          {toast.type === 'success' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
          <span className="font-bold text-sm">{toast.msg}</span>
        </div>
      )}

      {/* HEADER RESPONSIVE */}
      <header className="bg-white dark:bg-gray-800 border-b sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 h-16 md:h-20 flex items-center justify-between">
          <div className="flex items-center gap-2 md:gap-3">
            <Shield className="text-emerald-500" size={24} md:size={32} />
            <h1 className="text-lg md:text-xl font-black">MintFlow <span className="text-emerald-500 hidden sm:inline">Admin</span></h1>
          </div>
          <div className="flex items-center gap-2 md:gap-4">
            <button onClick={() => setShowSqlModal(true)} title="Database Schema" className="p-2 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 rounded-xl">
              <Database size={18} md:size={20} />
            </button>
            <button onClick={onLogout} className="flex items-center gap-2 px-3 md:px-4 py-2 bg-gray-100 dark:bg-gray-700 rounded-xl font-bold text-sm">
              <LogOut size={18} md:size={20} /> <span className="hidden sm:inline">Esci</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-6 md:py-8">
        <div className="mb-6 md:mb-8 relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Cerca utente..." 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            className="w-full pl-12 pr-4 py-3 md:py-4 rounded-2xl bg-white dark:bg-gray-800 border-none shadow-sm outline-none focus:ring-2 focus:ring-emerald-500 text-sm" 
          />
        </div>

        {/* VISTA DESKTOP (Tabella) */}
        <div className="hidden md:block bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-gray-50 dark:bg-gray-700/50">
              <tr>
                <th className="px-6 py-4 font-bold text-xs uppercase tracking-wider text-gray-500 dark:text-gray-400">Utente</th>
                <th className="px-6 py-4 font-bold text-xs uppercase tracking-wider text-gray-500 dark:text-gray-400">Stato</th>
                <th className="px-6 py-4 font-bold text-xs uppercase tracking-wider text-gray-500 dark:text-gray-400">Azioni</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
              {loading ? (
                <tr><td colSpan={3} className="p-12 text-center"><Loader2 className="animate-spin mx-auto text-emerald-500" /></td></tr>
              ) : filteredUsers.length > 0 ? (
                filteredUsers.map(user => (
                  <tr key={user.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                    <td className="px-6 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-emerald-500 rounded-full flex items-center justify-center text-white font-bold shrink-0">{(user.display_name || user.email).charAt(0).toUpperCase()}</div>
                        <div className="min-w-0">
                          <div className="font-bold truncate">{user.display_name}</div>
                          <div className="text-sm text-gray-500 truncate">{user.email}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-6">
                      <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${user.status === 'active' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'}`}>{user.status}</span>
                    </td>
                    <td className="px-6 py-6">
                      {user.email !== 'admin@mintflow.com' && (
                        <div className="flex gap-2">
                          <button onClick={() => setUserToReset({ email: user.email, id: user.id })} className="p-2.5 bg-amber-50 dark:bg-amber-900/20 text-amber-500 rounded-xl hover:scale-110 transition-transform shadow-sm" title="Sicurezza Account"><Key size={18} /></button>
                          <button onClick={() => handleSendQuickNotification(user)} className="p-2.5 bg-blue-50 dark:bg-blue-900/20 text-blue-500 rounded-xl hover:scale-110 transition-transform shadow-sm" title="Invia Notifica"><Bell size={18} /></button>
                          <button onClick={e => handleToggleStatusRequest(user, e)} className={`p-2.5 rounded-xl transition-all hover:scale-110 shadow-sm ${user.status === 'active' ? 'text-gray-400 bg-gray-100 hover:text-red-500 hover:bg-red-50 dark:bg-gray-700' : 'text-white bg-emerald-500 shadow-emerald-100'}`} title={user.status === 'active' ? "Disabilita Account" : "Attiva Account"}>{user.status === 'active' ? <Ban size={18} /> : <CheckCircle2 size={18} />}</button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))
              ) : (
                <tr><td colSpan={3} className="p-12 text-center text-gray-400">Nessun utente trovato</td></tr>
              )}
            </tbody>
          </table>
        </div>

        {/* VISTA MOBILE (Card) */}
        <div className="md:hidden space-y-4">
          {loading ? (
            <div className="p-12 text-center"><Loader2 className="animate-spin mx-auto text-emerald-500" /></div>
          ) : filteredUsers.length > 0 ? (
            filteredUsers.map(user => (
              <div key={user.id} className="bg-white dark:bg-gray-800 p-5 rounded-[2rem] border border-emerald-50 dark:border-gray-700 shadow-sm space-y-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-12 h-12 bg-emerald-500 rounded-2xl flex items-center justify-center text-white font-black text-lg shrink-0">{(user.display_name || user.email).charAt(0).toUpperCase()}</div>
                    <div className="min-w-0">
                      <h4 className="font-bold text-gray-800 dark:text-white truncate">{user.display_name}</h4>
                      <p className="text-[10px] text-gray-400 truncate">{user.email}</p>
                    </div>
                  </div>
                  <span className={`px-2 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest ${user.status === 'active' ? 'bg-emerald-50 text-emerald-600 dark:bg-emerald-900/30' : 'bg-red-50 text-red-600 dark:bg-red-900/30'}`}>{user.status}</span>
                </div>

                {user.email !== 'admin@mintflow.com' && (
                  <div className="grid grid-cols-3 gap-2 pt-2">
                    <button onClick={() => handleSendQuickNotification(user)} className="flex flex-col items-center justify-center gap-1.5 p-3 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-2xl active:scale-95 transition-all">
                      <Bell size={18} />
                      <span className="text-[8px] font-bold uppercase tracking-tighter">Notifica</span>
                    </button>
                    <button onClick={() => setUserToReset({ email: user.email, id: user.id })} className="flex flex-col items-center justify-center gap-1.5 p-3 bg-amber-50 dark:bg-amber-900/20 text-amber-600 dark:text-amber-400 rounded-2xl active:scale-95 transition-all">
                      <Key size={18} />
                      <span className="text-[8px] font-bold uppercase tracking-tighter">Reset</span>
                    </button>
                    <button onClick={e => handleToggleStatusRequest(user, e)} className={`flex flex-col items-center justify-center gap-1.5 p-3 rounded-2xl active:scale-95 transition-all ${user.status === 'active' ? 'bg-red-50 dark:bg-red-900/20 text-red-600' : 'bg-emerald-500 text-white shadow-lg shadow-emerald-100'}`}>
                      {user.status === 'active' ? <Ban size={18} /> : <CheckCircle2 size={18} />}
                      <span className="text-[8px] font-bold uppercase tracking-tighter">{user.status === 'active' ? 'Blocca' : 'Attiva'}</span>
                    </button>
                  </div>
                )}
              </div>
            ))
          ) : (
            <div className="p-12 text-center text-gray-400">Nessun utente trovato</div>
          )}
        </div>
      </main>

      {/* MODALI RIMANGONO UGUALI */}
      {userToReset && (
        <div className="fixed inset-0 z-[160] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-in fade-in duration-200">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-sm p-8 shadow-2xl animate-in zoom-in-95 border border-amber-100 dark:border-gray-700 relative overflow-hidden">
            <button onClick={() => { setUserToReset(null); setTempPassword(''); }} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 transition-colors"><X size={24} /></button>
            <div className="bg-amber-100 dark:bg-amber-900/30 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 text-amber-600 shadow-inner"><Key size={32} /></div>
            <h2 className="text-2xl font-black text-gray-800 dark:text-white mb-2 tracking-tight">Sicurezza Account</h2>
            <p className="text-gray-500 dark:text-gray-400 mb-8 font-medium leading-relaxed">Gestione accesso per: <br/><span className="font-bold text-emerald-600 dark:text-emerald-400">{userToReset.email}</span></p>
            <div className="space-y-4">
              <button onClick={confirmResetPassword} disabled={isResetting} className="w-full py-4 bg-amber-500 text-white rounded-2xl font-bold shadow-lg shadow-amber-200 dark:shadow-none hover:bg-amber-600 active:scale-95 transition-all flex items-center justify-center gap-2">{isResetting ? <Loader2 className="animate-spin" size={18} /> : <Mail size={18} />}Invia Email di Reset</button>
              <div className="relative my-6 text-center"><hr className="border-gray-100 dark:border-gray-700" /><span className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-white dark:bg-gray-800 px-3 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Oppure imposta subito</span></div>
              <div className="space-y-3">
                <input type="text" placeholder="Password temporanea..." value={tempPassword} onChange={(e) => setTempPassword(e.target.value)} className="w-full px-5 py-4 bg-gray-50 dark:bg-gray-700 rounded-2xl border-2 border-transparent focus:border-emerald-500 outline-none dark:text-white font-medium" />
                <button onClick={handleSetTempPassword} disabled={isResetting || !tempPassword} className="w-full py-4 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-2xl font-bold disabled:opacity-50 transition-all flex items-center justify-center gap-2 active:scale-95">{isResetting ? <Loader2 className="animate-spin" size={18} /> : <Check size={18} />}Aggiorna Password Ora</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showSqlModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] w-full max-w-2xl p-8 max-h-[90vh] overflow-y-auto animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
               <h3 className="text-xl font-bold flex gap-2"><Terminal className="text-emerald-500" /> Script SQL Supabase</h3>
               <button onClick={() => setShowSqlModal(false)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>
            <p className="text-sm text-gray-500 mb-4 font-medium">Copia questi comandi nel SQL Editor di Supabase per attivare il sistema di notifiche.</p>
            <pre className="bg-gray-900 text-emerald-400 p-5 rounded-xl text-xs overflow-x-auto mb-6 whitespace-pre-wrap leading-relaxed">
{`CREATE TABLE IF NOT EXISTS public.notifications (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    is_read BOOLEAN DEFAULT false,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);

ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users view own" ON public.notifications FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Admin insert" ON public.notifications FOR INSERT WITH CHECK (true);
CREATE POLICY "Users delete own" ON public.notifications FOR DELETE USING (auth.uid() = user_id);
CREATE POLICY "Users update own read status" ON public.notifications FOR UPDATE USING (auth.uid() = user_id);`}
            </pre>
            <button onClick={() => setShowSqlModal(false)} className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-bold shadow-lg shadow-emerald-200 dark:shadow-none transition-all active:scale-95">Ho capito, chiudi</button>
          </div>
        </div>
      )}

      <ConfirmModal 
        isOpen={confirmConfig.isOpen}
        title={confirmConfig.newStatus === 'disabled' ? "Disabilita Utente" : "Riattiva Utente"}
        message={`Sei sicuro di voler cambiare lo stato di ${confirmConfig.userName} a ${confirmConfig.newStatus === 'disabled' ? 'Disabilitato' : 'Attivo'}?`}
        confirmText={confirmConfig.newStatus === 'disabled' ? "Sì, Blocca" : "Sì, Attiva"}
        type={confirmConfig.newStatus === 'disabled' ? 'danger' : 'success'}
        onConfirm={executeToggleStatus}
        onCancel={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}
      />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Shield, Users, Bell, Ban, Search, LogOut, CheckCircle2, X, Send, AlertTriangle, Loader2, Database, Terminal, Copy, Key, Check, Mail, MoreVertical } from 'lucide-react';
import { db, auth, supabase, supabaseAdmin } from '../services/supabase';
import { ConfirmModal } from './ConfirmModal';
import { format } from 'date-fns';
import it from 'date-fns/locale/it';

interface AdminUser {
  id: string;
  email: string;
  display_name: string;
  status: 'active' | 'disabled';
  last_login: string;
  role: 'user' | 'admin';
}

interface AdminDashboardProps {
  onLogout: () => void;
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout }) => {
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showSqlModal, setShowSqlModal] = useState(false);
  const [toast, setToast] = useState<{msg: string, type: 'success' | 'error' | 'warning'} | null>(null);

  // Stati per l'invio notifiche
  const [isNotifyModalOpen, setIsNotifyModalOpen] = useState(false);
  const [targetUser, setTargetUser] = useState<AdminUser | null>(null);
  const [notifyTitle, setNotifyTitle] = useState('Messaggio da MintFlow');
  const [notifyBody, setNotifyBody] = useState('');
  const [isSendingNotify, setIsSendingNotify] = useState(false);

  const [userToReset, setUserToReset] = useState<{email: string, id: string} | null>(null);
  const [isResetting, setIsResetting] = useState(false);
  const [tempPassword, setTempPassword] = useState('');

  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    userId: string;
    userName: string;
    newStatus: 'active' | 'disabled';
  }>({ isOpen: false, userId: '', userName: '', newStatus: 'active' });

  const fetchUsers = async () => {
    setLoading(true);
    setError(null);
    try {
        const data = await db.getAllProfiles();
        setUsers(data as AdminUser[]);
    } catch (err: any) {
        console.error("Errore fetch:", err);
        setError("Errore nel caricamento dal database.");
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => { fetchUsers(); }, []);

  const showToast = (msg: string, type: 'success' | 'error' | 'warning' = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleToggleStatusRequest = (user: AdminUser, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    setConfirmConfig({
      isOpen: true,
      userId: user.id,
      userName: user.display_name || user.email,
      newStatus: user.status === 'active' ? 'disabled' : 'active'
    });
  };

  const executeToggleStatus = async () => {
    const { userId, newStatus } = confirmConfig;
    setConfirmConfig(prev => ({ ...prev, isOpen: false }));

    try {
        const data = await db.updateUserStatus(userId, newStatus);
        if (!data || data.length === 0) {
             showToast("Errore: Il database ha rifiutato la modifica (Verifica Policy SQL)", "error");
             return;
        }
        setUsers(prev => prev.map(u => u.id === userId ? { ...u, status: newStatus } : u));
        showToast(`Utente ${newStatus === 'active' ? 'riattivato' : 'disabilitato'} con successo`);
    } catch (err: any) {
        console.error("Errore durante l'aggiornamento:", err);
        showToast("Errore: " + err.message, "error");
    }
  };

  const openNotifyModal = (user: AdminUser) => {
    setTargetUser(user);
    setNotifyTitle('Messaggio da MintFlow');
    setNotifyBody('');
    setIsNotifyModalOpen(true);
  };

  const handleSendNotification = async () => {
    if (!targetUser || !notifyTitle.trim() || !notifyBody.trim()) {
      showToast("Titolo e corpo del messaggio sono obbligatori", "warning");
      return;
    }

    setIsSendingNotify(true);
    try {
      const { error } = await supabaseAdmin
        .from('notifications')
        .insert([{ 
          user_id: targetUser.id, 
          title: notifyTitle.trim(), 
          message: notifyBody.trim() 
        }]);

      if (error) throw error;
      showToast(`Notifica inviata a ${targetUser.display_name || targetUser.email}!`);
      setIsNotifyModalOpen(false);
    } catch (err: any) {
      showToast("Errore invio: " + err.message, "error");
    } finally {
      setIsSendingNotify(false);
    }
  };

  const confirmResetPassword = async () => {
    if (!userToReset) return;
    setIsResetting(true);

    try {
      const { error } = await supabase.auth.resetPasswordForEmail(userToReset.email, {
        redirectTo: window.location.origin,
      });
      if (error) throw error;
      showToast(`📧 Email di reset inviata a ${userToReset.email}!`, 'success');
      setUserToReset(null);
    } catch (err: any) {
      showToast('Errore reset password: ' + err.message, 'error');
    } finally {
      setIsResetting(false);
    }
  };

  const handleSetTempPassword = async () => {
    if (!userToReset || !tempPassword) return;
    setIsResetting(true);

    try {
      const { error } = await supabaseAdmin.auth.admin.updateUserById(
        userToReset.id,
        { password: tempPassword }
      );

      if (error) throw error;

