    if (!userToReset) return;
    setIsResetting(true);
    try {
      await supabase.auth.resetPasswordForEmail(userToReset.email, { redirectTo: window.location.origin });
      showToast(`Email di reset inviata a ${userToReset.email}`);
      setUserToReset(null);
